begin;
with patches as (select * from jsonb_to_recordset($imagepatch$[{"id":"6c7d1deb-880a-4e98-9d6c-3d370508bf86","expected_steps":[{"title":"Zwiebel, Knoblauch und Paprika andünsten","content":"Erhitze das Öl in einer Pfanne bei mittlerer Hitze. Dünste die Zwiebel, den Knoblauch und die Paprika 4 bis 5 Minuten an, bis sie weich und aromatisch sind.","image_alt":"Zwiebel, Knoblauch und Paprika dünsten in der Pfanne","image_url":null},{"title":"Das Fleisch garen","content":"Gib das Hackfleisch, den Kreuzkümmel, Salz, Pfeffer und das Chilipulver dazu. Gare 8 bis 10 Minuten, zerkleinere es dabei mit einem Holzlöffel, bis nichts Rosafarbenes mehr übrig ist und es 71 °C erreicht. Gieße das überschüssige Fett ab.","image_alt":"Mit Kreuzkümmel gewürztes Hackfleisch gart in der Pfanne","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Die Bohnen und den Reis erwärmen","content":"Erwärme die Bohnen und den Reis getrennt 3 bis 4 Minuten lang, bei Bedarf mit einem Esslöffel Wasser. Sie sollten heiß, aber nicht zu feucht sein, damit die Tortilla nicht reißt.","image_alt":"Heiße Bohnen und Reis in Tonschalen","image_url":null},{"title":"Die Tortillas erwärmen","content":"Erwärme jede Tortilla 20 bis 30 Sekunden pro Seite auf einem Comal oder einer trockenen Pfanne, bis sie geschmeidig ist und kleine goldene Flecken hat. Halte sie mit einem Tuch bedeckt.","image_alt":"Weizentortilla wird auf dem Comal erwärmt, bis sie geschmeidig ist","image_url":null},{"title":"Die Füllung platzieren","content":"Breite eine Tortilla auf dem Brett aus. Verteile ein Viertel des Reises, der Bohnen, des Fleisches, der Salsa und des Käses in der unteren Mitte, wobei du etwa 4 cm am Rand frei lässt. Überlade sie nicht.","image_alt":"Füllung in der unteren Mitte der Tortilla platziert","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Die Seiten einklappen","content":"Klappe die linke und rechte Seite der Tortilla zur Mitte hin über die Füllung, um zwei Falten zu bilden, die die Enden verschließen.","image_alt":"Seiten der Tortilla nach innen geklappt","image_url":null},{"title":"Das Burrito rollen","content":"Bringe den unteren Rand über die Füllung und rolle nach oben mit sanftem, festem Druck, bis es geschlossen ist. Lege die Naht nach unten.","image_alt":"Burrito wird gerollt, der untere Rand liegt über der Füllung","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Das Burrito anbraten","content":"Lege die Burritos mit der Naht nach unten in eine trockene Pfanne oder auf einen Comal. Brate sie 2 bis 3 Minuten pro Seite bei mittlerer Hitze an, bis die Tortilla geröstet ist und der Käse schmilzt.","image_alt":"Burrito brät mit der Naht nach unten auf dem Comal","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Schneiden und servieren","content":"Schneide jedes Burrito diagonal durch und serviere es sofort, mit roter Salsa, Guacamole und frischem Koriander.","image_alt":"Diagonal geschnittenes Burrito serviert mit Salsa und Guacamole","image_url":"/recetas/burrito/paso-09.webp"}],"new_steps":[{"title":"Zwiebel, Knoblauch und Paprika andünsten","content":"Erhitze das Öl in einer Pfanne bei mittlerer Hitze. Dünste die Zwiebel, den Knoblauch und die Paprika 4 bis 5 Minuten an, bis sie weich und aromatisch sind.","image_alt":"Zwiebel, Knoblauch und Paprika dünsten in der Pfanne","image_url":"/recetas/burrito/paso-completo-01-20261103.webp"},{"title":"Das Fleisch garen","content":"Gib das Hackfleisch, den Kreuzkümmel, Salz, Pfeffer und das Chilipulver dazu. Gare 8 bis 10 Minuten, zerkleinere es dabei mit einem Holzlöffel, bis nichts Rosafarbenes mehr übrig ist und es 71 °C erreicht. Gieße das überschüssige Fett ab.","image_alt":"Mit Kreuzkümmel gewürztes Hackfleisch gart in der Pfanne","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Die Bohnen und den Reis erwärmen","content":"Erwärme die Bohnen und den Reis getrennt 3 bis 4 Minuten lang, bei Bedarf mit einem Esslöffel Wasser. Sie sollten heiß, aber nicht zu feucht sein, damit die Tortilla nicht reißt.","image_alt":"Heiße Bohnen und Reis in Tonschalen","image_url":"/recetas/burrito/paso-completo-03-20261103.webp"},{"title":"Die Tortillas erwärmen","content":"Erwärme jede Tortilla 20 bis 30 Sekunden pro Seite auf einem Comal oder einer trockenen Pfanne, bis sie geschmeidig ist und kleine goldene Flecken hat. Halte sie mit einem Tuch bedeckt.","image_alt":"Weizentortilla wird auf dem Comal erwärmt, bis sie geschmeidig ist","image_url":"/recetas/burrito/paso-completo-04-20261103.webp"},{"title":"Die Füllung platzieren","content":"Breite eine Tortilla auf dem Brett aus. Verteile ein Viertel des Reises, der Bohnen, des Fleisches, der Salsa und des Käses in der unteren Mitte, wobei du etwa 4 cm am Rand frei lässt. Überlade sie nicht.","image_alt":"Füllung in der unteren Mitte der Tortilla platziert","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Die Seiten einklappen","content":"Klappe die linke und rechte Seite der Tortilla zur Mitte hin über die Füllung, um zwei Falten zu bilden, die die Enden verschließen.","image_alt":"Seiten der Tortilla nach innen geklappt","image_url":"/recetas/burrito/paso-completo-06-20261103.webp"},{"title":"Das Burrito rollen","content":"Bringe den unteren Rand über die Füllung und rolle nach oben mit sanftem, festem Druck, bis es geschlossen ist. Lege die Naht nach unten.","image_alt":"Burrito wird gerollt, der untere Rand liegt über der Füllung","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Das Burrito anbraten","content":"Lege die Burritos mit der Naht nach unten in eine trockene Pfanne oder auf einen Comal. Brate sie 2 bis 3 Minuten pro Seite bei mittlerer Hitze an, bis die Tortilla geröstet ist und der Käse schmilzt.","image_alt":"Burrito brät mit der Naht nach unten auf dem Comal","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Schneiden und servieren","content":"Schneide jedes Burrito diagonal durch und serviere es sofort, mit roter Salsa, Guacamole und frischem Koriander.","image_alt":"Diagonal geschnittenes Burrito serviert mit Salsa und Guacamole","image_url":"/recetas/burrito/paso-09.webp"}]},{"id":"3ce2903d-aaad-49ef-8cec-9b13afb745e2","expected_steps":[{"title":"Sauté the onion, garlic and bell pepper","content":"Heat the oil in a skillet over medium heat. Sauté the onion, garlic and bell pepper for 4 to 5 minutes, until soft and fragrant.","image_alt":"Onion, garlic and bell pepper sautéing in the skillet","image_url":null},{"title":"Cook the beef","content":"Add the ground beef, cumin, salt, pepper and chili powder. Cook for 8 to 10 minutes, breaking it up with a wooden spoon, until no pink remains and it reaches 160°F (71°C). Drain off the excess fat.","image_alt":"Ground beef seasoned with cumin cooking in the skillet","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Heat the beans and rice","content":"Heat the beans and rice separately for 3 to 4 minutes, with a tablespoon of water if needed. They should be hot but not too wet, so they don't tear the tortilla.","image_alt":"Hot beans and rice in clay bowls","image_url":null},{"title":"Heat the tortillas","content":"Heat each tortilla for 20 to 30 seconds per side on a dry griddle or skillet, until pliable with small golden spots. Keep them covered with a cloth.","image_alt":"Flour tortilla warming on the griddle until pliable","image_url":null},{"title":"Add the filling","content":"Lay a tortilla on the counter. Spread a quarter of the rice, beans, beef, salsa and cheese across the lower center, leaving about 4 cm (1.5 in) free at the edges. Don't overfill it.","image_alt":"Filling placed in the lower center of the tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Fold in the sides","content":"Fold the left and right sides of the tortilla toward the center, over the filling, to form two flaps that seal the ends.","image_alt":"Sides of the tortilla folded inward","image_url":null},{"title":"Roll the burrito","content":"Bring the bottom edge over the filling and roll upward with gentle, firm pressure, until closed. Leave the seam facing down.","image_alt":"Burrito being rolled with the bottom edge over the filling","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Brown the burrito","content":"Place the burritos in a dry skillet or griddle, seam side down. Brown them for 2 to 3 minutes per side over medium heat, until the tortilla is toasted and the cheese melts.","image_alt":"Burrito browning on the griddle, seam side down","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Cut and serve","content":"Cut each burrito diagonally and serve right away, with red salsa, guacamole and fresh cilantro.","image_alt":"Burrito cut diagonally, served with salsa and guacamole","image_url":"/recetas/burrito/paso-09.webp"}],"new_steps":[{"title":"Sauté the onion, garlic and bell pepper","content":"Heat the oil in a skillet over medium heat. Sauté the onion, garlic and bell pepper for 4 to 5 minutes, until soft and fragrant.","image_alt":"Onion, garlic and bell pepper sautéing in the skillet","image_url":"/recetas/burrito/paso-completo-01-20261103.webp"},{"title":"Cook the beef","content":"Add the ground beef, cumin, salt, pepper and chili powder. Cook for 8 to 10 minutes, breaking it up with a wooden spoon, until no pink remains and it reaches 160°F (71°C). Drain off the excess fat.","image_alt":"Ground beef seasoned with cumin cooking in the skillet","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Heat the beans and rice","content":"Heat the beans and rice separately for 3 to 4 minutes, with a tablespoon of water if needed. They should be hot but not too wet, so they don't tear the tortilla.","image_alt":"Hot beans and rice in clay bowls","image_url":"/recetas/burrito/paso-completo-03-20261103.webp"},{"title":"Heat the tortillas","content":"Heat each tortilla for 20 to 30 seconds per side on a dry griddle or skillet, until pliable with small golden spots. Keep them covered with a cloth.","image_alt":"Flour tortilla warming on the griddle until pliable","image_url":"/recetas/burrito/paso-completo-04-20261103.webp"},{"title":"Add the filling","content":"Lay a tortilla on the counter. Spread a quarter of the rice, beans, beef, salsa and cheese across the lower center, leaving about 4 cm (1.5 in) free at the edges. Don't overfill it.","image_alt":"Filling placed in the lower center of the tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Fold in the sides","content":"Fold the left and right sides of the tortilla toward the center, over the filling, to form two flaps that seal the ends.","image_alt":"Sides of the tortilla folded inward","image_url":"/recetas/burrito/paso-completo-06-20261103.webp"},{"title":"Roll the burrito","content":"Bring the bottom edge over the filling and roll upward with gentle, firm pressure, until closed. Leave the seam facing down.","image_alt":"Burrito being rolled with the bottom edge over the filling","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Brown the burrito","content":"Place the burritos in a dry skillet or griddle, seam side down. Brown them for 2 to 3 minutes per side over medium heat, until the tortilla is toasted and the cheese melts.","image_alt":"Burrito browning on the griddle, seam side down","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Cut and serve","content":"Cut each burrito diagonally and serve right away, with red salsa, guacamole and fresh cilantro.","image_alt":"Burrito cut diagonally, served with salsa and guacamole","image_url":"/recetas/burrito/paso-09.webp"}]},{"id":"df4c0310-e72a-49a1-a7b4-4c3624079520","expected_steps":[{"title":"Sofríe la cebolla, el ajo y el pimiento","content":"Calienta el aceite en una sartén a fuego medio. Sofríe la cebolla, el ajo y el pimiento durante 4 o 5 minutos, hasta que estén blandos y aromáticos.","image_alt":"Cebolla, ajo y pimiento sofriéndose en la sartén","image_url":null},{"title":"Cocina la carne","content":"Añade la carne molida, el comino, la sal, la pimienta y el chile. Cocina de 8 a 10 minutos, deshaciéndola con una cuchara de madera, hasta que no quede nada rosado y alcance 71 °C. Escurre el exceso de grasa.","image_alt":"Carne molida sazonada con comino cocinándose en la sartén","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Calienta los frijoles y el arroz","content":"Calienta por separado los frijoles y el arroz durante 3 o 4 minutos, con una cucharada de agua si hace falta. Deben quedar calientes pero no muy húmedos, para que no rompan la tortilla.","image_alt":"Frijoles y arroz calientes en cuencos de barro","image_url":null},{"title":"Calienta las tortillas","content":"Calienta cada tortilla de 20 a 30 segundos por lado en un comal o sartén seca, hasta que esté flexible y con pequeñas manchas doradas. Manténlas cubiertas con un paño.","image_alt":"Tortilla de harina calentándose en el comal para que sea flexible","image_url":null},{"title":"Coloca el relleno","content":"Extiende una tortilla sobre la tabla. Reparte un cuarto del arroz, los frijoles, la carne, la salsa y el queso en la parte inferior central, dejando unos 4 cm libres en los bordes. No la sobrecargues.","image_alt":"Relleno colocado en el centro inferior de la tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Dobla los laterales","content":"Dobla los lados izquierdo y derecho de la tortilla hacia el centro, por encima del relleno, para formar dos pliegues que sellen los extremos.","image_alt":"Laterales de la tortilla doblados hacia dentro","image_url":null},{"title":"Enrolla el burrito","content":"Lleva el borde inferior sobre el relleno y enrolla hacia arriba con presión suave y firme, hasta cerrar. Deja la unión hacia abajo.","image_alt":"Burrito enrollándose con el borde inferior sobre el relleno","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Dora el burrito","content":"Coloca los burritos en una sartén o comal seco, con la unión hacia abajo. Dóralos de 2 a 3 minutos por lado a fuego medio, hasta que la tortilla esté tostada y el queso se derrita.","image_alt":"Burrito dorándose en el comal con la unión hacia abajo","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Corta y sirve","content":"Corta cada burrito en diagonal y sírvelo enseguida, con salsa roja, guacamole y cilantro fresco.","image_alt":"Burrito cortado en diagonal servido con salsa y guacamole","image_url":"/recetas/burrito/paso-09.webp"}],"new_steps":[{"title":"Sofríe la cebolla, el ajo y el pimiento","content":"Calienta el aceite en una sartén a fuego medio. Sofríe la cebolla, el ajo y el pimiento durante 4 o 5 minutos, hasta que estén blandos y aromáticos.","image_alt":"Cebolla, ajo y pimiento sofriéndose en la sartén","image_url":"/recetas/burrito/paso-completo-01-20261103.webp"},{"title":"Cocina la carne","content":"Añade la carne molida, el comino, la sal, la pimienta y el chile. Cocina de 8 a 10 minutos, deshaciéndola con una cuchara de madera, hasta que no quede nada rosado y alcance 71 °C. Escurre el exceso de grasa.","image_alt":"Carne molida sazonada con comino cocinándose en la sartén","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Calienta los frijoles y el arroz","content":"Calienta por separado los frijoles y el arroz durante 3 o 4 minutos, con una cucharada de agua si hace falta. Deben quedar calientes pero no muy húmedos, para que no rompan la tortilla.","image_alt":"Frijoles y arroz calientes en cuencos de barro","image_url":"/recetas/burrito/paso-completo-03-20261103.webp"},{"title":"Calienta las tortillas","content":"Calienta cada tortilla de 20 a 30 segundos por lado en un comal o sartén seca, hasta que esté flexible y con pequeñas manchas doradas. Manténlas cubiertas con un paño.","image_alt":"Tortilla de harina calentándose en el comal para que sea flexible","image_url":"/recetas/burrito/paso-completo-04-20261103.webp"},{"title":"Coloca el relleno","content":"Extiende una tortilla sobre la tabla. Reparte un cuarto del arroz, los frijoles, la carne, la salsa y el queso en la parte inferior central, dejando unos 4 cm libres en los bordes. No la sobrecargues.","image_alt":"Relleno colocado en el centro inferior de la tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Dobla los laterales","content":"Dobla los lados izquierdo y derecho de la tortilla hacia el centro, por encima del relleno, para formar dos pliegues que sellen los extremos.","image_alt":"Laterales de la tortilla doblados hacia dentro","image_url":"/recetas/burrito/paso-completo-06-20261103.webp"},{"title":"Enrolla el burrito","content":"Lleva el borde inferior sobre el relleno y enrolla hacia arriba con presión suave y firme, hasta cerrar. Deja la unión hacia abajo.","image_alt":"Burrito enrollándose con el borde inferior sobre el relleno","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Dora el burrito","content":"Coloca los burritos en una sartén o comal seco, con la unión hacia abajo. Dóralos de 2 a 3 minutos por lado a fuego medio, hasta que la tortilla esté tostada y el queso se derrita.","image_alt":"Burrito dorándose en el comal con la unión hacia abajo","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Corta y sirve","content":"Corta cada burrito en diagonal y sírvelo enseguida, con salsa roja, guacamole y cilantro fresco.","image_alt":"Burrito cortado en diagonal servido con salsa y guacamole","image_url":"/recetas/burrito/paso-09.webp"}]},{"id":"84fc5de1-c24a-4856-8540-4bac3af1659a","expected_steps":[{"title":"Fais revenir l'oignon, l'ail et le poivron","content":"Fais chauffer l'huile dans une poêle à feu moyen. Fais revenir l'oignon, l'ail et le poivron pendant 4 à 5 minutes, jusqu'à ce qu'ils soient tendres et parfumés.","image_alt":"Oignon, ail et poivron qui reviennent dans la poêle","image_url":null},{"title":"Fais cuire la viande","content":"Ajoute le bœuf haché, le cumin, le sel, le poivre et le piment. Fais cuire 8 à 10 minutes, en l'émiettant avec une cuillère en bois, jusqu'à ce qu'il n'y ait plus de rose et qu'elle atteigne 71 °C. Égoutte l'excès de graisse.","image_alt":"Bœuf haché assaisonné au cumin qui cuit dans la poêle","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Réchauffe les haricots et le riz","content":"Réchauffe séparément les haricots et le riz pendant 3 à 4 minutes, avec une cuillère à soupe d'eau si besoin. Ils doivent être chauds mais pas trop humides, pour ne pas déchirer la tortilla.","image_alt":"Haricots et riz chauds dans des bols en terre cuite","image_url":null},{"title":"Réchauffe les tortillas","content":"Réchauffe chaque tortilla 20 à 30 secondes de chaque côté sur un comal ou une poêle sèche, jusqu'à ce qu'elle soit souple avec de petites taches dorées. Garde-les couvertes d'un torchon.","image_alt":"Tortilla de blé qui chauffe sur le comal pour devenir souple","image_url":null},{"title":"Dispose la garniture","content":"Étale une tortilla sur le plan de travail. Répartis un quart du riz, des haricots, de la viande, de la sauce et du fromage dans la partie inférieure centrale, en laissant environ 4 cm libres sur les bords. Ne la surcharge pas.","image_alt":"Garniture disposée dans la partie inférieure centrale de la tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Replie les côtés","content":"Replie les côtés gauche et droit de la tortilla vers le centre, par-dessus la garniture, pour former deux plis qui scellent les extrémités.","image_alt":"Côtés de la tortilla repliés vers l'intérieur","image_url":null},{"title":"Roule le burrito","content":"Amène le bord inférieur par-dessus la garniture et roule vers le haut avec une pression douce et ferme, jusqu'à ce qu'il soit fermé. Laisse la jointure vers le bas.","image_alt":"Burrito en train d'être roulé, le bord inférieur par-dessus la garniture","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Fais dorer le burrito","content":"Place les burritos dans une poêle ou un comal sec, jointure vers le bas. Fais-les dorer 2 à 3 minutes de chaque côté à feu moyen, jusqu'à ce que la tortilla soit grillée et que le fromage fonde.","image_alt":"Burrito qui dore sur le comal, jointure vers le bas","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Coupe et sers","content":"Coupe chaque burrito en diagonale et sers-le aussitôt, avec de la salsa rouge, du guacamole et de la coriandre fraîche.","image_alt":"Burrito coupé en diagonale, servi avec salsa et guacamole","image_url":"/recetas/burrito/paso-09.webp"}],"new_steps":[{"title":"Fais revenir l'oignon, l'ail et le poivron","content":"Fais chauffer l'huile dans une poêle à feu moyen. Fais revenir l'oignon, l'ail et le poivron pendant 4 à 5 minutes, jusqu'à ce qu'ils soient tendres et parfumés.","image_alt":"Oignon, ail et poivron qui reviennent dans la poêle","image_url":"/recetas/burrito/paso-completo-01-20261103.webp"},{"title":"Fais cuire la viande","content":"Ajoute le bœuf haché, le cumin, le sel, le poivre et le piment. Fais cuire 8 à 10 minutes, en l'émiettant avec une cuillère en bois, jusqu'à ce qu'il n'y ait plus de rose et qu'elle atteigne 71 °C. Égoutte l'excès de graisse.","image_alt":"Bœuf haché assaisonné au cumin qui cuit dans la poêle","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Réchauffe les haricots et le riz","content":"Réchauffe séparément les haricots et le riz pendant 3 à 4 minutes, avec une cuillère à soupe d'eau si besoin. Ils doivent être chauds mais pas trop humides, pour ne pas déchirer la tortilla.","image_alt":"Haricots et riz chauds dans des bols en terre cuite","image_url":"/recetas/burrito/paso-completo-03-20261103.webp"},{"title":"Réchauffe les tortillas","content":"Réchauffe chaque tortilla 20 à 30 secondes de chaque côté sur un comal ou une poêle sèche, jusqu'à ce qu'elle soit souple avec de petites taches dorées. Garde-les couvertes d'un torchon.","image_alt":"Tortilla de blé qui chauffe sur le comal pour devenir souple","image_url":"/recetas/burrito/paso-completo-04-20261103.webp"},{"title":"Dispose la garniture","content":"Étale une tortilla sur le plan de travail. Répartis un quart du riz, des haricots, de la viande, de la sauce et du fromage dans la partie inférieure centrale, en laissant environ 4 cm libres sur les bords. Ne la surcharge pas.","image_alt":"Garniture disposée dans la partie inférieure centrale de la tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Replie les côtés","content":"Replie les côtés gauche et droit de la tortilla vers le centre, par-dessus la garniture, pour former deux plis qui scellent les extrémités.","image_alt":"Côtés de la tortilla repliés vers l'intérieur","image_url":"/recetas/burrito/paso-completo-06-20261103.webp"},{"title":"Roule le burrito","content":"Amène le bord inférieur par-dessus la garniture et roule vers le haut avec une pression douce et ferme, jusqu'à ce qu'il soit fermé. Laisse la jointure vers le bas.","image_alt":"Burrito en train d'être roulé, le bord inférieur par-dessus la garniture","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Fais dorer le burrito","content":"Place les burritos dans une poêle ou un comal sec, jointure vers le bas. Fais-les dorer 2 à 3 minutes de chaque côté à feu moyen, jusqu'à ce que la tortilla soit grillée et que le fromage fonde.","image_alt":"Burrito qui dore sur le comal, jointure vers le bas","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Coupe et sers","content":"Coupe chaque burrito en diagonale et sers-le aussitôt, avec de la salsa rouge, du guacamole et de la coriandre fraîche.","image_alt":"Burrito coupé en diagonale, servi avec salsa et guacamole","image_url":"/recetas/burrito/paso-09.webp"}]},{"id":"473388ad-e855-4300-b711-de5074c10b5e","expected_steps":[{"title":"Soffriggi cipolla, aglio e peperone","content":"Scalda l'olio in una padella a fuoco medio. Soffriggi la cipolla, l'aglio e il peperone per 4-5 minuti, finché sono morbidi e profumati.","image_alt":"Cipolla, aglio e peperone che soffriggono in padella","image_url":null},{"title":"Cuoci la carne","content":"Aggiungi la carne macinata, il cumino, il sale, il pepe e il peperoncino. Cuoci per 8-10 minuti, sfaldandola con un cucchiaio di legno, finché non resta più rosa e raggiunge i 71 °C. Scola il grasso in eccesso.","image_alt":"Carne macinata insaporita con cumino che cuoce in padella","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Scalda i fagioli e il riso","content":"Scalda separatamente i fagioli e il riso per 3-4 minuti, con un cucchiaio d'acqua se serve. Devono restare caldi ma non troppo umidi, perché non rompano la tortilla.","image_alt":"Fagioli e riso caldi in ciotole di terracotta","image_url":null},{"title":"Scalda le tortillas","content":"Scalda ogni tortilla per 20-30 secondi per lato su un comal o una padella asciutta, finché è flessibile e con piccole macchie dorate. Tienile coperte con un panno.","image_alt":"Tortilla di farina che si scalda sul comal fino a diventare flessibile","image_url":null},{"title":"Metti il ripieno","content":"Stendi una tortilla sul piano di lavoro. Distribuisci un quarto del riso, dei fagioli, della carne, della salsa e del formaggio nella parte inferiore centrale, lasciando circa 4 cm liberi ai bordi. Non riempirla troppo.","image_alt":"Ripieno collocato nella parte inferiore centrale della tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Piega i lati","content":"Piega i lati sinistro e destro della tortilla verso il centro, sopra il ripieno, per formare due pieghe che sigillino le estremità.","image_alt":"Lati della tortilla piegati verso l'interno","image_url":null},{"title":"Arrotola il burrito","content":"Porta il bordo inferiore sopra il ripieno e arrotola verso l'alto con una pressione delicata e ferma, finché è chiuso. Lascia la giuntura verso il basso.","image_alt":"Burrito che viene arrotolato con il bordo inferiore sopra il ripieno","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Rosola il burrito","content":"Metti i burritos in una padella o comal asciutto, con la giuntura verso il basso. Rosolali per 2-3 minuti per lato a fuoco medio, finché la tortilla è tostata e il formaggio si scioglie.","image_alt":"Burrito che rosola sul comal con la giuntura verso il basso","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Taglia e servi","content":"Taglia ogni burrito in diagonale e servilo subito, con salsa rossa, guacamole e coriandolo fresco.","image_alt":"Burrito tagliato in diagonale servito con salsa e guacamole","image_url":"/recetas/burrito/paso-09.webp"}],"new_steps":[{"title":"Soffriggi cipolla, aglio e peperone","content":"Scalda l'olio in una padella a fuoco medio. Soffriggi la cipolla, l'aglio e il peperone per 4-5 minuti, finché sono morbidi e profumati.","image_alt":"Cipolla, aglio e peperone che soffriggono in padella","image_url":"/recetas/burrito/paso-completo-01-20261103.webp"},{"title":"Cuoci la carne","content":"Aggiungi la carne macinata, il cumino, il sale, il pepe e il peperoncino. Cuoci per 8-10 minuti, sfaldandola con un cucchiaio di legno, finché non resta più rosa e raggiunge i 71 °C. Scola il grasso in eccesso.","image_alt":"Carne macinata insaporita con cumino che cuoce in padella","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Scalda i fagioli e il riso","content":"Scalda separatamente i fagioli e il riso per 3-4 minuti, con un cucchiaio d'acqua se serve. Devono restare caldi ma non troppo umidi, perché non rompano la tortilla.","image_alt":"Fagioli e riso caldi in ciotole di terracotta","image_url":"/recetas/burrito/paso-completo-03-20261103.webp"},{"title":"Scalda le tortillas","content":"Scalda ogni tortilla per 20-30 secondi per lato su un comal o una padella asciutta, finché è flessibile e con piccole macchie dorate. Tienile coperte con un panno.","image_alt":"Tortilla di farina che si scalda sul comal fino a diventare flessibile","image_url":"/recetas/burrito/paso-completo-04-20261103.webp"},{"title":"Metti il ripieno","content":"Stendi una tortilla sul piano di lavoro. Distribuisci un quarto del riso, dei fagioli, della carne, della salsa e del formaggio nella parte inferiore centrale, lasciando circa 4 cm liberi ai bordi. Non riempirla troppo.","image_alt":"Ripieno collocato nella parte inferiore centrale della tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Piega i lati","content":"Piega i lati sinistro e destro della tortilla verso il centro, sopra il ripieno, per formare due pieghe che sigillino le estremità.","image_alt":"Lati della tortilla piegati verso l'interno","image_url":"/recetas/burrito/paso-completo-06-20261103.webp"},{"title":"Arrotola il burrito","content":"Porta il bordo inferiore sopra il ripieno e arrotola verso l'alto con una pressione delicata e ferma, finché è chiuso. Lascia la giuntura verso il basso.","image_alt":"Burrito che viene arrotolato con il bordo inferiore sopra il ripieno","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Rosola il burrito","content":"Metti i burritos in una padella o comal asciutto, con la giuntura verso il basso. Rosolali per 2-3 minuti per lato a fuoco medio, finché la tortilla è tostata e il formaggio si scioglie.","image_alt":"Burrito che rosola sul comal con la giuntura verso il basso","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Taglia e servi","content":"Taglia ogni burrito in diagonale e servilo subito, con salsa rossa, guacamole e coriandolo fresco.","image_alt":"Burrito tagliato in diagonale servito con salsa e guacamole","image_url":"/recetas/burrito/paso-09.webp"}]},{"id":"cd4ccb17-a0e4-4c85-b792-d526eaf24e6d","expected_steps":[{"title":"玉ねぎ、にんにく、ピーマンを炒める","content":"フライパンに油を入れて中火で熱する。玉ねぎ、にんにく、ピーマンを4～5分炒め、柔らかく香りが立つまで炒める。","image_alt":"フライパンで炒める玉ねぎ、にんにく、ピーマン","image_url":null},{"title":"肉を調理する","content":"牛ひき肉、クミン、塩、こしょう、チリパウダーを加える。木べらでほぐしながら8～10分加熱し、赤い部分がなくなり71℃に達するまで火を通す。余分な脂を取り除く。","image_alt":"クミンで味付けした牛ひき肉をフライパンで調理する","image_url":"/recetas/burrito/paso-02.webp"},{"title":"豆とご飯を温める","content":"豆とご飯を別々に3～4分温める。必要であれば大さじ1の水を加える。トルティーヤが破れないよう、熱すぎず、水分が多すぎない状態にする。","image_alt":"陶器の器に入った温かい豆とご飯","image_url":null},{"title":"トルティーヤを温める","content":"コマルまたは油を引かないフライパンで、トルティーヤの両面をそれぞれ20～30秒ずつ温め、しなやかになり小さな焼き色がつくまで加熱する。布をかぶせて保温しておく。","image_alt":"しなやかになるまでコマルで温める小麦粉トルティーヤ","image_url":null},{"title":"具材をのせる","content":"台の上にトルティーヤを広げる。中心よりやや下に、ご飯、豆、肉、サルサ、チーズをそれぞれ4分の1量ずつのせ、端を4cmほど空けておく。詰めすぎないこと。","image_alt":"トルティーヤの中央下部にのせた具材","image_url":"/recetas/burrito/paso-05.webp"},{"title":"両サイドを折り込む","content":"トルティーヤの左右の端を具材の上から中心に向かって折り込み、両端を閉じる2つの折り目を作る。","image_alt":"内側に折り込まれたトルティーヤの両サイド","image_url":null},{"title":"ブリトーを巻く","content":"下側の端を具材の上に持ち上げ、優しくしっかりと押さえながら上へ巻いていき、閉じる。閉じ目を下にしておく。","image_alt":"下側の端を具材にかぶせて巻いていくブリトー","image_url":"/recetas/burrito/paso-07.webp"},{"title":"ブリトーに焼き色をつける","content":"ブリトーを閉じ目を下にして、油を引かないフライパンまたはコマルにのせる。中火で片面2～3分ずつ焼き、トルティーヤが香ばしくなりチーズが溶けるまで焼く。","image_alt":"閉じ目を下にしてコマルで焼き色をつけるブリトー","image_url":"/recetas/burrito/paso-08.webp"},{"title":"切って盛り付ける","content":"ブリトーを斜めに切り、赤サルサ、ワカモレ、生コリアンダーを添えてすぐに盛り付ける。","image_alt":"斜めに切ってサルサとワカモレを添えたブリトー","image_url":"/recetas/burrito/paso-09.webp"}],"new_steps":[{"title":"玉ねぎ、にんにく、ピーマンを炒める","content":"フライパンに油を入れて中火で熱する。玉ねぎ、にんにく、ピーマンを4～5分炒め、柔らかく香りが立つまで炒める。","image_alt":"フライパンで炒める玉ねぎ、にんにく、ピーマン","image_url":"/recetas/burrito/paso-completo-01-20261103.webp"},{"title":"肉を調理する","content":"牛ひき肉、クミン、塩、こしょう、チリパウダーを加える。木べらでほぐしながら8～10分加熱し、赤い部分がなくなり71℃に達するまで火を通す。余分な脂を取り除く。","image_alt":"クミンで味付けした牛ひき肉をフライパンで調理する","image_url":"/recetas/burrito/paso-02.webp"},{"title":"豆とご飯を温める","content":"豆とご飯を別々に3～4分温める。必要であれば大さじ1の水を加える。トルティーヤが破れないよう、熱すぎず、水分が多すぎない状態にする。","image_alt":"陶器の器に入った温かい豆とご飯","image_url":"/recetas/burrito/paso-completo-03-20261103.webp"},{"title":"トルティーヤを温める","content":"コマルまたは油を引かないフライパンで、トルティーヤの両面をそれぞれ20～30秒ずつ温め、しなやかになり小さな焼き色がつくまで加熱する。布をかぶせて保温しておく。","image_alt":"しなやかになるまでコマルで温める小麦粉トルティーヤ","image_url":"/recetas/burrito/paso-completo-04-20261103.webp"},{"title":"具材をのせる","content":"台の上にトルティーヤを広げる。中心よりやや下に、ご飯、豆、肉、サルサ、チーズをそれぞれ4分の1量ずつのせ、端を4cmほど空けておく。詰めすぎないこと。","image_alt":"トルティーヤの中央下部にのせた具材","image_url":"/recetas/burrito/paso-05.webp"},{"title":"両サイドを折り込む","content":"トルティーヤの左右の端を具材の上から中心に向かって折り込み、両端を閉じる2つの折り目を作る。","image_alt":"内側に折り込まれたトルティーヤの両サイド","image_url":"/recetas/burrito/paso-completo-06-20261103.webp"},{"title":"ブリトーを巻く","content":"下側の端を具材の上に持ち上げ、優しくしっかりと押さえながら上へ巻いていき、閉じる。閉じ目を下にしておく。","image_alt":"下側の端を具材にかぶせて巻いていくブリトー","image_url":"/recetas/burrito/paso-07.webp"},{"title":"ブリトーに焼き色をつける","content":"ブリトーを閉じ目を下にして、油を引かないフライパンまたはコマルにのせる。中火で片面2～3分ずつ焼き、トルティーヤが香ばしくなりチーズが溶けるまで焼く。","image_alt":"閉じ目を下にしてコマルで焼き色をつけるブリトー","image_url":"/recetas/burrito/paso-08.webp"},{"title":"切って盛り付ける","content":"ブリトーを斜めに切り、赤サルサ、ワカモレ、生コリアンダーを添えてすぐに盛り付ける。","image_alt":"斜めに切ってサルサとワカモレを添えたブリトー","image_url":"/recetas/burrito/paso-09.webp"}]},{"id":"fab0efc5-61c3-4889-a812-515214cc5fb9","expected_steps":[{"title":"Refogue a cebola, o alho e o pimentão","content":"Aqueça o óleo em uma frigideira em fogo médio. Refogue a cebola, o alho e o pimentão por 4 a 5 minutos, até ficarem macios e aromáticos.","image_alt":"Cebola, alho e pimentão refogando na frigideira","image_url":null},{"title":"Cozinhe a carne","content":"Adicione a carne moída, o cominho, o sal, a pimenta e a pimenta em pó. Cozinhe por 8 a 10 minutos, desmanchando com uma colher de pau, até não sobrar nada rosado e atingir 71 °C. Escorra o excesso de gordura.","image_alt":"Carne moída temperada com cominho cozinhando na frigideira","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Aqueça o feijão e o arroz","content":"Aqueça separadamente o feijão e o arroz por 3 a 4 minutos, com uma colher de sopa de água se necessário. Devem ficar quentes mas não muito úmidos, para não rasgar a tortilla.","image_alt":"Feijão e arroz quentes em tigelas de barro","image_url":null},{"title":"Aqueça as tortillas","content":"Aqueça cada tortilla por 20 a 30 segundos de cada lado numa chapa ou frigideira seca, até ficar flexível e com pequenas manchas douradas. Mantenha-as cobertas com um pano.","image_alt":"Tortilla de trigo aquecendo na chapa até ficar flexível","image_url":null},{"title":"Coloque o recheio","content":"Estenda uma tortilla na bancada. Distribua um quarto do arroz, do feijão, da carne, do molho e do queijo na parte inferior central, deixando cerca de 4 cm livres nas bordas. Não sobrecarregue.","image_alt":"Recheio colocado na parte inferior central da tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Dobre as laterais","content":"Dobre os lados esquerdo e direito da tortilla em direção ao centro, sobre o recheio, formando duas dobras que selam as pontas.","image_alt":"Laterais da tortilla dobradas para dentro","image_url":null},{"title":"Enrole o burrito","content":"Leve a borda inferior sobre o recheio e enrole para cima com pressão suave e firme, até fechar. Deixe a emenda para baixo.","image_alt":"Burrito sendo enrolado com a borda inferior sobre o recheio","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Doure o burrito","content":"Coloque os burritos numa frigideira ou chapa seca, com a emenda para baixo. Doure por 2 a 3 minutos de cada lado em fogo médio, até a tortilla ficar tostada e o queijo derreter.","image_alt":"Burrito dourando na chapa com a emenda para baixo","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Corte e sirva","content":"Corte cada burrito na diagonal e sirva na hora, com molho vermelho, guacamole e coentro fresco.","image_alt":"Burrito cortado na diagonal servido com molho e guacamole","image_url":"/recetas/burrito/paso-09.webp"}],"new_steps":[{"title":"Refogue a cebola, o alho e o pimentão","content":"Aqueça o óleo em uma frigideira em fogo médio. Refogue a cebola, o alho e o pimentão por 4 a 5 minutos, até ficarem macios e aromáticos.","image_alt":"Cebola, alho e pimentão refogando na frigideira","image_url":"/recetas/burrito/paso-completo-01-20261103.webp"},{"title":"Cozinhe a carne","content":"Adicione a carne moída, o cominho, o sal, a pimenta e a pimenta em pó. Cozinhe por 8 a 10 minutos, desmanchando com uma colher de pau, até não sobrar nada rosado e atingir 71 °C. Escorra o excesso de gordura.","image_alt":"Carne moída temperada com cominho cozinhando na frigideira","image_url":"/recetas/burrito/paso-02.webp"},{"title":"Aqueça o feijão e o arroz","content":"Aqueça separadamente o feijão e o arroz por 3 a 4 minutos, com uma colher de sopa de água se necessário. Devem ficar quentes mas não muito úmidos, para não rasgar a tortilla.","image_alt":"Feijão e arroz quentes em tigelas de barro","image_url":"/recetas/burrito/paso-completo-03-20261103.webp"},{"title":"Aqueça as tortillas","content":"Aqueça cada tortilla por 20 a 30 segundos de cada lado numa chapa ou frigideira seca, até ficar flexível e com pequenas manchas douradas. Mantenha-as cobertas com um pano.","image_alt":"Tortilla de trigo aquecendo na chapa até ficar flexível","image_url":"/recetas/burrito/paso-completo-04-20261103.webp"},{"title":"Coloque o recheio","content":"Estenda uma tortilla na bancada. Distribua um quarto do arroz, do feijão, da carne, do molho e do queijo na parte inferior central, deixando cerca de 4 cm livres nas bordas. Não sobrecarregue.","image_alt":"Recheio colocado na parte inferior central da tortilla","image_url":"/recetas/burrito/paso-05.webp"},{"title":"Dobre as laterais","content":"Dobre os lados esquerdo e direito da tortilla em direção ao centro, sobre o recheio, formando duas dobras que selam as pontas.","image_alt":"Laterais da tortilla dobradas para dentro","image_url":"/recetas/burrito/paso-completo-06-20261103.webp"},{"title":"Enrole o burrito","content":"Leve a borda inferior sobre o recheio e enrole para cima com pressão suave e firme, até fechar. Deixe a emenda para baixo.","image_alt":"Burrito sendo enrolado com a borda inferior sobre o recheio","image_url":"/recetas/burrito/paso-07.webp"},{"title":"Doure o burrito","content":"Coloque os burritos numa frigideira ou chapa seca, com a emenda para baixo. Doure por 2 a 3 minutos de cada lado em fogo médio, até a tortilla ficar tostada e o queijo derreter.","image_alt":"Burrito dourando na chapa com a emenda para baixo","image_url":"/recetas/burrito/paso-08.webp"},{"title":"Corte e sirva","content":"Corte cada burrito na diagonal e sirva na hora, com molho vermelho, guacamole e coentro fresco.","image_alt":"Burrito cortado na diagonal servido com molho e guacamole","image_url":"/recetas/burrito/paso-09.webp"}]},{"id":"6e9b80c9-c2a8-4959-9ae2-c5378ee8f1a6","expected_steps":[{"title":"Die Früchte vorbereiten","content":"Falls nötig, die Früchte schneiden und vorher einfrieren."},{"title":"Die Zutaten hinzufügen","content":"Die Beeren, die Banane, die Pflanzenmilch, die Vanille und den optionalen Süßstoff in den Mixer geben.","image_alt":"Erdbeeren, Brombeeren, Himbeeren, Banane und Pflanzenmilch im Mixbecher","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Mixen","content":"So lange mixen, bis eine glatte, cremige Masse entsteht. Für eine dickere Konsistenz Eis hinzufügen.","image_alt":"Frisch gemixter violetter Beeren-Smoothie im Mixbecher","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Servieren","content":"Den Smoothie sofort servieren.","image_alt":"Violetter Beeren-Smoothie wird in ein Glas gegossen","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}],"new_steps":[{"title":"Die Früchte vorbereiten","content":"Falls nötig, die Früchte schneiden und vorher einfrieren.","image_url":"/recetas/batido-grimace-mcdonalds/paso-completo-01-20261103.webp","image_alt":"Die Früchte vorbereiten"},{"title":"Die Zutaten hinzufügen","content":"Die Beeren, die Banane, die Pflanzenmilch, die Vanille und den optionalen Süßstoff in den Mixer geben.","image_alt":"Erdbeeren, Brombeeren, Himbeeren, Banane und Pflanzenmilch im Mixbecher","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Mixen","content":"So lange mixen, bis eine glatte, cremige Masse entsteht. Für eine dickere Konsistenz Eis hinzufügen.","image_alt":"Frisch gemixter violetter Beeren-Smoothie im Mixbecher","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Servieren","content":"Den Smoothie sofort servieren.","image_alt":"Violetter Beeren-Smoothie wird in ein Glas gegossen","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}]},{"id":"5c1d8428-c204-4ae9-a49f-031928213fe6","expected_steps":[{"title":"Prepare the fruit","content":"If needed, cut the fruit and freeze it beforehand."},{"title":"Add the ingredients","content":"Place the berries, banana, plant-based milk, vanilla and optional sweetener in the blender.","image_alt":"Strawberries, blackberries, raspberries, banana and plant-based milk in the blender jar","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Blend","content":"Process until smooth and creamy. Add ice if you would like a thicker texture.","image_alt":"Freshly blended purple berry smoothie in the blender jar","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Serve","content":"Serve the smoothie immediately.","image_alt":"Purple berry smoothie being poured into a glass","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}],"new_steps":[{"title":"Prepare the fruit","content":"If needed, cut the fruit and freeze it beforehand.","image_url":"/recetas/batido-grimace-mcdonalds/paso-completo-01-20261103.webp","image_alt":"Prepare the fruit"},{"title":"Add the ingredients","content":"Place the berries, banana, plant-based milk, vanilla and optional sweetener in the blender.","image_alt":"Strawberries, blackberries, raspberries, banana and plant-based milk in the blender jar","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Blend","content":"Process until smooth and creamy. Add ice if you would like a thicker texture.","image_alt":"Freshly blended purple berry smoothie in the blender jar","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Serve","content":"Serve the smoothie immediately.","image_alt":"Purple berry smoothie being poured into a glass","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}]},{"id":"ad715218-7ce9-4f29-905e-4fcecdc4d954","expected_steps":[{"title":"Prepara la fruta","content":"Si es necesario, corta la fruta y congélala previamente."},{"title":"Añade los ingredientes","content":"Coloca las frutas, el plátano, la leche vegetal, la vainilla y el endulzante opcional en la licuadora.","image_alt":"Fresas, moras, frambuesas, plátano y leche vegetal en el vaso de la licuadora","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Licúa","content":"Procesa durante 1-2 minutos, hasta obtener una mezcla suave y homogénea. Añade hielo si deseas más espesor.","image_alt":"Batido morado de frutos rojos recién licuado en el vaso de la licuadora","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Sirve","content":"Sirve el batido inmediatamente.","image_alt":"Batido morado de frutos rojos sirviéndose en un vaso","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}],"new_steps":[{"title":"Prepara la fruta","content":"Si es necesario, corta la fruta y congélala previamente.","image_url":"/recetas/batido-grimace-mcdonalds/paso-completo-01-20261103.webp","image_alt":"Prepara la fruta"},{"title":"Añade los ingredientes","content":"Coloca las frutas, el plátano, la leche vegetal, la vainilla y el endulzante opcional en la licuadora.","image_alt":"Fresas, moras, frambuesas, plátano y leche vegetal en el vaso de la licuadora","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Licúa","content":"Procesa durante 1-2 minutos, hasta obtener una mezcla suave y homogénea. Añade hielo si deseas más espesor.","image_alt":"Batido morado de frutos rojos recién licuado en el vaso de la licuadora","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Sirve","content":"Sirve el batido inmediatamente.","image_alt":"Batido morado de frutos rojos sirviéndose en un vaso","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}]},{"id":"2df87c4e-3924-4780-a75b-d96e9b26d7c6","expected_steps":[{"title":"Préparer les fruits","content":"Si nécessaire, coupez les fruits et congelez-les à l'avance."},{"title":"Ajouter les ingrédients","content":"Placez les fruits rouges, la banane, le lait végétal, la vanille et l'édulcorant facultatif dans le blender.","image_alt":"Fraises, mûres, framboises, banane et lait végétal dans le blender","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Mixer","content":"Mixez jusqu'à obtenir un mélange lisse et onctueux. Ajoutez des glaçons pour plus d'épaisseur.","image_alt":"Smoothie violet aux fruits rouges fraîchement mixé dans le blender","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Servir","content":"Servez le smoothie immédiatement.","image_alt":"Smoothie violet aux fruits rouges versé dans un verre","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}],"new_steps":[{"title":"Préparer les fruits","content":"Si nécessaire, coupez les fruits et congelez-les à l'avance.","image_url":"/recetas/batido-grimace-mcdonalds/paso-completo-01-20261103.webp","image_alt":"Préparer les fruits"},{"title":"Ajouter les ingrédients","content":"Placez les fruits rouges, la banane, le lait végétal, la vanille et l'édulcorant facultatif dans le blender.","image_alt":"Fraises, mûres, framboises, banane et lait végétal dans le blender","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Mixer","content":"Mixez jusqu'à obtenir un mélange lisse et onctueux. Ajoutez des glaçons pour plus d'épaisseur.","image_alt":"Smoothie violet aux fruits rouges fraîchement mixé dans le blender","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Servir","content":"Servez le smoothie immédiatement.","image_alt":"Smoothie violet aux fruits rouges versé dans un verre","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}]},{"id":"2a15bb28-c3b1-4cf0-a2f0-812f709658e3","expected_steps":[{"title":"Prepara la frutta","content":"Se necessario, taglia la frutta e congelala in anticipo."},{"title":"Aggiungi gli ingredienti","content":"Metti i frutti di bosco, la banana, il latte vegetale, la vaniglia e il dolcificante facoltativo nel frullatore.","image_alt":"Fragole, more, lamponi, banana e latte vegetale nel bicchiere del frullatore","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Frulla","content":"Frulla fino a ottenere un composto liscio e omogeneo. Aggiungi ghiaccio per una consistenza più densa.","image_alt":"Frullato viola ai frutti di bosco appena frullato nel bicchiere","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Servi","content":"Servi il frullato subito.","image_alt":"Frullato viola ai frutti di bosco versato in un bicchiere","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}],"new_steps":[{"title":"Prepara la frutta","content":"Se necessario, taglia la frutta e congelala in anticipo.","image_url":"/recetas/batido-grimace-mcdonalds/paso-completo-01-20261103.webp","image_alt":"Prepara la frutta"},{"title":"Aggiungi gli ingredienti","content":"Metti i frutti di bosco, la banana, il latte vegetale, la vaniglia e il dolcificante facoltativo nel frullatore.","image_alt":"Fragole, more, lamponi, banana e latte vegetale nel bicchiere del frullatore","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Frulla","content":"Frulla fino a ottenere un composto liscio e omogeneo. Aggiungi ghiaccio per una consistenza più densa.","image_alt":"Frullato viola ai frutti di bosco appena frullato nel bicchiere","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Servi","content":"Servi il frullato subito.","image_alt":"Frullato viola ai frutti di bosco versato in un bicchiere","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}]},{"id":"401379ba-72cf-41a2-a4d6-e956ab26efa0","expected_steps":[{"title":"果物を準備する","content":"必要に応じて果物をカットし、あらかじめ冷凍しておきます。"},{"title":"材料を加える","content":"ベリー類、バナナ、植物性ミルク、バニラ、お好みの甘味料をミキサーに入れます。","image_alt":"いちご、ブラックベリー、ラズベリー、バナナ、植物性ミルクが入ったミキサー","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"ミキサーにかける","content":"なめらかになるまで撹拌します。濃厚にしたい場合は氷を加えます。","image_alt":"ミキサーで撹拌したばかりの紫色のベリースムージー","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"提供する","content":"すぐにグラスに注いで提供します。","image_alt":"紫色のベリースムージーをグラスに注いでいるところ","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}],"new_steps":[{"title":"果物を準備する","content":"必要に応じて果物をカットし、あらかじめ冷凍しておきます。","image_url":"/recetas/batido-grimace-mcdonalds/paso-completo-01-20261103.webp","image_alt":"果物を準備する"},{"title":"材料を加える","content":"ベリー類、バナナ、植物性ミルク、バニラ、お好みの甘味料をミキサーに入れます。","image_alt":"いちご、ブラックベリー、ラズベリー、バナナ、植物性ミルクが入ったミキサー","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"ミキサーにかける","content":"なめらかになるまで撹拌します。濃厚にしたい場合は氷を加えます。","image_alt":"ミキサーで撹拌したばかりの紫色のベリースムージー","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"提供する","content":"すぐにグラスに注いで提供します。","image_alt":"紫色のベリースムージーをグラスに注いでいるところ","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}]},{"id":"1335d91c-469d-41ff-beba-2a3be41b2ead","expected_steps":[{"title":"Prepare a fruta","content":"Se necessário, corte a fruta e congele com antecedência."},{"title":"Adicione os ingredientes","content":"Coloque as frutas vermelhas, a banana, o leite vegetal, a baunilha e o adoçante opcional no liquidificador.","image_alt":"Morangos, amoras, framboesas, banana e leite vegetal no copo do liquidificador","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Bata","content":"Bata até obter uma mistura lisa e homogênea. Adicione gelo para uma textura mais espessa.","image_alt":"Batida roxa de frutas vermelhas recém-batida no liquidificador","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Sirva","content":"Sirva a batida imediatamente.","image_alt":"Batida roxa de frutas vermelhas sendo servida em um copo","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}],"new_steps":[{"title":"Prepare a fruta","content":"Se necessário, corte a fruta e congele com antecedência.","image_url":"/recetas/batido-grimace-mcdonalds/paso-completo-01-20261103.webp","image_alt":"Prepare a fruta"},{"title":"Adicione os ingredientes","content":"Coloque as frutas vermelhas, a banana, o leite vegetal, a baunilha e o adoçante opcional no liquidificador.","image_alt":"Morangos, amoras, framboesas, banana e leite vegetal no copo do liquidificador","image_url":"/recetas/batido-grimace-mcdonalds/paso-02.webp"},{"title":"Bata","content":"Bata até obter uma mistura lisa e homogênea. Adicione gelo para uma textura mais espessa.","image_alt":"Batida roxa de frutas vermelhas recém-batida no liquidificador","image_url":"/recetas/batido-grimace-mcdonalds/paso-03.webp"},{"title":"Sirva","content":"Sirva a batida imediatamente.","image_alt":"Batida roxa de frutas vermelhas sendo servida em um copo","image_url":"/recetas/batido-grimace-mcdonalds/paso-04.webp"}]},{"id":"4324c03a-abdd-44c5-9570-99c91bb4c237","expected_steps":[{"title":"Hähnchen kochen und Brühe zubereiten","content":"Das Hähnchen mit Wasser oder Brühe, Frühlingszwiebel, Knoblauch, Salz und Pfeffer in einen großen Topf geben. Sanft aufkochen lassen und etwa 30 Minuten garen, dabei aufsteigenden Schaum abschöpfen.","image_alt":"Hähnchenbrust köchelt in einem Topf mit Brühe, Frühlingszwiebel und Knoblauch","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Hähnchen herausnehmen und zerpflücken","content":"Sobald das Hähnchen gar ist, herausnehmen und etwas abkühlen lassen. In mittelgroße Stücke zerzupfen und beiseitestellen. Die Brühe im Topf lassen.","image_alt":"Gekochtes Hähnchen in Stücke gezupft auf einem Holzbrett","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Mais und Kartoffeln hinzufügen","content":"Mais und Kartoffeln hinzugeben. Zuerst die Papa criolla und die Kartoffelsorte, die zerfallen soll, um die Brühe anzudicken; die festeren Kartoffeln so hinzufügen, dass sie erkennbare Stücke behalten.","image_alt":"Maisstücke und drei Kartoffelsorten werden der Hühnerbrühe hinzugefügt","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Köcheln lassen, bis die Suppe sämig wird","content":"Bei mittlerer bis niedriger Hitze etwa 35–40 Minuten köcheln lassen, dabei gelegentlich vorsichtig umrühren. Ein Teil der Kartoffeln soll zerfallen und die Brühe andicken, während andere ihre Textur behalten.","image_alt":"Ajiaco wird sämig im Topf, während sich die Kartoffeln in der Brühe auflösen","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Guascas hinzufügen","content":"Die Guascas in den letzten 10 Minuten der Garzeit hinzufügen. Abschmecken und mit Salz und Pfeffer nachwürzen.","image_alt":"Hand streut getrocknete Guascas über das Ajiaco im Topf","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Hähnchen zurückgeben","content":"Das zerpflückte Hähnchen hinzufügen und einige Minuten weiterköcheln lassen, bis es durchgewärmt und gleichmäßig in der Suppe verteilt ist."},{"title":"Servieren","content":"Das Ajiaco heiß mit Sahne, Kapern und Avocado servieren. Diese Beilagen können separat oder direkt in jedem Teller serviert werden, je nach Vorliebe.","image_alt":"Heißes kolumbianisches Ajiaco wird mit Sahne, Kapern und Avocado in eine Schüssel serviert","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}],"new_steps":[{"title":"Hähnchen kochen und Brühe zubereiten","content":"Das Hähnchen mit Wasser oder Brühe, Frühlingszwiebel, Knoblauch, Salz und Pfeffer in einen großen Topf geben. Sanft aufkochen lassen und etwa 30 Minuten garen, dabei aufsteigenden Schaum abschöpfen.","image_alt":"Hähnchenbrust köchelt in einem Topf mit Brühe, Frühlingszwiebel und Knoblauch","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Hähnchen herausnehmen und zerpflücken","content":"Sobald das Hähnchen gar ist, herausnehmen und etwas abkühlen lassen. In mittelgroße Stücke zerzupfen und beiseitestellen. Die Brühe im Topf lassen.","image_alt":"Gekochtes Hähnchen in Stücke gezupft auf einem Holzbrett","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Mais und Kartoffeln hinzufügen","content":"Mais und Kartoffeln hinzugeben. Zuerst die Papa criolla und die Kartoffelsorte, die zerfallen soll, um die Brühe anzudicken; die festeren Kartoffeln so hinzufügen, dass sie erkennbare Stücke behalten.","image_alt":"Maisstücke und drei Kartoffelsorten werden der Hühnerbrühe hinzugefügt","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Köcheln lassen, bis die Suppe sämig wird","content":"Bei mittlerer bis niedriger Hitze etwa 35–40 Minuten köcheln lassen, dabei gelegentlich vorsichtig umrühren. Ein Teil der Kartoffeln soll zerfallen und die Brühe andicken, während andere ihre Textur behalten.","image_alt":"Ajiaco wird sämig im Topf, während sich die Kartoffeln in der Brühe auflösen","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Guascas hinzufügen","content":"Die Guascas in den letzten 10 Minuten der Garzeit hinzufügen. Abschmecken und mit Salz und Pfeffer nachwürzen.","image_alt":"Hand streut getrocknete Guascas über das Ajiaco im Topf","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Hähnchen zurückgeben","content":"Das zerpflückte Hähnchen hinzufügen und einige Minuten weiterköcheln lassen, bis es durchgewärmt und gleichmäßig in der Suppe verteilt ist.","image_url":"/recetas/ajiaco-colombiano/paso-completo-06-20261103.webp","image_alt":"Hähnchen zurückgeben"},{"title":"Servieren","content":"Das Ajiaco heiß mit Sahne, Kapern und Avocado servieren. Diese Beilagen können separat oder direkt in jedem Teller serviert werden, je nach Vorliebe.","image_alt":"Heißes kolumbianisches Ajiaco wird mit Sahne, Kapern und Avocado in eine Schüssel serviert","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}]},{"id":"49a2845e-5eaf-47b4-a66b-7b6dde3f0048","expected_steps":[{"title":"Cook the chicken and make the broth","content":"Place the chicken in a large pot with the water or stock, the scallion, garlic, salt and pepper. Bring to a gentle boil and cook for about 30 minutes, skimming off any foam that rises to the surface.","image_alt":"Chicken breasts simmering in a pot of broth with scallion and garlic","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Remove and shred the chicken","content":"Once the chicken is cooked, remove it and let it cool enough to handle. Shred it into medium pieces and set aside. Keep the broth in the pot.","image_alt":"Cooked chicken shredded into pieces on a wooden board","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Add the corn and potatoes","content":"Add the corn and potatoes. Add the papa criolla and the potato that will break down first to thicken the broth; add the firmer potatoes so they keep recognizable pieces.","image_alt":"Corn pieces and three kinds of potato being added to the chicken broth","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cook until it thickens","content":"Cook over medium-low heat for about 35–40 minutes, stirring occasionally with care. Some of the potatoes should break down and thicken the broth, while others keep their texture.","image_alt":"Ajiaco thickening in the pot as the potatoes break down into the broth","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Add the guascas","content":"Add the guascas during the last 10 minutes of cooking. Taste and adjust salt and pepper.","image_alt":"Hand sprinkling dried guascas over the ajiaco in the pot","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Return the chicken to the pot","content":"Add the shredded chicken and cook for a few more minutes, until it is heated through and evenly distributed in the soup."},{"title":"Serve","content":"Serve the ajiaco hot with heavy cream, capers and avocado. These toppings can be served on the side or added directly to each bowl, as preferred.","image_alt":"Serving hot Colombian ajiaco into a bowl with cream, capers and avocado","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}],"new_steps":[{"title":"Cook the chicken and make the broth","content":"Place the chicken in a large pot with the water or stock, the scallion, garlic, salt and pepper. Bring to a gentle boil and cook for about 30 minutes, skimming off any foam that rises to the surface.","image_alt":"Chicken breasts simmering in a pot of broth with scallion and garlic","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Remove and shred the chicken","content":"Once the chicken is cooked, remove it and let it cool enough to handle. Shred it into medium pieces and set aside. Keep the broth in the pot.","image_alt":"Cooked chicken shredded into pieces on a wooden board","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Add the corn and potatoes","content":"Add the corn and potatoes. Add the papa criolla and the potato that will break down first to thicken the broth; add the firmer potatoes so they keep recognizable pieces.","image_alt":"Corn pieces and three kinds of potato being added to the chicken broth","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cook until it thickens","content":"Cook over medium-low heat for about 35–40 minutes, stirring occasionally with care. Some of the potatoes should break down and thicken the broth, while others keep their texture.","image_alt":"Ajiaco thickening in the pot as the potatoes break down into the broth","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Add the guascas","content":"Add the guascas during the last 10 minutes of cooking. Taste and adjust salt and pepper.","image_alt":"Hand sprinkling dried guascas over the ajiaco in the pot","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Return the chicken to the pot","content":"Add the shredded chicken and cook for a few more minutes, until it is heated through and evenly distributed in the soup.","image_url":"/recetas/ajiaco-colombiano/paso-completo-06-20261103.webp","image_alt":"Return the chicken to the pot"},{"title":"Serve","content":"Serve the ajiaco hot with heavy cream, capers and avocado. These toppings can be served on the side or added directly to each bowl, as preferred.","image_alt":"Serving hot Colombian ajiaco into a bowl with cream, capers and avocado","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}]},{"id":"52fbd60c-9d33-481f-8d85-3eaaca0f220b","expected_steps":[{"title":"Cocina el pollo y prepara el caldo","content":"Coloca el pollo en una olla grande con el agua o caldo, la cebolla larga, el ajo, sal y pimienta. Lleva a hervor suave y cocina unos 30 minutos, retirando la espuma que suba a la superficie.","image_alt":"Pechugas de pollo cociéndose en una olla con caldo, cebolla larga y ajo","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Retira y desmecha el pollo","content":"Cuando el pollo esté cocido, retíralo y deja que se enfríe lo suficiente para manipularlo. Desméchalo en trozos medianos y reserva. Mantén el caldo en la olla.","image_alt":"Pollo cocido desmechado en trozos sobre una tabla de madera","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Añade la mazorca y las papas","content":"Incorpora la mazorca y las papas. Coloca primero la papa criolla y la papa que vaya a deshacerse para espesar el caldo; añade las papas más firmes de forma que conserven trozos reconocibles.","image_alt":"Trozos de mazorca y tres tipos de papa añadiéndose al caldo de pollo","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cocina hasta obtener cuerpo","content":"Cocina a fuego medio-bajo unos 35–40 minutos, removiendo de vez en cuando con cuidado. Parte de las papas debe deshacerse y espesar el caldo, mientras otras conservan textura.","image_alt":"Ajiaco espesando en la olla con el pollo y las papas deshaciéndose en el caldo","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Incorpora las guascas","content":"Añade las guascas durante los últimos 10 minutos de cocción. Prueba y ajusta sal y pimienta.","image_alt":"Mano espolvoreando guascas secas sobre el ajiaco en la olla","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Devuelve el pollo","content":"Incorpora el pollo desmechado y cocina unos minutos más, hasta que esté bien caliente y distribuido por la sopa."},{"title":"Sirve","content":"Sirve el ajiaco caliente con crema de leche, alcaparras y aguacate. Estos acompañamientos se sirven aparte o directamente en cada plato, según preferencia.","image_alt":"Sirviendo ajiaco colombiano caliente en un plato hondo con crema de leche, alcaparras y aguacate","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}],"new_steps":[{"title":"Cocina el pollo y prepara el caldo","content":"Coloca el pollo en una olla grande con el agua o caldo, la cebolla larga, el ajo, sal y pimienta. Lleva a hervor suave y cocina unos 30 minutos, retirando la espuma que suba a la superficie.","image_alt":"Pechugas de pollo cociéndose en una olla con caldo, cebolla larga y ajo","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Retira y desmecha el pollo","content":"Cuando el pollo esté cocido, retíralo y deja que se enfríe lo suficiente para manipularlo. Desméchalo en trozos medianos y reserva. Mantén el caldo en la olla.","image_alt":"Pollo cocido desmechado en trozos sobre una tabla de madera","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Añade la mazorca y las papas","content":"Incorpora la mazorca y las papas. Coloca primero la papa criolla y la papa que vaya a deshacerse para espesar el caldo; añade las papas más firmes de forma que conserven trozos reconocibles.","image_alt":"Trozos de mazorca y tres tipos de papa añadiéndose al caldo de pollo","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cocina hasta obtener cuerpo","content":"Cocina a fuego medio-bajo unos 35–40 minutos, removiendo de vez en cuando con cuidado. Parte de las papas debe deshacerse y espesar el caldo, mientras otras conservan textura.","image_alt":"Ajiaco espesando en la olla con el pollo y las papas deshaciéndose en el caldo","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Incorpora las guascas","content":"Añade las guascas durante los últimos 10 minutos de cocción. Prueba y ajusta sal y pimienta.","image_alt":"Mano espolvoreando guascas secas sobre el ajiaco en la olla","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Devuelve el pollo","content":"Incorpora el pollo desmechado y cocina unos minutos más, hasta que esté bien caliente y distribuido por la sopa.","image_url":"/recetas/ajiaco-colombiano/paso-completo-06-20261103.webp","image_alt":"Devuelve el pollo"},{"title":"Sirve","content":"Sirve el ajiaco caliente con crema de leche, alcaparras y aguacate. Estos acompañamientos se sirven aparte o directamente en cada plato, según preferencia.","image_alt":"Sirviendo ajiaco colombiano caliente en un plato hondo con crema de leche, alcaparras y aguacate","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}]},{"id":"8bdf411b-5842-484c-8398-83c771c3fa08","expected_steps":[{"title":"Cuire le poulet et préparer le bouillon","content":"Place le poulet dans une grande marmite avec l'eau ou le bouillon, l'oignon nouveau, l'ail, le sel et le poivre. Porte à ébullition douce et cuis environ 30 minutes, en retirant l'écume qui remonte à la surface.","image_alt":"Blancs de poulet mijotant dans une marmite de bouillon avec oignon nouveau et ail","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Retirer et effilocher le poulet","content":"Une fois le poulet cuit, retire-le et laisse-le refroidir suffisamment pour le manipuler. Effiloche-le en morceaux moyens et réserve. Garde le bouillon dans la marmite.","image_alt":"Poulet cuit effiloché en morceaux sur une planche en bois","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Ajouter le maïs et les pommes de terre","content":"Incorpore le maïs et les pommes de terre. Ajoute d'abord la papa criolla et la pomme de terre qui va se défaire pour épaissir le bouillon ; ajoute les pommes de terre plus fermes de façon à ce qu'elles gardent des morceaux reconnaissables.","image_alt":"Morceaux de maïs et trois variétés de pommes de terre ajoutés au bouillon de poulet","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cuire jusqu'à obtenir du corps","content":"Cuis à feu moyen-doux pendant 35 à 40 minutes environ, en remuant de temps en temps avec précaution. Une partie des pommes de terre doit se défaire et épaissir le bouillon, tandis que d'autres gardent leur texture.","image_alt":"L'ajiaco épaissit dans la marmite tandis que les pommes de terre se défont dans le bouillon","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Incorporer les guascas","content":"Ajoute les guascas pendant les 10 dernières minutes de cuisson. Goûte et rectifie le sel et le poivre.","image_alt":"Main saupoudrant des guascas séchées sur l'ajiaco dans la marmite","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Remettre le poulet","content":"Incorpore le poulet effiloché et cuis quelques minutes de plus, jusqu'à ce qu'il soit bien chaud et réparti dans la soupe."},{"title":"Servir","content":"Sers l'ajiaco chaud avec de la crème fraîche, des câpres et de l'avocat. Ces accompagnements se servent à part ou directement dans chaque assiette, selon la préférence.","image_alt":"Service de l'ajiaco colombien chaud dans un bol avec crème, câpres et avocat","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}],"new_steps":[{"title":"Cuire le poulet et préparer le bouillon","content":"Place le poulet dans une grande marmite avec l'eau ou le bouillon, l'oignon nouveau, l'ail, le sel et le poivre. Porte à ébullition douce et cuis environ 30 minutes, en retirant l'écume qui remonte à la surface.","image_alt":"Blancs de poulet mijotant dans une marmite de bouillon avec oignon nouveau et ail","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Retirer et effilocher le poulet","content":"Une fois le poulet cuit, retire-le et laisse-le refroidir suffisamment pour le manipuler. Effiloche-le en morceaux moyens et réserve. Garde le bouillon dans la marmite.","image_alt":"Poulet cuit effiloché en morceaux sur une planche en bois","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Ajouter le maïs et les pommes de terre","content":"Incorpore le maïs et les pommes de terre. Ajoute d'abord la papa criolla et la pomme de terre qui va se défaire pour épaissir le bouillon ; ajoute les pommes de terre plus fermes de façon à ce qu'elles gardent des morceaux reconnaissables.","image_alt":"Morceaux de maïs et trois variétés de pommes de terre ajoutés au bouillon de poulet","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cuire jusqu'à obtenir du corps","content":"Cuis à feu moyen-doux pendant 35 à 40 minutes environ, en remuant de temps en temps avec précaution. Une partie des pommes de terre doit se défaire et épaissir le bouillon, tandis que d'autres gardent leur texture.","image_alt":"L'ajiaco épaissit dans la marmite tandis que les pommes de terre se défont dans le bouillon","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Incorporer les guascas","content":"Ajoute les guascas pendant les 10 dernières minutes de cuisson. Goûte et rectifie le sel et le poivre.","image_alt":"Main saupoudrant des guascas séchées sur l'ajiaco dans la marmite","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Remettre le poulet","content":"Incorpore le poulet effiloché et cuis quelques minutes de plus, jusqu'à ce qu'il soit bien chaud et réparti dans la soupe.","image_url":"/recetas/ajiaco-colombiano/paso-completo-06-20261103.webp","image_alt":"Remettre le poulet"},{"title":"Servir","content":"Sers l'ajiaco chaud avec de la crème fraîche, des câpres et de l'avocat. Ces accompagnements se servent à part ou directement dans chaque assiette, selon la préférence.","image_alt":"Service de l'ajiaco colombien chaud dans un bol avec crème, câpres et avocat","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}]},{"id":"ca08844b-5e00-4a0d-9884-00205545c74a","expected_steps":[{"title":"Cuocere il pollo e preparare il brodo","content":"Metti il pollo in una pentola capiente con acqua o brodo, la cebolla larga, l'aglio, sale e pepe. Porta a un bollore delicato e cuoci per circa 30 minuti, eliminando la schiuma che sale in superficie.","image_alt":"Petti di pollo che cuociono in una pentola di brodo con cipollotto e aglio","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Sfilacciare il pollo","content":"Quando il pollo è cotto, toglilo dalla pentola e lascialo intiepidire abbastanza da poterlo maneggiare. Sfilaccialo in pezzi medi e tienilo da parte. Conserva il brodo nella pentola.","image_alt":"Pollo cotto sfilacciato in pezzi su un tagliere di legno","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Aggiungere mais e patate","content":"Unisci le pannocchie e le patate. Metti per prime le patate criolla e quelle che devono disfarsi per addensare il brodo; aggiungi le patate più sode in modo che conservino la loro forma.","image_alt":"Pezzi di mais e tre varietà di patate aggiunti al brodo di pollo","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cuocere fino a ottenere la consistenza","content":"Cuoci a fuoco medio-basso per circa 35–40 minuti, mescolando con delicatezza ogni tanto. Una parte delle patate deve disfarsi e dare corpo al brodo, mentre altre devono rimanere a pezzi.","image_alt":"L'ajiaco si addensa nella pentola mentre le patate si sfaldano nel brodo","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Aggiungere la guasca","content":"Unisci la guasca negli ultimi 10 minuti di cottura. Assaggia e regola di sale e pepe.","image_alt":"Mano che cosparge guascas secche sull'ajiaco nella pentola","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Rimettere il pollo nella pentola","content":"Aggiungi il pollo sfilacciato e cuoci ancora per qualche minuto, finché è ben caldo e distribuito nella zuppa."},{"title":"Servire","content":"Servi l'ajiaco ben caldo con panna, capperi e avocado. Puoi aggiungere gli accompagnamenti direttamente nel piatto oppure portarli separatamente.","image_alt":"Ajiaco colombiano caldo servito in una ciotola con panna, capperi e avocado","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}],"new_steps":[{"title":"Cuocere il pollo e preparare il brodo","content":"Metti il pollo in una pentola capiente con acqua o brodo, la cebolla larga, l'aglio, sale e pepe. Porta a un bollore delicato e cuoci per circa 30 minuti, eliminando la schiuma che sale in superficie.","image_alt":"Petti di pollo che cuociono in una pentola di brodo con cipollotto e aglio","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Sfilacciare il pollo","content":"Quando il pollo è cotto, toglilo dalla pentola e lascialo intiepidire abbastanza da poterlo maneggiare. Sfilaccialo in pezzi medi e tienilo da parte. Conserva il brodo nella pentola.","image_alt":"Pollo cotto sfilacciato in pezzi su un tagliere di legno","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Aggiungere mais e patate","content":"Unisci le pannocchie e le patate. Metti per prime le patate criolla e quelle che devono disfarsi per addensare il brodo; aggiungi le patate più sode in modo che conservino la loro forma.","image_alt":"Pezzi di mais e tre varietà di patate aggiunti al brodo di pollo","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cuocere fino a ottenere la consistenza","content":"Cuoci a fuoco medio-basso per circa 35–40 minuti, mescolando con delicatezza ogni tanto. Una parte delle patate deve disfarsi e dare corpo al brodo, mentre altre devono rimanere a pezzi.","image_alt":"L'ajiaco si addensa nella pentola mentre le patate si sfaldano nel brodo","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Aggiungere la guasca","content":"Unisci la guasca negli ultimi 10 minuti di cottura. Assaggia e regola di sale e pepe.","image_alt":"Mano che cosparge guascas secche sull'ajiaco nella pentola","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Rimettere il pollo nella pentola","content":"Aggiungi il pollo sfilacciato e cuoci ancora per qualche minuto, finché è ben caldo e distribuito nella zuppa.","image_url":"/recetas/ajiaco-colombiano/paso-completo-06-20261103.webp","image_alt":"Rimettere il pollo nella pentola"},{"title":"Servire","content":"Servi l'ajiaco ben caldo con panna, capperi e avocado. Puoi aggiungere gli accompagnamenti direttamente nel piatto oppure portarli separatamente.","image_alt":"Ajiaco colombiano caldo servito in una ciotola con panna, capperi e avocado","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}]},{"id":"46488da8-104a-4400-a9ea-d134488866eb","expected_steps":[{"title":"鶏肉を煮てスープを作る","content":"大きな鍋に鶏肉、水またはスープ、青ねぎ、にんにく、塩、こしょうを入れる。弱めに沸騰させ、表面に浮くアクを取りながら約30分煮る。","image_alt":"青ねぎとにんにくを加えたスープで煮込まれる鶏胸肉","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"鶏肉を取り出してほぐす","content":"鶏肉に火が通ったら取り出し、触れる程度まで冷ます。中くらいの大きさにほぐして取り置く。スープは鍋に残しておく。","image_alt":"まな板の上でほぐされた鶏肉","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"とうもろこしとじゃがいもを加える","content":"とうもろこしとじゃがいもを加える。スープにとろみをつけるため、パパ・クリオージャと崩れやすいじゃがいもを先に入れ、形が残るよう硬めのじゃがいもも加える。","image_alt":"鶏がらスープに加えられるとうもろこしと三種のじゃがいも","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"とろみがつくまで煮る","content":"中弱火で35〜40分ほど、時々そっと混ぜながら煮る。じゃがいもの一部は崩れてスープにとろみをつけ、他は食感を保つようにする。","image_alt":"じゃがいもが崩れてとろみがつくアヒアコ","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"グアスカスを加える","content":"煮込みの最後の10分でグアスカスを加える。味を見て塩こしょうを調整する。","image_alt":"鍋のアヒアコに乾燥グアスカスを振りかける手","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"鶏肉を戻す","content":"ほぐした鶏肉を加え、全体が温まりスープに行き渡るまでさらに数分煮る。"},{"title":"盛り付ける","content":"熱いうちに生クリーム、ケッパー、アボカドを添えて盛り付ける。これらの具材は取り分けて添えても、直接盛り付けてもよい。","image_alt":"生クリーム、ケッパー、アボカドを添えて盛り付けられた熱々のコロンビア風アヒアコ","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}],"new_steps":[{"title":"鶏肉を煮てスープを作る","content":"大きな鍋に鶏肉、水またはスープ、青ねぎ、にんにく、塩、こしょうを入れる。弱めに沸騰させ、表面に浮くアクを取りながら約30分煮る。","image_alt":"青ねぎとにんにくを加えたスープで煮込まれる鶏胸肉","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"鶏肉を取り出してほぐす","content":"鶏肉に火が通ったら取り出し、触れる程度まで冷ます。中くらいの大きさにほぐして取り置く。スープは鍋に残しておく。","image_alt":"まな板の上でほぐされた鶏肉","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"とうもろこしとじゃがいもを加える","content":"とうもろこしとじゃがいもを加える。スープにとろみをつけるため、パパ・クリオージャと崩れやすいじゃがいもを先に入れ、形が残るよう硬めのじゃがいもも加える。","image_alt":"鶏がらスープに加えられるとうもろこしと三種のじゃがいも","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"とろみがつくまで煮る","content":"中弱火で35〜40分ほど、時々そっと混ぜながら煮る。じゃがいもの一部は崩れてスープにとろみをつけ、他は食感を保つようにする。","image_alt":"じゃがいもが崩れてとろみがつくアヒアコ","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"グアスカスを加える","content":"煮込みの最後の10分でグアスカスを加える。味を見て塩こしょうを調整する。","image_alt":"鍋のアヒアコに乾燥グアスカスを振りかける手","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"鶏肉を戻す","content":"ほぐした鶏肉を加え、全体が温まりスープに行き渡るまでさらに数分煮る。","image_url":"/recetas/ajiaco-colombiano/paso-completo-06-20261103.webp","image_alt":"鶏肉を戻す"},{"title":"盛り付ける","content":"熱いうちに生クリーム、ケッパー、アボカドを添えて盛り付ける。これらの具材は取り分けて添えても、直接盛り付けてもよい。","image_alt":"生クリーム、ケッパー、アボカドを添えて盛り付けられた熱々のコロンビア風アヒアコ","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}]},{"id":"3fe4e81e-f100-42ad-9ed2-11cfe05dacd4","expected_steps":[{"title":"Cozinhe o frango e prepare o caldo","content":"Coloque o frango em uma panela grande com a água ou o caldo, a cebolinha, o alho, sal e pimenta. Deixe ferver suavemente e cozinhe por cerca de 30 minutos, retirando a espuma que subir à superfície.","image_alt":"Peitos de frango cozinhando em uma panela de caldo com cebolinha e alho","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Retire e desfie o frango","content":"Quando o frango estiver cozido, retire-o e deixe esfriar o suficiente para manuseá-lo. Desfie em pedaços médios e reserve. Mantenha o caldo na panela.","image_alt":"Frango cozido desfiado em pedaços sobre uma tábua de madeira","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Adicione o milho e as batatas","content":"Acrescente o milho e as batatas. Coloque primeiro a papa criolla e a batata que vai se desmanchar para engrossar o caldo; adicione as batatas mais firmes de forma que mantenham pedaços reconhecíveis.","image_alt":"Pedaços de milho e três tipos de batata sendo adicionados ao caldo de frango","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cozinhe até engrossar","content":"Cozinhe em fogo médio-baixo por cerca de 35–40 minutos, mexendo de vez em quando com cuidado. Parte das batatas deve se desmanchar e engrossar o caldo, enquanto outras mantêm a textura.","image_alt":"Ajiaco engrossando na panela com as batatas se desmanchando no caldo","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Acrescente as guascas","content":"Adicione as guascas nos últimos 10 minutos de cozimento. Prove e ajuste o sal e a pimenta.","image_alt":"Mão polvilhando guascas secas sobre o ajiaco na panela","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Devolva o frango","content":"Acrescente o frango desfiado e cozinhe mais alguns minutos, até que esteja bem quente e distribuído na sopa."},{"title":"Sirva","content":"Sirva o ajiaco quente com creme de leite, alcaparras e abacate. Esses acompanhamentos podem ser servidos à parte ou diretamente em cada prato, conforme preferir.","image_alt":"Servindo ajiaco colombiano quente em um prato com creme de leite, alcaparras e abacate","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}],"new_steps":[{"title":"Cozinhe o frango e prepare o caldo","content":"Coloque o frango em uma panela grande com a água ou o caldo, a cebolinha, o alho, sal e pimenta. Deixe ferver suavemente e cozinhe por cerca de 30 minutos, retirando a espuma que subir à superfície.","image_alt":"Peitos de frango cozinhando em uma panela de caldo com cebolinha e alho","image_url":"/recetas/ajiaco-colombiano/paso-01.webp"},{"title":"Retire e desfie o frango","content":"Quando o frango estiver cozido, retire-o e deixe esfriar o suficiente para manuseá-lo. Desfie em pedaços médios e reserve. Mantenha o caldo na panela.","image_alt":"Frango cozido desfiado em pedaços sobre uma tábua de madeira","image_url":"/recetas/ajiaco-colombiano/paso-02.webp"},{"title":"Adicione o milho e as batatas","content":"Acrescente o milho e as batatas. Coloque primeiro a papa criolla e a batata que vai se desmanchar para engrossar o caldo; adicione as batatas mais firmes de forma que mantenham pedaços reconhecíveis.","image_alt":"Pedaços de milho e três tipos de batata sendo adicionados ao caldo de frango","image_url":"/recetas/ajiaco-colombiano/paso-03.webp"},{"title":"Cozinhe até engrossar","content":"Cozinhe em fogo médio-baixo por cerca de 35–40 minutos, mexendo de vez em quando com cuidado. Parte das batatas deve se desmanchar e engrossar o caldo, enquanto outras mantêm a textura.","image_alt":"Ajiaco engrossando na panela com as batatas se desmanchando no caldo","image_url":"/recetas/ajiaco-colombiano/paso-04.webp"},{"title":"Acrescente as guascas","content":"Adicione as guascas nos últimos 10 minutos de cozimento. Prove e ajuste o sal e a pimenta.","image_alt":"Mão polvilhando guascas secas sobre o ajiaco na panela","image_url":"/recetas/ajiaco-colombiano/paso-05.webp"},{"title":"Devolva o frango","content":"Acrescente o frango desfiado e cozinhe mais alguns minutos, até que esteja bem quente e distribuído na sopa.","image_url":"/recetas/ajiaco-colombiano/paso-completo-06-20261103.webp","image_alt":"Devolva o frango"},{"title":"Sirva","content":"Sirva o ajiaco quente com creme de leite, alcaparras e abacate. Esses acompanhamentos podem ser servidos à parte ou diretamente em cada prato, conforme preferir.","image_alt":"Servindo ajiaco colombiano quente em um prato com creme de leite, alcaparras e abacate","image_url":"/recetas/ajiaco-colombiano/paso-06.webp"}]},{"id":"fcef53fc-f3a0-4a0a-b593-ae87d1630b6b","expected_steps":[{"title":"Reis kochen","content":"Den braunen Reis nach Packungsanweisung kochen.","image_alt":"Frisch gekochter brauner Reis im Topf mit Holzlöffel","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Tofu marinieren und backen","content":"In der Zwischenzeit den marinierten, gebackenen Tofu zubereiten. Den Tofu würfeln und mindestens 30 Minuten in einer Mischung aus Sojasauce, Knoblauch und Ingwer marinieren. Anschließend 20-25 Minuten bei 200°C backen.","image_alt":"Goldbraune Tofuwürfel auf einem Blech mit der Marinade daneben","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Brokkoli dämpfen","content":"Den Brokkoli etwa 5-7 Minuten dämpfen, bis er weich, aber noch bissfest ist.","image_alt":"Leuchtend grüne Brokkoliröschen beim Dämpfen","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Die Bowl anrichten","content":"Den gekochten Reis auf vier Schüsseln verteilen. Mit schwarzen Bohnen, Brokkoli, geraspelten Karotten, Kirschtomaten, Avocado und gebackenem Tofu belegen.","image_alt":"Anrichten der Bowl mit Reis, Brokkoli, schwarzen Bohnen, Karotte, Tomate, Avocado und Tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Sesam bestreuen","content":"Die gerösteten Sesamsamen über jede Bowl streuen und servieren."}],"new_steps":[{"title":"Reis kochen","content":"Den braunen Reis nach Packungsanweisung kochen.","image_alt":"Frisch gekochter brauner Reis im Topf mit Holzlöffel","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Tofu marinieren und backen","content":"In der Zwischenzeit den marinierten, gebackenen Tofu zubereiten. Den Tofu würfeln und mindestens 30 Minuten in einer Mischung aus Sojasauce, Knoblauch und Ingwer marinieren. Anschließend 20-25 Minuten bei 200°C backen.","image_alt":"Goldbraune Tofuwürfel auf einem Blech mit der Marinade daneben","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Brokkoli dämpfen","content":"Den Brokkoli etwa 5-7 Minuten dämpfen, bis er weich, aber noch bissfest ist.","image_alt":"Leuchtend grüne Brokkoliröschen beim Dämpfen","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Die Bowl anrichten","content":"Den gekochten Reis auf vier Schüsseln verteilen. Mit schwarzen Bohnen, Brokkoli, geraspelten Karotten, Kirschtomaten, Avocado und gebackenem Tofu belegen.","image_alt":"Anrichten der Bowl mit Reis, Brokkoli, schwarzen Bohnen, Karotte, Tomate, Avocado und Tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Sesam bestreuen","content":"Die gerösteten Sesamsamen über jede Bowl streuen und servieren.","image_url":"/recetas/buddha-bowl/paso-completo-05-20261103.webp","image_alt":"Sesam bestreuen"}]},{"id":"7b5b0a43-12ae-4f6a-891d-2ea3540498c9","expected_steps":[{"title":"Cook the rice","content":"Cook the brown rice according to the package instructions.","image_alt":"Freshly cooked brown rice in a pot with a wooden spoon","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marinate and bake the tofu","content":"Meanwhile, prepare the marinated baked tofu. Cut the tofu into cubes and marinate it in a mixture of soy sauce, garlic and ginger for at least 30 minutes. Then bake for 20-25 minutes at 200°C.","image_alt":"Golden baked tofu cubes on a tray with the marinade on the side","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Steam the broccoli","content":"Steam the broccoli for about 5-7 minutes, until tender but still crisp.","image_alt":"Bright green broccoli florets steaming","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Assemble the bowl","content":"Divide the cooked rice among four bowls. Top with the black beans, broccoli, shredded carrots, cherry tomatoes, avocado and baked tofu.","image_alt":"Assembling the bowl with rice, broccoli, black beans, carrot, tomato, avocado and tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Sprinkle the sesame seeds","content":"Sprinkle the toasted sesame seeds over each bowl and serve."}],"new_steps":[{"title":"Cook the rice","content":"Cook the brown rice according to the package instructions.","image_alt":"Freshly cooked brown rice in a pot with a wooden spoon","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marinate and bake the tofu","content":"Meanwhile, prepare the marinated baked tofu. Cut the tofu into cubes and marinate it in a mixture of soy sauce, garlic and ginger for at least 30 minutes. Then bake for 20-25 minutes at 200°C.","image_alt":"Golden baked tofu cubes on a tray with the marinade on the side","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Steam the broccoli","content":"Steam the broccoli for about 5-7 minutes, until tender but still crisp.","image_alt":"Bright green broccoli florets steaming","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Assemble the bowl","content":"Divide the cooked rice among four bowls. Top with the black beans, broccoli, shredded carrots, cherry tomatoes, avocado and baked tofu.","image_alt":"Assembling the bowl with rice, broccoli, black beans, carrot, tomato, avocado and tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Sprinkle the sesame seeds","content":"Sprinkle the toasted sesame seeds over each bowl and serve.","image_url":"/recetas/buddha-bowl/paso-completo-05-20261103.webp","image_alt":"Sprinkle the sesame seeds"}]},{"id":"885461b6-4e1c-45ac-aa61-3f90b9c49e34","expected_steps":[{"title":"Cocina el arroz","content":"Cocina el arroz integral según las instrucciones del paquete.","image_alt":"Arroz integral recién cocido en una olla con una cuchara de madera","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marina y hornea el tofu","content":"Mientras tanto, prepara el tofu marinado y horneado. Corta el tofu en cubos y marínalo en una mezcla de salsa de soja, ajo y jengibre durante al menos 30 minutos. Luego, hornéalo 20-25 minutos a 200°C.","image_alt":"Cubos de tofu horneados y dorados en una bandeja con la marinada al lado","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cocina el brócoli al vapor","content":"Cocina el brócoli al vapor durante unos 5-7 minutos, hasta que esté tierno pero aún crujiente.","image_alt":"Floretes de brócoli verde brillante cocinándose al vapor","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Arma el bowl","content":"Divide el arroz cocido en cuatro tazones. Coloca encima los frijoles negros, el brócoli, las zanahorias ralladas, los tomates cherry, el aguacate y el tofu horneado.","image_alt":"Armando el bowl con arroz, brócoli, frijoles negros, zanahoria, tomate, aguacate y tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Espolvorea las semillas de sésamo","content":"Espolvorea las semillas de sésamo tostadas por encima de cada bowl y sirve."}],"new_steps":[{"title":"Cocina el arroz","content":"Cocina el arroz integral según las instrucciones del paquete.","image_alt":"Arroz integral recién cocido en una olla con una cuchara de madera","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marina y hornea el tofu","content":"Mientras tanto, prepara el tofu marinado y horneado. Corta el tofu en cubos y marínalo en una mezcla de salsa de soja, ajo y jengibre durante al menos 30 minutos. Luego, hornéalo 20-25 minutos a 200°C.","image_alt":"Cubos de tofu horneados y dorados en una bandeja con la marinada al lado","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cocina el brócoli al vapor","content":"Cocina el brócoli al vapor durante unos 5-7 minutos, hasta que esté tierno pero aún crujiente.","image_alt":"Floretes de brócoli verde brillante cocinándose al vapor","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Arma el bowl","content":"Divide el arroz cocido en cuatro tazones. Coloca encima los frijoles negros, el brócoli, las zanahorias ralladas, los tomates cherry, el aguacate y el tofu horneado.","image_alt":"Armando el bowl con arroz, brócoli, frijoles negros, zanahoria, tomate, aguacate y tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Espolvorea las semillas de sésamo","content":"Espolvorea las semillas de sésamo tostadas por encima de cada bowl y sirve.","image_url":"/recetas/buddha-bowl/paso-completo-05-20261103.webp","image_alt":"Espolvorea las semillas de sésamo"}]},{"id":"0ba89666-ffd5-41be-b6f5-e22e468054db","expected_steps":[{"title":"Cuis le riz","content":"Cuis le riz complet selon les instructions du paquet.","image_alt":"Riz complet fraîchement cuit dans une casserole avec une cuillère en bois","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marine et cuis le tofu","content":"Pendant ce temps, prépare le tofu mariné et cuit au four. Coupe le tofu en cubes et fais-le mariner dans un mélange de sauce soja, d'ail et de gingembre pendant au moins 30 minutes. Fais-le ensuite cuire 20-25 minutes à 200°C.","image_alt":"Cubes de tofu dorés cuits au four sur une plaque avec la marinade à côté","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cuis le brocoli à la vapeur","content":"Fais cuire le brocoli à la vapeur pendant environ 5-7 minutes, jusqu'à ce qu'il soit tendre mais encore croquant.","image_alt":"Fleurettes de brocoli vert vif cuisant à la vapeur","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Assemble le bowl","content":"Répartis le riz cuit dans quatre bols. Ajoute par-dessus les haricots noirs, le brocoli, les carottes râpées, les tomates cerises, l'avocat et le tofu cuit.","image_alt":"Assemblage du bowl avec riz, brocoli, haricots noirs, carotte, tomate, avocat et tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Saupoudre de sésame","content":"Saupoudre les graines de sésame grillées sur chaque bowl et sers."}],"new_steps":[{"title":"Cuis le riz","content":"Cuis le riz complet selon les instructions du paquet.","image_alt":"Riz complet fraîchement cuit dans une casserole avec une cuillère en bois","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marine et cuis le tofu","content":"Pendant ce temps, prépare le tofu mariné et cuit au four. Coupe le tofu en cubes et fais-le mariner dans un mélange de sauce soja, d'ail et de gingembre pendant au moins 30 minutes. Fais-le ensuite cuire 20-25 minutes à 200°C.","image_alt":"Cubes de tofu dorés cuits au four sur une plaque avec la marinade à côté","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cuis le brocoli à la vapeur","content":"Fais cuire le brocoli à la vapeur pendant environ 5-7 minutes, jusqu'à ce qu'il soit tendre mais encore croquant.","image_alt":"Fleurettes de brocoli vert vif cuisant à la vapeur","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Assemble le bowl","content":"Répartis le riz cuit dans quatre bols. Ajoute par-dessus les haricots noirs, le brocoli, les carottes râpées, les tomates cerises, l'avocat et le tofu cuit.","image_alt":"Assemblage du bowl avec riz, brocoli, haricots noirs, carotte, tomate, avocat et tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Saupoudre de sésame","content":"Saupoudre les graines de sésame grillées sur chaque bowl et sers.","image_url":"/recetas/buddha-bowl/paso-completo-05-20261103.webp","image_alt":"Saupoudre de sésame"}]},{"id":"2fdce208-44c4-4359-b3c8-c0caaa96c315","expected_steps":[{"title":"Cuoci il riso","content":"Cuoci il riso integrale secondo le istruzioni della confezione.","image_alt":"Riso integrale appena cotto in una pentola con un cucchiaio di legno","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marina e cuoci il tofu","content":"Nel frattempo, prepara il tofu marinato al forno. Taglia il tofu a cubetti e marinalo in un mix di salsa di soia, aglio e zenzero per almeno 30 minuti. Poi cuoci in forno 20-25 minuti a 200°C.","image_alt":"Cubetti di tofu dorati al forno su una teglia con la marinata a lato","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cuoci il broccolo al vapore","content":"Cuoci il broccolo al vapore per circa 5-7 minuti, finché è tenero ma ancora croccante.","image_alt":"Cimette di broccolo verde brillante cotte al vapore","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Componi la bowl","content":"Dividi il riso cotto in quattro ciotole. Aggiungi sopra i fagioli neri, il broccolo, le carote grattugiate, i pomodorini, l'avocado e il tofu al forno.","image_alt":"Composizione della bowl con riso, broccolo, fagioli neri, carota, pomodoro, avocado e tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Cospargi di sesamo","content":"Cospargi i semi di sesamo tostati su ogni bowl e servi."}],"new_steps":[{"title":"Cuoci il riso","content":"Cuoci il riso integrale secondo le istruzioni della confezione.","image_alt":"Riso integrale appena cotto in una pentola con un cucchiaio di legno","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marina e cuoci il tofu","content":"Nel frattempo, prepara il tofu marinato al forno. Taglia il tofu a cubetti e marinalo in un mix di salsa di soia, aglio e zenzero per almeno 30 minuti. Poi cuoci in forno 20-25 minuti a 200°C.","image_alt":"Cubetti di tofu dorati al forno su una teglia con la marinata a lato","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cuoci il broccolo al vapore","content":"Cuoci il broccolo al vapore per circa 5-7 minuti, finché è tenero ma ancora croccante.","image_alt":"Cimette di broccolo verde brillante cotte al vapore","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Componi la bowl","content":"Dividi il riso cotto in quattro ciotole. Aggiungi sopra i fagioli neri, il broccolo, le carote grattugiate, i pomodorini, l'avocado e il tofu al forno.","image_alt":"Composizione della bowl con riso, broccolo, fagioli neri, carota, pomodoro, avocado e tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Cospargi di sesamo","content":"Cospargi i semi di sesamo tostati su ogni bowl e servi.","image_url":"/recetas/buddha-bowl/paso-completo-05-20261103.webp","image_alt":"Cospargi di sesamo"}]},{"id":"c91e0544-5c47-48de-b7d1-77d1c8fb0fdc","expected_steps":[{"title":"ご飯を炊く","content":"玄米をパッケージの指示通りに炊きます。","image_alt":"木のスプーンが入った鍋の中の炊きたての玄米","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"豆腐をマリネして焼く","content":"その間に、マリネして焼いた豆腐を準備します。豆腐を角切りにし、しょうゆ、にんにく、しょうがを混ぜたマリネ液に最低30分漬けます。その後200°Cのオーブンで20〜25分焼きます。","image_alt":"マリネ液の隣に置かれた、天板の上のこんがり焼けた豆腐の角切り","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"ブロッコリーを蒸す","content":"ブロッコリーを5〜7分ほど蒸し、柔らかくも歯ごたえが残る程度にします。","image_alt":"蒸されている鮮やかな緑色のブロッコリーの小房","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"ボウルを盛り付ける","content":"炊いたご飯を4つのボウルに分けます。上に黒豆、ブロッコリー、にんじん、ミニトマト、アボカド、焼いた豆腐をのせます。","image_alt":"ご飯、ブロッコリー、黒豆、にんじん、トマト、アボカド、豆腐でボウルを盛り付けているところ","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"ごまを振りかける","content":"炒りごまを各ボウルに振りかけて完成です。"}],"new_steps":[{"title":"ご飯を炊く","content":"玄米をパッケージの指示通りに炊きます。","image_alt":"木のスプーンが入った鍋の中の炊きたての玄米","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"豆腐をマリネして焼く","content":"その間に、マリネして焼いた豆腐を準備します。豆腐を角切りにし、しょうゆ、にんにく、しょうがを混ぜたマリネ液に最低30分漬けます。その後200°Cのオーブンで20〜25分焼きます。","image_alt":"マリネ液の隣に置かれた、天板の上のこんがり焼けた豆腐の角切り","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"ブロッコリーを蒸す","content":"ブロッコリーを5〜7分ほど蒸し、柔らかくも歯ごたえが残る程度にします。","image_alt":"蒸されている鮮やかな緑色のブロッコリーの小房","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"ボウルを盛り付ける","content":"炊いたご飯を4つのボウルに分けます。上に黒豆、ブロッコリー、にんじん、ミニトマト、アボカド、焼いた豆腐をのせます。","image_alt":"ご飯、ブロッコリー、黒豆、にんじん、トマト、アボカド、豆腐でボウルを盛り付けているところ","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"ごまを振りかける","content":"炒りごまを各ボウルに振りかけて完成です。","image_url":"/recetas/buddha-bowl/paso-completo-05-20261103.webp","image_alt":"ごまを振りかける"}]},{"id":"40c7717b-278c-4fd0-ac0b-407486ea8c93","expected_steps":[{"title":"Cozinhe o arroz","content":"Cozinhe o arroz integral conforme as instruções da embalagem.","image_alt":"Arroz integral recém-cozido em uma panela com uma colher de pau","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marine e asse o tofu","content":"Enquanto isso, prepare o tofu marinado e assado. Corte o tofu em cubos e marine em uma mistura de molho de soja, alho e gengibre por pelo menos 30 minutos. Depois asse por 20 a 25 minutos a 200°C.","image_alt":"Cubos de tofu dourados assados em uma assadeira com a marinada ao lado","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cozinhe o brócolis no vapor","content":"Cozinhe o brócolis no vapor por cerca de 5 a 7 minutos, até ficar macio mas ainda crocante.","image_alt":"Floretes de brócolis verde-vivo cozinhando no vapor","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Monte o bowl","content":"Divida o arroz cozido em quatro tigelas. Coloque por cima o feijão preto, o brócolis, a cenoura ralada, os tomates cereja, o abacate e o tofu assado.","image_alt":"Montagem do bowl com arroz, brócolis, feijão preto, cenoura, tomate, abacate e tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Polvilhe as sementes de gergelim","content":"Polvilhe as sementes de gergelim torradas sobre cada bowl e sirva."}],"new_steps":[{"title":"Cozinhe o arroz","content":"Cozinhe o arroz integral conforme as instruções da embalagem.","image_alt":"Arroz integral recém-cozido em uma panela com uma colher de pau","image_url":"/recetas/buddha-bowl/paso-02.webp"},{"title":"Marine e asse o tofu","content":"Enquanto isso, prepare o tofu marinado e assado. Corte o tofu em cubos e marine em uma mistura de molho de soja, alho e gengibre por pelo menos 30 minutos. Depois asse por 20 a 25 minutos a 200°C.","image_alt":"Cubos de tofu dourados assados em uma assadeira com a marinada ao lado","image_url":"/recetas/buddha-bowl/paso-03.webp"},{"title":"Cozinhe o brócolis no vapor","content":"Cozinhe o brócolis no vapor por cerca de 5 a 7 minutos, até ficar macio mas ainda crocante.","image_alt":"Floretes de brócolis verde-vivo cozinhando no vapor","image_url":"/recetas/buddha-bowl/paso-04.webp"},{"title":"Monte o bowl","content":"Divida o arroz cozido em quatro tigelas. Coloque por cima o feijão preto, o brócolis, a cenoura ralada, os tomates cereja, o abacate e o tofu assado.","image_alt":"Montagem do bowl com arroz, brócolis, feijão preto, cenoura, tomate, abacate e tofu","image_url":"/recetas/buddha-bowl/paso-05.webp"},{"title":"Polvilhe as sementes de gergelim","content":"Polvilhe as sementes de gergelim torradas sobre cada bowl e sirva.","image_url":"/recetas/buddha-bowl/paso-completo-05-20261103.webp","image_alt":"Polvilhe as sementes de gergelim"}]},{"id":"d358573b-8cfa-4cf4-aa0a-cc78474360f0","expected_steps":[{"title":"Obst schneiden","content":"Das gesamte Obst waschen und in kleine Stücke schneiden, auch die Kiwi.","image_alt":"Holzbrett mit geschnittener Banane, Erdbeeren, Ananas, Mango, Wassermelone, Trauben und Kiwi","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Alles in den Mixer geben","content":"Das geschnittene Obst zusammen mit der Sahne, dem zerstoßenen Eis und dem Zucker (falls verwendet) in einen Mixer geben.","image_alt":"Geschnittenes Obst und Sahne werden mit Eis in den Mixer gegeben","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Glatt mixen","content":"Alle Zutaten mixen, bis eine glatte, gleichmäßige Mischung entsteht.","image_alt":"Glatte, gleichmäßige Fruchtshake-Mischung im Mixer","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Abschmecken und Süße anpassen","content":"Den Shake probieren und bei Bedarf den Zucker nach Geschmack anpassen."},{"title":"In hohen Gläsern servieren","content":"Den Shake in hohen Gläsern servieren und nach Belieben mit einer Kiwischeibe oder einem Minzblatt garnieren.","image_alt":"Fruchtshake wird in ein hohes Glas gegossen","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Trinkhalm hinzufügen","content":"Du kannst einen Trinkhalm hinzufügen, um ihn bequem zu trinken.","image_alt":"Der Shake wird mit einer Kiwischeibe, Minze und einem Trinkhalm garniert","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Gut gekühlt genießen","content":"Genieße deinen Fruchtshake mit Sahne schön kalt","image_alt":"Zwei Gläser Fruchtshake mit Sahne, bereit zum Genießen","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}],"new_steps":[{"title":"Obst schneiden","content":"Das gesamte Obst waschen und in kleine Stücke schneiden, auch die Kiwi.","image_alt":"Holzbrett mit geschnittener Banane, Erdbeeren, Ananas, Mango, Wassermelone, Trauben und Kiwi","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Alles in den Mixer geben","content":"Das geschnittene Obst zusammen mit der Sahne, dem zerstoßenen Eis und dem Zucker (falls verwendet) in einen Mixer geben.","image_alt":"Geschnittenes Obst und Sahne werden mit Eis in den Mixer gegeben","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Glatt mixen","content":"Alle Zutaten mixen, bis eine glatte, gleichmäßige Mischung entsteht.","image_alt":"Glatte, gleichmäßige Fruchtshake-Mischung im Mixer","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Abschmecken und Süße anpassen","content":"Den Shake probieren und bei Bedarf den Zucker nach Geschmack anpassen.","image_url":"/recetas/batido-de-frutas-con-crema/paso-completo-04-20261103.webp","image_alt":"Abschmecken und Süße anpassen"},{"title":"In hohen Gläsern servieren","content":"Den Shake in hohen Gläsern servieren und nach Belieben mit einer Kiwischeibe oder einem Minzblatt garnieren.","image_alt":"Fruchtshake wird in ein hohes Glas gegossen","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Trinkhalm hinzufügen","content":"Du kannst einen Trinkhalm hinzufügen, um ihn bequem zu trinken.","image_alt":"Der Shake wird mit einer Kiwischeibe, Minze und einem Trinkhalm garniert","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Gut gekühlt genießen","content":"Genieße deinen Fruchtshake mit Sahne schön kalt","image_alt":"Zwei Gläser Fruchtshake mit Sahne, bereit zum Genießen","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}]},{"id":"1fb423f8-2ad0-47a1-99c9-a91642555aa7","expected_steps":[{"title":"Cut the fruit","content":"Wash and cut all the fruit into small pieces, including the kiwi.","image_alt":"Wooden board with chopped banana, strawberries, pineapple, mango, watermelon, grapes and kiwi","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Add everything to the blender","content":"In a blender, place the chopped fruit along with the heavy cream, crushed ice and sugar (if using).","image_alt":"Chopped fruit and cream being added to the blender with ice","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Blend until smooth","content":"Blend all the ingredients until you get a smooth, even mixture.","image_alt":"Smooth, even fruit smoothie mixture in the blender","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Taste and adjust the sweetness","content":"Taste the smoothie and adjust the sugar if needed, to your preference."},{"title":"Serve in tall glasses","content":"Serve the smoothie in tall glasses and garnish with a kiwi slice or a mint leaf if you like.","image_alt":"Fruit smoothie being poured into a tall glass","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Add a straw","content":"You can add a straw to drink it comfortably.","image_alt":"Garnishing the smoothie with a kiwi slice, mint and a straw","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Enjoy well chilled","content":"Enjoy your fruit smoothie with cream nice and cold","image_alt":"Two glasses of fruit smoothie with cream ready to enjoy","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}],"new_steps":[{"title":"Cut the fruit","content":"Wash and cut all the fruit into small pieces, including the kiwi.","image_alt":"Wooden board with chopped banana, strawberries, pineapple, mango, watermelon, grapes and kiwi","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Add everything to the blender","content":"In a blender, place the chopped fruit along with the heavy cream, crushed ice and sugar (if using).","image_alt":"Chopped fruit and cream being added to the blender with ice","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Blend until smooth","content":"Blend all the ingredients until you get a smooth, even mixture.","image_alt":"Smooth, even fruit smoothie mixture in the blender","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Taste and adjust the sweetness","content":"Taste the smoothie and adjust the sugar if needed, to your preference.","image_url":"/recetas/batido-de-frutas-con-crema/paso-completo-04-20261103.webp","image_alt":"Taste and adjust the sweetness"},{"title":"Serve in tall glasses","content":"Serve the smoothie in tall glasses and garnish with a kiwi slice or a mint leaf if you like.","image_alt":"Fruit smoothie being poured into a tall glass","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Add a straw","content":"You can add a straw to drink it comfortably.","image_alt":"Garnishing the smoothie with a kiwi slice, mint and a straw","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Enjoy well chilled","content":"Enjoy your fruit smoothie with cream nice and cold","image_alt":"Two glasses of fruit smoothie with cream ready to enjoy","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}]},{"id":"e7da4502-2064-4bd6-b275-56c9c0b54dd0","expected_steps":[{"title":"Corta las frutas","content":"Lava y corta todas las frutas en trozos pequeños, incluyendo el kiwi.","image_alt":"Tabla de madera con plátano, fresas, piña, mango, sandía, uvas y kiwi cortados","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Agrega todo a la licuadora","content":"En una licuadora, coloca las frutas cortadas junto con la crema de leche, el hielo triturado y el azúcar (si lo deseas).","image_alt":"Frutas troceadas y crema de leche siendo añadidas a la licuadora con hielo","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Licúa hasta que quede suave","content":"Licúa durante 1-2 minutos, hasta obtener una mezcla suave y homogénea.","image_alt":"Mezcla de batido de frutas suave y homogénea en la licuadora","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Prueba y ajusta el dulzor","content":"Prueba el batido y ajusta el azúcar si es necesario, según tu preferencia de dulzor."},{"title":"Sirve en vasos altos","content":"Sirve el batido en vasos altos y decóralos con una rodaja de kiwi o una hoja de menta si lo deseas.","image_alt":"Batido de frutas siendo servido en un vaso alto","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Añade la pajita","content":"Puedes agregar una pajita para beberlo con comodidad.","image_alt":"Decorando el batido con una rodaja de kiwi, menta y una pajita","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Disfruta bien frío","content":"Disfruta tu batido de frutas con crema bien frío.","image_alt":"Dos vasos de batido de frutas con crema listos para disfrutar","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}],"new_steps":[{"title":"Corta las frutas","content":"Lava y corta todas las frutas en trozos pequeños, incluyendo el kiwi.","image_alt":"Tabla de madera con plátano, fresas, piña, mango, sandía, uvas y kiwi cortados","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Agrega todo a la licuadora","content":"En una licuadora, coloca las frutas cortadas junto con la crema de leche, el hielo triturado y el azúcar (si lo deseas).","image_alt":"Frutas troceadas y crema de leche siendo añadidas a la licuadora con hielo","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Licúa hasta que quede suave","content":"Licúa durante 1-2 minutos, hasta obtener una mezcla suave y homogénea.","image_alt":"Mezcla de batido de frutas suave y homogénea en la licuadora","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Prueba y ajusta el dulzor","content":"Prueba el batido y ajusta el azúcar si es necesario, según tu preferencia de dulzor.","image_url":"/recetas/batido-de-frutas-con-crema/paso-completo-04-20261103.webp","image_alt":"Prueba y ajusta el dulzor"},{"title":"Sirve en vasos altos","content":"Sirve el batido en vasos altos y decóralos con una rodaja de kiwi o una hoja de menta si lo deseas.","image_alt":"Batido de frutas siendo servido en un vaso alto","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Añade la pajita","content":"Puedes agregar una pajita para beberlo con comodidad.","image_alt":"Decorando el batido con una rodaja de kiwi, menta y una pajita","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Disfruta bien frío","content":"Disfruta tu batido de frutas con crema bien frío.","image_alt":"Dos vasos de batido de frutas con crema listos para disfrutar","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}]},{"id":"e3a78b33-8acd-4faf-8a2b-cb1be0e32d1c","expected_steps":[{"title":"Coupez les fruits","content":"Lavez et coupez tous les fruits en petits morceaux, y compris le kiwi.","image_alt":"Planche en bois avec banane, fraises, ananas, mangue, pastèque, raisins et kiwi coupés","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Ajoutez tout dans le mixeur","content":"Dans un mixeur, placez les fruits coupés avec la crème, la glace pilée et le sucre (si utilisé).","image_alt":"Fruits coupés et crème ajoutés au mixeur avec de la glace","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Mixez jusqu'à consistance lisse","content":"Mixez tous les ingrédients jusqu'à obtenir un mélange lisse et homogène.","image_alt":"Mélange de smoothie de fruits lisse et homogène dans le mixeur","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Goûtez et ajustez le sucre","content":"Goûtez le smoothie et ajustez le sucre si nécessaire, selon votre préférence."},{"title":"Servez dans des grands verres","content":"Servez le smoothie dans des grands verres et décorez-le d'une tranche de kiwi ou d'une feuille de menthe si vous le souhaitez.","image_alt":"Smoothie de fruits versé dans un grand verre","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Ajoutez une paille","content":"Vous pouvez ajouter une paille pour le boire confortablement.","image_alt":"Smoothie décoré d'une tranche de kiwi, de menthe et d'une paille","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Dégustez bien frais","content":"Dégustez votre smoothie de fruits à la crème bien frais","image_alt":"Deux verres de smoothie de fruits à la crème prêts à déguster","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}],"new_steps":[{"title":"Coupez les fruits","content":"Lavez et coupez tous les fruits en petits morceaux, y compris le kiwi.","image_alt":"Planche en bois avec banane, fraises, ananas, mangue, pastèque, raisins et kiwi coupés","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Ajoutez tout dans le mixeur","content":"Dans un mixeur, placez les fruits coupés avec la crème, la glace pilée et le sucre (si utilisé).","image_alt":"Fruits coupés et crème ajoutés au mixeur avec de la glace","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Mixez jusqu'à consistance lisse","content":"Mixez tous les ingrédients jusqu'à obtenir un mélange lisse et homogène.","image_alt":"Mélange de smoothie de fruits lisse et homogène dans le mixeur","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Goûtez et ajustez le sucre","content":"Goûtez le smoothie et ajustez le sucre si nécessaire, selon votre préférence.","image_url":"/recetas/batido-de-frutas-con-crema/paso-completo-04-20261103.webp","image_alt":"Goûtez et ajustez le sucre"},{"title":"Servez dans des grands verres","content":"Servez le smoothie dans des grands verres et décorez-le d'une tranche de kiwi ou d'une feuille de menthe si vous le souhaitez.","image_alt":"Smoothie de fruits versé dans un grand verre","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Ajoutez une paille","content":"Vous pouvez ajouter une paille pour le boire confortablement.","image_alt":"Smoothie décoré d'une tranche de kiwi, de menthe et d'une paille","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Dégustez bien frais","content":"Dégustez votre smoothie de fruits à la crème bien frais","image_alt":"Deux verres de smoothie de fruits à la crème prêts à déguster","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}]},{"id":"ba6014ea-b033-4f37-a948-8df00b181cae","expected_steps":[{"title":"Taglia la frutta","content":"Lava e taglia tutta la frutta a pezzetti, incluso il kiwi.","image_alt":"Tagliere di legno con banana, fragole, ananas, mango, anguria, uva e kiwi tagliati","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Aggiungi tutto nel frullatore","content":"In un frullatore, metti la frutta tagliata insieme alla panna, al ghiaccio tritato e allo zucchero (se lo usi).","image_alt":"Frutta tagliata e panna aggiunte al frullatore con ghiaccio","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Frulla fino a ottenere una consistenza liscia","content":"Frulla tutti gli ingredienti fino a ottenere un composto liscio e omogeneo.","image_alt":"Composto di frullato di frutta liscio e omogeneo nel frullatore","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Assaggia e regola la dolcezza","content":"Assaggia il frullato e regola lo zucchero se necessario, secondo il tuo gusto."},{"title":"Servi in bicchieri alti","content":"Servi il frullato in bicchieri alti e decoralo con una fetta di kiwi o una foglia di menta se lo desideri.","image_alt":"Frullato di frutta versato in un bicchiere alto","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Aggiungi una cannuccia","content":"Puoi aggiungere una cannuccia per berlo comodamente.","image_alt":"Frullato decorato con una fetta di kiwi, menta e una cannuccia","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Gustalo ben freddo","content":"Gustati il tuo frullato di frutta con panna ben freddo","image_alt":"Due bicchieri di frullato di frutta con panna pronti da gustare","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}],"new_steps":[{"title":"Taglia la frutta","content":"Lava e taglia tutta la frutta a pezzetti, incluso il kiwi.","image_alt":"Tagliere di legno con banana, fragole, ananas, mango, anguria, uva e kiwi tagliati","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Aggiungi tutto nel frullatore","content":"In un frullatore, metti la frutta tagliata insieme alla panna, al ghiaccio tritato e allo zucchero (se lo usi).","image_alt":"Frutta tagliata e panna aggiunte al frullatore con ghiaccio","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Frulla fino a ottenere una consistenza liscia","content":"Frulla tutti gli ingredienti fino a ottenere un composto liscio e omogeneo.","image_alt":"Composto di frullato di frutta liscio e omogeneo nel frullatore","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Assaggia e regola la dolcezza","content":"Assaggia il frullato e regola lo zucchero se necessario, secondo il tuo gusto.","image_url":"/recetas/batido-de-frutas-con-crema/paso-completo-04-20261103.webp","image_alt":"Assaggia e regola la dolcezza"},{"title":"Servi in bicchieri alti","content":"Servi il frullato in bicchieri alti e decoralo con una fetta di kiwi o una foglia di menta se lo desideri.","image_alt":"Frullato di frutta versato in un bicchiere alto","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Aggiungi una cannuccia","content":"Puoi aggiungere una cannuccia per berlo comodamente.","image_alt":"Frullato decorato con una fetta di kiwi, menta e una cannuccia","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Gustalo ben freddo","content":"Gustati il tuo frullato di frutta con panna ben freddo","image_alt":"Due bicchieri di frullato di frutta con panna pronti da gustare","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}]},{"id":"4fc058ef-edec-4455-a2af-5067d69219c1","expected_steps":[{"title":"フルーツを切る","content":"すべてのフルーツを洗い、キウイも含めて小さく切る。","image_alt":"切られたバナナ、いちご、パイナップル、マンゴー、スイカ、ぶどう、キウイが並ぶ木製のまな板","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"ミキサーにすべて入れる","content":"ミキサーに切ったフルーツと生クリーム、砕いた氷、お好みで砂糖を入れる。","image_alt":"切ったフルーツと生クリームが氷と一緒にミキサーに加えられる様子","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"なめらかになるまで攪拌する","content":"すべての材料をなめらかで均一になるまで攪拌する。","image_alt":"ミキサーの中でなめらかに仕上がったフルーツスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"味見して甘さを調整する","content":"スムージーを味見し、好みに応じて砂糖の量を調整する。"},{"title":"背の高いグラスに注ぐ","content":"スムージーを背の高いグラスに注ぎ、お好みでキウイのスライスやミントの葉を飾る。","image_alt":"背の高いグラスに注がれるフルーツスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"ストローを添える","content":"飲みやすいようにストローを添えるのもおすすめ。","image_alt":"キウイのスライス、ミント、ストローで飾られるスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"よく冷えたまま楽しむ","content":"フルーツと生クリームのスムージーをよく冷えたまま楽しんでください","image_alt":"楽しむ準備ができた2杯のフルーツ生クリームスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}],"new_steps":[{"title":"フルーツを切る","content":"すべてのフルーツを洗い、キウイも含めて小さく切る。","image_alt":"切られたバナナ、いちご、パイナップル、マンゴー、スイカ、ぶどう、キウイが並ぶ木製のまな板","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"ミキサーにすべて入れる","content":"ミキサーに切ったフルーツと生クリーム、砕いた氷、お好みで砂糖を入れる。","image_alt":"切ったフルーツと生クリームが氷と一緒にミキサーに加えられる様子","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"なめらかになるまで攪拌する","content":"すべての材料をなめらかで均一になるまで攪拌する。","image_alt":"ミキサーの中でなめらかに仕上がったフルーツスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"味見して甘さを調整する","content":"スムージーを味見し、好みに応じて砂糖の量を調整する。","image_url":"/recetas/batido-de-frutas-con-crema/paso-completo-04-20261103.webp","image_alt":"味見して甘さを調整する"},{"title":"背の高いグラスに注ぐ","content":"スムージーを背の高いグラスに注ぎ、お好みでキウイのスライスやミントの葉を飾る。","image_alt":"背の高いグラスに注がれるフルーツスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"ストローを添える","content":"飲みやすいようにストローを添えるのもおすすめ。","image_alt":"キウイのスライス、ミント、ストローで飾られるスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"よく冷えたまま楽しむ","content":"フルーツと生クリームのスムージーをよく冷えたまま楽しんでください","image_alt":"楽しむ準備ができた2杯のフルーツ生クリームスムージー","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}]},{"id":"55912d6c-d510-4671-94be-bae4690d0470","expected_steps":[{"title":"Corte as frutas","content":"Lave e corte todas as frutas em pedaços pequenos, incluindo o kiwi.","image_alt":"Tábua de madeira com banana, morangos, abacaxi, manga, melancia, uvas e kiwi cortados","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Adicione tudo no liquidificador","content":"No liquidificador, coloque as frutas cortadas junto com o creme de leite, o gelo triturado e o açúcar (se for usar).","image_alt":"Frutas picadas e creme de leite sendo adicionados ao liquidificador com gelo","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Bata até ficar homogêneo","content":"Bata todos os ingredientes até obter uma mistura lisa e homogênea.","image_alt":"Mistura de batida de frutas lisa e homogênea no liquidificador","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Prove e ajuste o dulçor","content":"Prove a batida e ajuste o açúcar se necessário, conforme sua preferência."},{"title":"Sirva em copos altos","content":"Sirva a batida em copos altos e decore com uma rodela de kiwi ou uma folha de hortelã, se desejar.","image_alt":"Batida de frutas sendo servida em um copo alto","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Adicione um canudo","content":"Você pode adicionar um canudo para beber com mais facilidade.","image_alt":"Decorando a batida com uma rodela de kiwi, hortelã e um canudo","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Aproveite bem gelada","content":"Aproveite sua batida de frutas com creme de leite bem gelada","image_alt":"Dois copos de batida de frutas com creme de leite prontos para aproveitar","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}],"new_steps":[{"title":"Corte as frutas","content":"Lave e corte todas as frutas em pedaços pequenos, incluindo o kiwi.","image_alt":"Tábua de madeira com banana, morangos, abacaxi, manga, melancia, uvas e kiwi cortados","image_url":"/recetas/batido-de-frutas-con-crema/paso-01.webp"},{"title":"Adicione tudo no liquidificador","content":"No liquidificador, coloque as frutas cortadas junto com o creme de leite, o gelo triturado e o açúcar (se for usar).","image_alt":"Frutas picadas e creme de leite sendo adicionados ao liquidificador com gelo","image_url":"/recetas/batido-de-frutas-con-crema/paso-02.webp"},{"title":"Bata até ficar homogêneo","content":"Bata todos os ingredientes até obter uma mistura lisa e homogênea.","image_alt":"Mistura de batida de frutas lisa e homogênea no liquidificador","image_url":"/recetas/batido-de-frutas-con-crema/paso-03.webp"},{"title":"Prove e ajuste o dulçor","content":"Prove a batida e ajuste o açúcar se necessário, conforme sua preferência.","image_url":"/recetas/batido-de-frutas-con-crema/paso-completo-04-20261103.webp","image_alt":"Prove e ajuste o dulçor"},{"title":"Sirva em copos altos","content":"Sirva a batida em copos altos e decore com uma rodela de kiwi ou uma folha de hortelã, se desejar.","image_alt":"Batida de frutas sendo servida em um copo alto","image_url":"/recetas/batido-de-frutas-con-crema/paso-04.webp"},{"title":"Adicione um canudo","content":"Você pode adicionar um canudo para beber com mais facilidade.","image_alt":"Decorando a batida com uma rodela de kiwi, hortelã e um canudo","image_url":"/recetas/batido-de-frutas-con-crema/paso-05.webp"},{"title":"Aproveite bem gelada","content":"Aproveite sua batida de frutas com creme de leite bem gelada","image_alt":"Dois copos de batida de frutas com creme de leite prontos para aproveitar","image_url":"/recetas/batido-de-frutas-con-crema/paso-06.webp"}]},{"id":"5028bcf5-22ca-4786-8b86-83b34168078c","expected_steps":[{"title":"Ofen vorheizen","content":"Den Ofen auf 180 Grad Celsius vorheizen."},{"title":"Hackfleisch mischen","content":"Das Hackfleisch mit Zwiebel, Knoblauch, gekochten Karotten, Paniermehl, Milch, Kreuzkümmel, Salz und Pfeffer vermischen.","image_alt":"Hände vermischen Hackfleisch mit Karotte, Paniermehl und Gewürzen in einer Schüssel","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Braten formen","content":"Einen kompakten, gleichmäßigen Braten formen und auf ein Backblech legen.","image_alt":"Hände formen und pressen den rohen Hackbraten auf dem Blech","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Backen","content":"Als Richtwert etwa 50 Minuten backen, bis die Mitte 71 Grad Celsius erreicht. Mit einem Thermometer prüfen.","image_alt":"Gebackener Hackbraten mit eingestecktem Küchenthermometer","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Sauce zubereiten","content":"Während der Braten im Ofen ist, Zwiebel und Knoblauch für die Sauce anbraten; passierte Tomaten, Tomatensauce, Zucker, Kreuzkümmel und Paprika hinzufügen und einkochen lassen.","image_alt":"Hausgemachte Tomatensauce kocht in einer Pfanne","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Ruhen lassen","content":"Den Braten aus dem Ofen nehmen und etwa 10 Minuten ruhen lassen, bevor er geschnitten wird."},{"title":"Schneiden und servieren","content":"In Scheiben schneiden und mit der Tomatensauce servieren.","image_alt":"Hackbraten in Scheiben geschnitten mit Tomatensauce und einer Sauciere daneben","image_url":"/recetas/rollo-de-carne/paso-07.webp"}],"new_steps":[{"title":"Ofen vorheizen","content":"Den Ofen auf 180 Grad Celsius vorheizen.","image_url":"/recetas/rollo-de-carne/paso-completo-01-20261103.webp","image_alt":"Ofen vorheizen"},{"title":"Hackfleisch mischen","content":"Das Hackfleisch mit Zwiebel, Knoblauch, gekochten Karotten, Paniermehl, Milch, Kreuzkümmel, Salz und Pfeffer vermischen.","image_alt":"Hände vermischen Hackfleisch mit Karotte, Paniermehl und Gewürzen in einer Schüssel","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Braten formen","content":"Einen kompakten, gleichmäßigen Braten formen und auf ein Backblech legen.","image_alt":"Hände formen und pressen den rohen Hackbraten auf dem Blech","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Backen","content":"Als Richtwert etwa 50 Minuten backen, bis die Mitte 71 Grad Celsius erreicht. Mit einem Thermometer prüfen.","image_alt":"Gebackener Hackbraten mit eingestecktem Küchenthermometer","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Sauce zubereiten","content":"Während der Braten im Ofen ist, Zwiebel und Knoblauch für die Sauce anbraten; passierte Tomaten, Tomatensauce, Zucker, Kreuzkümmel und Paprika hinzufügen und einkochen lassen.","image_alt":"Hausgemachte Tomatensauce kocht in einer Pfanne","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Ruhen lassen","content":"Den Braten aus dem Ofen nehmen und etwa 10 Minuten ruhen lassen, bevor er geschnitten wird.","image_url":"/recetas/rollo-de-carne/paso-completo-06-20261103.webp","image_alt":"Ruhen lassen"},{"title":"Schneiden und servieren","content":"In Scheiben schneiden und mit der Tomatensauce servieren.","image_alt":"Hackbraten in Scheiben geschnitten mit Tomatensauce und einer Sauciere daneben","image_url":"/recetas/rollo-de-carne/paso-07.webp"}]},{"id":"5adbf92c-af9b-45ad-8918-bc467b25a557","expected_steps":[{"title":"Preheat the oven","content":"Preheat the oven to 180 C (356 F)."},{"title":"Mix the meat","content":"Mix the meat with the onion, garlic, cooked carrots, breadcrumbs, milk, cumin, salt and pepper.","image_alt":"Hands mixing ground meat with carrot, breadcrumbs and spices in a bowl","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Shape the loaf","content":"Shape a compact, even loaf and place it on a baking tray.","image_alt":"Hands shaping and packing the raw meatloaf on the tray","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Bake","content":"Bake for about 50 minutes as a guide, until the center reaches 71 C (160 F). Check with a thermometer.","image_alt":"Baked meatloaf with a kitchen thermometer inserted","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Make the sauce","content":"While it bakes, saute the onion and garlic for the sauce; add the crushed tomato, tomato sauce, sugar, cumin and paprika, and cook until it thickens.","image_alt":"Homemade tomato sauce cooking in a pan","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Let it rest","content":"Take the loaf out of the oven and let it rest for about 10 minutes before slicing."},{"title":"Slice and serve","content":"Slice and serve with the tomato sauce.","image_alt":"Meatloaf sliced with tomato sauce and a sauce boat alongside","image_url":"/recetas/rollo-de-carne/paso-07.webp"}],"new_steps":[{"title":"Preheat the oven","content":"Preheat the oven to 180 C (356 F).","image_url":"/recetas/rollo-de-carne/paso-completo-01-20261103.webp","image_alt":"Preheat the oven"},{"title":"Mix the meat","content":"Mix the meat with the onion, garlic, cooked carrots, breadcrumbs, milk, cumin, salt and pepper.","image_alt":"Hands mixing ground meat with carrot, breadcrumbs and spices in a bowl","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Shape the loaf","content":"Shape a compact, even loaf and place it on a baking tray.","image_alt":"Hands shaping and packing the raw meatloaf on the tray","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Bake","content":"Bake for about 50 minutes as a guide, until the center reaches 71 C (160 F). Check with a thermometer.","image_alt":"Baked meatloaf with a kitchen thermometer inserted","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Make the sauce","content":"While it bakes, saute the onion and garlic for the sauce; add the crushed tomato, tomato sauce, sugar, cumin and paprika, and cook until it thickens.","image_alt":"Homemade tomato sauce cooking in a pan","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Let it rest","content":"Take the loaf out of the oven and let it rest for about 10 minutes before slicing.","image_url":"/recetas/rollo-de-carne/paso-completo-06-20261103.webp","image_alt":"Let it rest"},{"title":"Slice and serve","content":"Slice and serve with the tomato sauce.","image_alt":"Meatloaf sliced with tomato sauce and a sauce boat alongside","image_url":"/recetas/rollo-de-carne/paso-07.webp"}]},{"id":"fd1ede8d-cf99-42ae-b897-c15698cfa7b9","expected_steps":[{"title":"Precalienta el horno","content":"Precalienta el horno a 180 °C."},{"title":"Mezcla la carne","content":"Mezcla la carne con la cebolla, el ajo, las zanahorias cocidas, el pan rallado, la leche, el comino, la sal y la pimienta.","image_alt":"Manos mezclando la carne molida con zanahoria, pan rallado y especias en un bol","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Forma el rollo","content":"Forma un rollo compacto y uniforme y colócalo en una bandeja.","image_alt":"Manos formando y compactando el rollo de carne crudo sobre la bandeja","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Hornea","content":"Hornea unos 50 minutos como orientación, hasta que el centro alcance 71 °C. Compruébalo con un termómetro.","image_alt":"Rollo de carne horneado con un termómetro de cocina insertado","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prepara la salsa","content":"Mientras se hornea, sofríe la cebolla y el ajo de la salsa; añade el tomate triturado, la salsa de tomate, el azúcar, el comino y el pimentón, y cocina hasta que espese.","image_alt":"Salsa de tomate casera cocinándose en una sartén","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Deja reposar","content":"Saca el rollo del horno y déjalo reposar unos 10 minutos antes de cortarlo."},{"title":"Corta y sirve","content":"Corta en rodajas y sirve con la salsa de tomate.","image_alt":"Rollo de carne cortado en rodajas con salsa de tomate y una salsera al lado","image_url":"/recetas/rollo-de-carne/paso-07.webp"}],"new_steps":[{"title":"Precalienta el horno","content":"Precalienta el horno a 180 °C.","image_url":"/recetas/rollo-de-carne/paso-completo-01-20261103.webp","image_alt":"Precalienta el horno"},{"title":"Mezcla la carne","content":"Mezcla la carne con la cebolla, el ajo, las zanahorias cocidas, el pan rallado, la leche, el comino, la sal y la pimienta.","image_alt":"Manos mezclando la carne molida con zanahoria, pan rallado y especias en un bol","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Forma el rollo","content":"Forma un rollo compacto y uniforme y colócalo en una bandeja.","image_alt":"Manos formando y compactando el rollo de carne crudo sobre la bandeja","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Hornea","content":"Hornea unos 50 minutos como orientación, hasta que el centro alcance 71 °C. Compruébalo con un termómetro.","image_alt":"Rollo de carne horneado con un termómetro de cocina insertado","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prepara la salsa","content":"Mientras se hornea, sofríe la cebolla y el ajo de la salsa; añade el tomate triturado, la salsa de tomate, el azúcar, el comino y el pimentón, y cocina hasta que espese.","image_alt":"Salsa de tomate casera cocinándose en una sartén","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Deja reposar","content":"Saca el rollo del horno y déjalo reposar unos 10 minutos antes de cortarlo.","image_url":"/recetas/rollo-de-carne/paso-completo-06-20261103.webp","image_alt":"Deja reposar"},{"title":"Corta y sirve","content":"Corta en rodajas y sirve con la salsa de tomate.","image_alt":"Rollo de carne cortado en rodajas con salsa de tomate y una salsera al lado","image_url":"/recetas/rollo-de-carne/paso-07.webp"}]},{"id":"549c6ac0-cf6d-415e-b7f6-7918a5d4f839","expected_steps":[{"title":"Préchauffe le four","content":"Préchauffe le four à 180 degrés Celsius."},{"title":"Mélange la viande","content":"Mélange la viande avec l'oignon, l'ail, les carottes cuites, la chapelure, le lait, le cumin, le sel et le poivre.","image_alt":"Mains mélangeant la viande hachée avec carotte, chapelure et épices dans un bol","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Forme le pain","content":"Forme un pain compact et uniforme et dépose-le sur une plaque.","image_alt":"Mains formant et compactant le pain de viande cru sur la plaque","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Cuis au four","content":"Cuis environ 50 minutes à titre indicatif, jusqu'à ce que le centre atteigne 71 degrés Celsius. Vérifie avec un thermomètre.","image_alt":"Pain de viande cuit avec un thermomètre de cuisine inséré","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prépare la sauce","content":"Pendant la cuisson, fais revenir l'oignon et l'ail de la sauce ; ajoute la tomate concassée, la sauce tomate, le sucre, le cumin et le paprika, et cuis jusqu'à ce que ça épaississe.","image_alt":"Sauce tomate maison qui cuit dans une poêle","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Laisse reposer","content":"Sors le pain du four et laisse-le reposer environ 10 minutes avant de le couper."},{"title":"Coupe et sers","content":"Coupe en tranches et sers avec la sauce tomate.","image_alt":"Pain de viande coupe en tranches avec sauce tomate et une saucière à côté","image_url":"/recetas/rollo-de-carne/paso-07.webp"}],"new_steps":[{"title":"Préchauffe le four","content":"Préchauffe le four à 180 degrés Celsius.","image_url":"/recetas/rollo-de-carne/paso-completo-01-20261103.webp","image_alt":"Préchauffe le four"},{"title":"Mélange la viande","content":"Mélange la viande avec l'oignon, l'ail, les carottes cuites, la chapelure, le lait, le cumin, le sel et le poivre.","image_alt":"Mains mélangeant la viande hachée avec carotte, chapelure et épices dans un bol","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Forme le pain","content":"Forme un pain compact et uniforme et dépose-le sur une plaque.","image_alt":"Mains formant et compactant le pain de viande cru sur la plaque","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Cuis au four","content":"Cuis environ 50 minutes à titre indicatif, jusqu'à ce que le centre atteigne 71 degrés Celsius. Vérifie avec un thermomètre.","image_alt":"Pain de viande cuit avec un thermomètre de cuisine inséré","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prépare la sauce","content":"Pendant la cuisson, fais revenir l'oignon et l'ail de la sauce ; ajoute la tomate concassée, la sauce tomate, le sucre, le cumin et le paprika, et cuis jusqu'à ce que ça épaississe.","image_alt":"Sauce tomate maison qui cuit dans une poêle","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Laisse reposer","content":"Sors le pain du four et laisse-le reposer environ 10 minutes avant de le couper.","image_url":"/recetas/rollo-de-carne/paso-completo-06-20261103.webp","image_alt":"Laisse reposer"},{"title":"Coupe et sers","content":"Coupe en tranches et sers avec la sauce tomate.","image_alt":"Pain de viande coupe en tranches avec sauce tomate et une saucière à côté","image_url":"/recetas/rollo-de-carne/paso-07.webp"}]},{"id":"54601cfa-ed1c-457b-99f3-63c219b41b40","expected_steps":[{"title":"Preriscalda il forno","content":"Preriscalda il forno a 180 gradi Celsius."},{"title":"Mescola la carne","content":"Mescola la carne con la cipolla, l'aglio, le carote cotte, il pangrattato, il latte, il cumino, il sale e il pepe.","image_alt":"Mani che mescolano la carne macinata con carota, pangrattato e spezie in una ciotola","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Forma il polpettone","content":"Forma un rotolo compatto e uniforme e mettilo su una teglia.","image_alt":"Mani che formano e compattano il polpettone crudo sulla teglia","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Inforna","content":"Inforna per circa 50 minuti come indicazione, finché il centro raggiunge 71 gradi Celsius. Controlla con un termometro.","image_alt":"Polpettone cotto con un termometro da cucina inserito","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prepara la salsa","content":"Mentre cuoce, soffriggi la cipolla e l'aglio della salsa; aggiungi il pomodoro schiacciato, la salsa di pomodoro, lo zucchero, il cumino e la paprika, e cuoci finché si addensa.","image_alt":"Salsa di pomodoro fatta in casa che cuoce in padella","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Lascia riposare","content":"Togli il polpettone dal forno e lascialo riposare circa 10 minuti prima di tagliarlo."},{"title":"Taglia e servi","content":"Taglia a fette e servi con la salsa di pomodoro.","image_alt":"Polpettone tagliato a fette con salsa di pomodoro e una salsiera accanto","image_url":"/recetas/rollo-de-carne/paso-07.webp"}],"new_steps":[{"title":"Preriscalda il forno","content":"Preriscalda il forno a 180 gradi Celsius.","image_url":"/recetas/rollo-de-carne/paso-completo-01-20261103.webp","image_alt":"Preriscalda il forno"},{"title":"Mescola la carne","content":"Mescola la carne con la cipolla, l'aglio, le carote cotte, il pangrattato, il latte, il cumino, il sale e il pepe.","image_alt":"Mani che mescolano la carne macinata con carota, pangrattato e spezie in una ciotola","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Forma il polpettone","content":"Forma un rotolo compatto e uniforme e mettilo su una teglia.","image_alt":"Mani che formano e compattano il polpettone crudo sulla teglia","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Inforna","content":"Inforna per circa 50 minuti come indicazione, finché il centro raggiunge 71 gradi Celsius. Controlla con un termometro.","image_alt":"Polpettone cotto con un termometro da cucina inserito","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prepara la salsa","content":"Mentre cuoce, soffriggi la cipolla e l'aglio della salsa; aggiungi il pomodoro schiacciato, la salsa di pomodoro, lo zucchero, il cumino e la paprika, e cuoci finché si addensa.","image_alt":"Salsa di pomodoro fatta in casa che cuoce in padella","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Lascia riposare","content":"Togli il polpettone dal forno e lascialo riposare circa 10 minuti prima di tagliarlo.","image_url":"/recetas/rollo-de-carne/paso-completo-06-20261103.webp","image_alt":"Lascia riposare"},{"title":"Taglia e servi","content":"Taglia a fette e servi con la salsa di pomodoro.","image_alt":"Polpettone tagliato a fette con salsa di pomodoro e una salsiera accanto","image_url":"/recetas/rollo-de-carne/paso-07.webp"}]},{"id":"fd6b782c-a1a2-41e1-bd22-588799c3c08f","expected_steps":[{"title":"オーブンを予熱する","content":"オーブンを180度に予熱する。"},{"title":"肉を混ぜる","content":"ひき肉に玉ねぎ、にんにく、茹でたにんじん、パン粉、牛乳、クミン、塩、こしょうを加えて混ぜる。","image_alt":"ボウルの中でひき肉ににんじん、パン粉、スパイスを混ぜ合わせる手元","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"成形する","content":"しっかりまとまった均一な塊に成形し、天板にのせる。","image_alt":"生のミートローフを天板の上で成形して固める手元","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"焼く","content":"目安として約50分焼き、中心が71度に達するまで焼く。温度計で確認する。","image_alt":"キッチン温度計を挿した焼き上がったミートローフ","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"ソースを作る","content":"焼いている間に、ソース用の玉ねぎとにんにくを炒める。カットトマト、トマトソース、砂糖、クミン、パプリカを加え、とろみがつくまで煮る。","image_alt":"フライパンで煮込む自家製トマトソース","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"休ませる","content":"オーブンから取り出し、切る前に約10分休ませる。"},{"title":"切って盛り付ける","content":"スライスしてトマトソースと一緒に盛り付ける。","image_alt":"スライスしたミートローフとトマトソース、添えられたソース入れ","image_url":"/recetas/rollo-de-carne/paso-07.webp"}],"new_steps":[{"title":"オーブンを予熱する","content":"オーブンを180度に予熱する。","image_url":"/recetas/rollo-de-carne/paso-completo-01-20261103.webp","image_alt":"オーブンを予熱する"},{"title":"肉を混ぜる","content":"ひき肉に玉ねぎ、にんにく、茹でたにんじん、パン粉、牛乳、クミン、塩、こしょうを加えて混ぜる。","image_alt":"ボウルの中でひき肉ににんじん、パン粉、スパイスを混ぜ合わせる手元","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"成形する","content":"しっかりまとまった均一な塊に成形し、天板にのせる。","image_alt":"生のミートローフを天板の上で成形して固める手元","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"焼く","content":"目安として約50分焼き、中心が71度に達するまで焼く。温度計で確認する。","image_alt":"キッチン温度計を挿した焼き上がったミートローフ","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"ソースを作る","content":"焼いている間に、ソース用の玉ねぎとにんにくを炒める。カットトマト、トマトソース、砂糖、クミン、パプリカを加え、とろみがつくまで煮る。","image_alt":"フライパンで煮込む自家製トマトソース","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"休ませる","content":"オーブンから取り出し、切る前に約10分休ませる。","image_url":"/recetas/rollo-de-carne/paso-completo-06-20261103.webp","image_alt":"休ませる"},{"title":"切って盛り付ける","content":"スライスしてトマトソースと一緒に盛り付ける。","image_alt":"スライスしたミートローフとトマトソース、添えられたソース入れ","image_url":"/recetas/rollo-de-carne/paso-07.webp"}]},{"id":"b242cf7e-7d0a-492a-871e-d5eec4e82108","expected_steps":[{"title":"Preaqueça o forno","content":"Preaqueça o forno a 180 graus Celsius."},{"title":"Misture a carne","content":"Misture a carne com a cebola, o alho, as cenouras cozidas, a farinha de rosca, o leite, o cominho, o sal e a pimenta.","image_alt":"Mãos misturando a carne moída com cenoura, farinha de rosca e especiarias numa tigela","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Molde o bolo","content":"Molde um rolo compacto e uniforme e coloque-o numa assadeira.","image_alt":"Mãos moldando e compactando o bolo de carne cru na assadeira","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Asse","content":"Asse por cerca de 50 minutos como orientação, até o centro atingir 71 graus Celsius. Verifique com um termômetro.","image_alt":"Bolo de carne assado com um termômetro de cozinha inserido","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prepare o molho","content":"Enquanto assa, refogue a cebola e o alho do molho; junte o tomate triturado, o molho de tomate, o açúcar, o cominho e o pimentão, e cozinhe até engrossar.","image_alt":"Molho de tomate caseiro cozinhando numa frigideira","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Deixe descansar","content":"Retire o bolo do forno e deixe-o descansar por cerca de 10 minutos antes de cortar."},{"title":"Corte e sirva","content":"Corte em fatias e sirva com o molho de tomate.","image_alt":"Bolo de carne cortado em fatias com molho de tomate e uma molheira ao lado","image_url":"/recetas/rollo-de-carne/paso-07.webp"}],"new_steps":[{"title":"Preaqueça o forno","content":"Preaqueça o forno a 180 graus Celsius.","image_url":"/recetas/rollo-de-carne/paso-completo-01-20261103.webp","image_alt":"Preaqueça o forno"},{"title":"Misture a carne","content":"Misture a carne com a cebola, o alho, as cenouras cozidas, a farinha de rosca, o leite, o cominho, o sal e a pimenta.","image_alt":"Mãos misturando a carne moída com cenoura, farinha de rosca e especiarias numa tigela","image_url":"/recetas/rollo-de-carne/paso-02.webp"},{"title":"Molde o bolo","content":"Molde um rolo compacto e uniforme e coloque-o numa assadeira.","image_alt":"Mãos moldando e compactando o bolo de carne cru na assadeira","image_url":"/recetas/rollo-de-carne/paso-03.webp"},{"title":"Asse","content":"Asse por cerca de 50 minutos como orientação, até o centro atingir 71 graus Celsius. Verifique com um termômetro.","image_alt":"Bolo de carne assado com um termômetro de cozinha inserido","image_url":"/recetas/rollo-de-carne/paso-04.webp"},{"title":"Prepare o molho","content":"Enquanto assa, refogue a cebola e o alho do molho; junte o tomate triturado, o molho de tomate, o açúcar, o cominho e o pimentão, e cozinhe até engrossar.","image_alt":"Molho de tomate caseiro cozinhando numa frigideira","image_url":"/recetas/rollo-de-carne/paso-05.webp"},{"title":"Deixe descansar","content":"Retire o bolo do forno e deixe-o descansar por cerca de 10 minutos antes de cortar.","image_url":"/recetas/rollo-de-carne/paso-completo-06-20261103.webp","image_alt":"Deixe descansar"},{"title":"Corte e sirva","content":"Corte em fatias e sirva com o molho de tomate.","image_alt":"Bolo de carne cortado em fatias com molho de tomate e uma molheira ao lado","image_url":"/recetas/rollo-de-carne/paso-07.webp"}]},{"id":"e2581453-10ed-4668-bdfc-0b546e15a7d0","expected_steps":[{"title":"Die Banane schälen","content":"Die Banane schälen und in Stücke schneiden."},{"title":"Den Apfel schneiden","content":"Den Apfel in Stücke schneiden, dabei Kerngehäuse und Kerne entfernen.","image_alt":"Geschnittene Banane und gewürfelter grüner Apfel auf einem Holzbrett","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Die Zutaten in den Mixer geben","content":"Banane, Apfel, Spinat, Erdbeeren, Gurke, griechischen Joghurt, Mandelmilch und Chiasamen in einen Mixer geben.","image_alt":"Banane, Apfel, Spinat, Erdbeeren und Gurke im Mixbecher, Milch wird eingegossen","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Glatt mixen","content":"Alle Zutaten mixen, bis eine glatte, cremige Konsistenz entsteht. Für eine kühlere Textur vor dem Mixen ein paar Eiswürfel hinzufügen.","image_alt":"Frisch gemixter Obst-Gemüse-Smoothie im Mixbecher","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Servieren","content":"Den Smoothie in einem großen Glas servieren und dieses gesunde, erfrischende Frühstück genießen.","image_alt":"Obst-Gemüse-Smoothie wird in ein hohes Glas gegossen","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}],"new_steps":[{"title":"Die Banane schälen","content":"Die Banane schälen und in Stücke schneiden.","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-completo-01-20261103.webp","image_alt":"Die Banane schälen"},{"title":"Den Apfel schneiden","content":"Den Apfel in Stücke schneiden, dabei Kerngehäuse und Kerne entfernen.","image_alt":"Geschnittene Banane und gewürfelter grüner Apfel auf einem Holzbrett","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Die Zutaten in den Mixer geben","content":"Banane, Apfel, Spinat, Erdbeeren, Gurke, griechischen Joghurt, Mandelmilch und Chiasamen in einen Mixer geben.","image_alt":"Banane, Apfel, Spinat, Erdbeeren und Gurke im Mixbecher, Milch wird eingegossen","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Glatt mixen","content":"Alle Zutaten mixen, bis eine glatte, cremige Konsistenz entsteht. Für eine kühlere Textur vor dem Mixen ein paar Eiswürfel hinzufügen.","image_alt":"Frisch gemixter Obst-Gemüse-Smoothie im Mixbecher","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Servieren","content":"Den Smoothie in einem großen Glas servieren und dieses gesunde, erfrischende Frühstück genießen.","image_alt":"Obst-Gemüse-Smoothie wird in ein hohes Glas gegossen","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}]},{"id":"81c84f3b-edec-48bc-9ff4-a73bfca2688c","expected_steps":[{"title":"Peel the banana","content":"Peel the banana and cut it into pieces."},{"title":"Cut the apple","content":"Cut the apple into pieces, making sure to remove the core and seeds.","image_alt":"Sliced banana and chopped green apple on a wooden cutting board","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Add the ingredients to the blender","content":"In a blender, combine the banana, apple, spinach, strawberries, cucumber, Greek yogurt, almond milk and chia seeds.","image_alt":"Banana, apple, spinach, strawberries and cucumber in the blender jar with milk being poured in","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Blend until smooth","content":"Blend all the ingredients until smooth and creamy. For a colder texture, add a few ice cubes before blending.","image_alt":"Freshly blended fruit and vegetable smoothie in the blender jar","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Serve","content":"Serve the smoothie in a large glass and enjoy this healthy, refreshing breakfast.","image_alt":"Fruit and vegetable smoothie being poured into a tall glass","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}],"new_steps":[{"title":"Peel the banana","content":"Peel the banana and cut it into pieces.","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-completo-01-20261103.webp","image_alt":"Peel the banana"},{"title":"Cut the apple","content":"Cut the apple into pieces, making sure to remove the core and seeds.","image_alt":"Sliced banana and chopped green apple on a wooden cutting board","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Add the ingredients to the blender","content":"In a blender, combine the banana, apple, spinach, strawberries, cucumber, Greek yogurt, almond milk and chia seeds.","image_alt":"Banana, apple, spinach, strawberries and cucumber in the blender jar with milk being poured in","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Blend until smooth","content":"Blend all the ingredients until smooth and creamy. For a colder texture, add a few ice cubes before blending.","image_alt":"Freshly blended fruit and vegetable smoothie in the blender jar","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Serve","content":"Serve the smoothie in a large glass and enjoy this healthy, refreshing breakfast.","image_alt":"Fruit and vegetable smoothie being poured into a tall glass","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}]},{"id":"57a9b600-9e13-49c8-b99a-103a91a4ec37","expected_steps":[{"title":"Pela el plátano","content":"Pelar el plátano y cortarlo en trozos."},{"title":"Corta la manzana","content":"Cortar la manzana en trozos, asegurándote de quitar el corazón y las semillas.","image_alt":"Plátano y manzana verde cortados en trozos sobre una tabla de madera","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Añade los ingredientes a la licuadora","content":"En una licuadora, combina el plátano, la manzana, las espinacas, las fresas, el pepino, el yogur griego, la leche de almendras y las semillas de chía.","image_alt":"Plátano, manzana, espinacas, fresas y pepino en el vaso de la licuadora con leche siendo añadida","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Licúa hasta que quede suave","content":"Licúa durante 1-2 minutos, hasta obtener una consistencia suave y homogénea. Si prefieres una textura más fría, añade unos cubitos de hielo antes de mezclar.","image_alt":"Batido de frutas y vegetales recién licuado en el vaso de la licuadora","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Sirve","content":"Sirve el batido en un vaso grande y disfruta de este desayuno saludable y refrescante.","image_alt":"Batido de frutas y vegetales sirviéndose en un vaso alto","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}],"new_steps":[{"title":"Pela el plátano","content":"Pelar el plátano y cortarlo en trozos.","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-completo-01-20261103.webp","image_alt":"Pela el plátano"},{"title":"Corta la manzana","content":"Cortar la manzana en trozos, asegurándote de quitar el corazón y las semillas.","image_alt":"Plátano y manzana verde cortados en trozos sobre una tabla de madera","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Añade los ingredientes a la licuadora","content":"En una licuadora, combina el plátano, la manzana, las espinacas, las fresas, el pepino, el yogur griego, la leche de almendras y las semillas de chía.","image_alt":"Plátano, manzana, espinacas, fresas y pepino en el vaso de la licuadora con leche siendo añadida","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Licúa hasta que quede suave","content":"Licúa durante 1-2 minutos, hasta obtener una consistencia suave y homogénea. Si prefieres una textura más fría, añade unos cubitos de hielo antes de mezclar.","image_alt":"Batido de frutas y vegetales recién licuado en el vaso de la licuadora","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Sirve","content":"Sirve el batido en un vaso grande y disfruta de este desayuno saludable y refrescante.","image_alt":"Batido de frutas y vegetales sirviéndose en un vaso alto","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}]},{"id":"9e7afc25-5fd5-4adf-8f51-edd8a00ef82d","expected_steps":[{"title":"Éplucher la banane","content":"Éplucher la banane et la couper en morceaux."},{"title":"Couper la pomme","content":"Couper la pomme en morceaux, en retirant bien le trognon et les pépins.","image_alt":"Banane tranchée et pomme verte coupée sur une planche en bois","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Ajouter les ingrédients au blender","content":"Dans un blender, mélanger la banane, la pomme, les épinards, les fraises, le concombre, le yaourt grec, le lait d'amande et les graines de chia.","image_alt":"Banane, pomme, épinards, fraises et concombre dans le blender avec du lait versé dessus","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Mixer jusqu'à consistance lisse","content":"Mixer tous les ingrédients jusqu'à obtenir une texture lisse et onctueuse. Pour une texture plus fraîche, ajouter quelques glaçons avant de mixer.","image_alt":"Smoothie aux fruits et légumes fraîchement mixé dans le blender","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Servir","content":"Servir le smoothie dans un grand verre et profiter de ce petit-déjeuner sain et rafraîchissant.","image_alt":"Smoothie aux fruits et légumes versé dans un grand verre","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}],"new_steps":[{"title":"Éplucher la banane","content":"Éplucher la banane et la couper en morceaux.","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-completo-01-20261103.webp","image_alt":"Éplucher la banane"},{"title":"Couper la pomme","content":"Couper la pomme en morceaux, en retirant bien le trognon et les pépins.","image_alt":"Banane tranchée et pomme verte coupée sur une planche en bois","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Ajouter les ingrédients au blender","content":"Dans un blender, mélanger la banane, la pomme, les épinards, les fraises, le concombre, le yaourt grec, le lait d'amande et les graines de chia.","image_alt":"Banane, pomme, épinards, fraises et concombre dans le blender avec du lait versé dessus","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Mixer jusqu'à consistance lisse","content":"Mixer tous les ingrédients jusqu'à obtenir une texture lisse et onctueuse. Pour une texture plus fraîche, ajouter quelques glaçons avant de mixer.","image_alt":"Smoothie aux fruits et légumes fraîchement mixé dans le blender","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Servir","content":"Servir le smoothie dans un grand verre et profiter de ce petit-déjeuner sain et rafraîchissant.","image_alt":"Smoothie aux fruits et légumes versé dans un grand verre","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}]},{"id":"3bdb43f9-ed94-4dee-93a7-6cb251893ab4","expected_steps":[{"title":"Sbuccia la banana","content":"Sbuccia la banana e tagliala a pezzi."},{"title":"Taglia la mela","content":"Taglia la mela a pezzi, avendo cura di eliminare il torsolo e i semi.","image_alt":"Banana affettata e mela verde tagliata su un tagliere di legno","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Aggiungi gli ingredienti al frullatore","content":"In un frullatore, unisci banana, mela, spinaci, fragole, cetriolo, yogurt greco, latte di mandorla e semi di chia.","image_alt":"Banana, mela, spinaci, fragole e cetriolo nel bicchiere del frullatore con latte versato sopra","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Frulla fino a ottenere un composto liscio","content":"Frulla tutti gli ingredienti fino a ottenere un composto liscio e cremoso. Per una consistenza più fredda, aggiungi qualche cubetto di ghiaccio prima di frullare.","image_alt":"Frullato di frutta e verdura appena frullato nel bicchiere del frullatore","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Servi","content":"Servi il frullato in un bicchiere grande e goditi questa colazione sana e rinfrescante.","image_alt":"Frullato di frutta e verdura versato in un bicchiere alto","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}],"new_steps":[{"title":"Sbuccia la banana","content":"Sbuccia la banana e tagliala a pezzi.","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-completo-01-20261103.webp","image_alt":"Sbuccia la banana"},{"title":"Taglia la mela","content":"Taglia la mela a pezzi, avendo cura di eliminare il torsolo e i semi.","image_alt":"Banana affettata e mela verde tagliata su un tagliere di legno","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Aggiungi gli ingredienti al frullatore","content":"In un frullatore, unisci banana, mela, spinaci, fragole, cetriolo, yogurt greco, latte di mandorla e semi di chia.","image_alt":"Banana, mela, spinaci, fragole e cetriolo nel bicchiere del frullatore con latte versato sopra","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Frulla fino a ottenere un composto liscio","content":"Frulla tutti gli ingredienti fino a ottenere un composto liscio e cremoso. Per una consistenza più fredda, aggiungi qualche cubetto di ghiaccio prima di frullare.","image_alt":"Frullato di frutta e verdura appena frullato nel bicchiere del frullatore","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Servi","content":"Servi il frullato in un bicchiere grande e goditi questa colazione sana e rinfrescante.","image_alt":"Frullato di frutta e verdura versato in un bicchiere alto","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}]},{"id":"1848f499-9479-4a15-b125-cc49f212a303","expected_steps":[{"title":"バナナの皮をむく","content":"バナナの皮をむいて一口大に切ります。"},{"title":"りんごを切る","content":"りんごの芯と種を取り除き、一口大に切ります。","image_alt":"木のまな板の上に並んだバナナの輪切りと角切りの青りんご","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"材料をミキサーに入れる","content":"ミキサーにバナナ、りんご、ほうれん草、いちご、きゅうり、ギリシャヨーグルト、アーモンドミルク、チアシードを入れます。","image_alt":"バナナ、りんご、ほうれん草、いちご、きゅうりが入ったミキサーにミルクを注いでいるところ","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"なめらかになるまで混ぜる","content":"なめらかでクリーミーになるまで撹拌します。冷たい口当たりにしたい場合は氷を加えてから撹拌します。","image_alt":"ミキサーで撹拌したばかりのフルーツ野菜スムージー","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"提供する","content":"大きめのグラスに注いで、健康的で爽やかな朝食として楽しみます。","image_alt":"背の高いグラスに注がれているフルーツ野菜スムージー","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}],"new_steps":[{"title":"バナナの皮をむく","content":"バナナの皮をむいて一口大に切ります。","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-completo-01-20261103.webp","image_alt":"バナナの皮をむく"},{"title":"りんごを切る","content":"りんごの芯と種を取り除き、一口大に切ります。","image_alt":"木のまな板の上に並んだバナナの輪切りと角切りの青りんご","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"材料をミキサーに入れる","content":"ミキサーにバナナ、りんご、ほうれん草、いちご、きゅうり、ギリシャヨーグルト、アーモンドミルク、チアシードを入れます。","image_alt":"バナナ、りんご、ほうれん草、いちご、きゅうりが入ったミキサーにミルクを注いでいるところ","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"なめらかになるまで混ぜる","content":"なめらかでクリーミーになるまで撹拌します。冷たい口当たりにしたい場合は氷を加えてから撹拌します。","image_alt":"ミキサーで撹拌したばかりのフルーツ野菜スムージー","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"提供する","content":"大きめのグラスに注いで、健康的で爽やかな朝食として楽しみます。","image_alt":"背の高いグラスに注がれているフルーツ野菜スムージー","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}]},{"id":"fd387fa1-d3d5-4f88-8e8e-9844e6114992","expected_steps":[{"title":"Descasque a banana","content":"Descasque a banana e corte-a em pedaços."},{"title":"Corte a maçã","content":"Corte a maçã em pedaços, removendo o miolo e as sementes.","image_alt":"Banana fatiada e maçã verde picada em uma tábua de madeira","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Adicione os ingredientes ao liquidificador","content":"No liquidificador, combine a banana, a maçã, o espinafre, os morangos, o pepino, o iogurte grego, o leite de amêndoas e as sementes de chia.","image_alt":"Banana, maçã, espinafre, morangos e pepino no copo do liquidificador com leite sendo despejado","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Bata até ficar homogêneo","content":"Bata todos os ingredientes até obter uma consistência lisa e cremosa. Para uma textura mais gelada, adicione alguns cubos de gelo antes de bater.","image_alt":"Batida de frutas e vegetais recém-batida no copo do liquidificador","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Sirva","content":"Sirva a batida em um copo grande e aproveite este café da manhã saudável e refrescante.","image_alt":"Batida de frutas e vegetais sendo servida em um copo alto","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}],"new_steps":[{"title":"Descasque a banana","content":"Descasque a banana e corte-a em pedaços.","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-completo-01-20261103.webp","image_alt":"Descasque a banana"},{"title":"Corte a maçã","content":"Corte a maçã em pedaços, removendo o miolo e as sementes.","image_alt":"Banana fatiada e maçã verde picada em uma tábua de madeira","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-02.webp"},{"title":"Adicione os ingredientes ao liquidificador","content":"No liquidificador, combine a banana, a maçã, o espinafre, os morangos, o pepino, o iogurte grego, o leite de amêndoas e as sementes de chia.","image_alt":"Banana, maçã, espinafre, morangos e pepino no copo do liquidificador com leite sendo despejado","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-03.webp"},{"title":"Bata até ficar homogêneo","content":"Bata todos os ingredientes até obter uma consistência lisa e cremosa. Para uma textura mais gelada, adicione alguns cubos de gelo antes de bater.","image_alt":"Batida de frutas e vegetais recém-batida no copo do liquidificador","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-04.webp"},{"title":"Sirva","content":"Sirva a batida em um copo grande e aproveite este café da manhã saudável e refrescante.","image_alt":"Batida de frutas e vegetais sendo servida em um copo alto","image_url":"/recetas/batido-energizante-frutas-vegetales/paso-05.webp"}]},{"id":"900a29cc-a46f-4dc4-bd44-6515cbab06f4","expected_steps":[{"title":"Trockene Zutaten mischen","content":"Mehl, Zucker und Salz vermischen."},{"title":"Teig zubereiten","content":"Die Eier verquirlen, Milch und geschmolzene Butter hinzufügen und mit den trockenen Zutaten zu einem klumpenfreien Teig verrühren. Den Teig abdecken und vor dem Ausbacken 30 Minuten ruhen lassen; diese Ruhezeit ist in den insgesamt 90 Minuten enthalten.","image_alt":"Flüssiger Crêpe-Teig in einer Glasschüssel verquirlt","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Crêpes backen","content":"Dünne Crêpes 1 bis 2 Minuten pro Seite in einer leicht gefetteten Pfanne backen und beiseitestellen.","image_alt":"Dünner Crêpe bräunt in einer Pfanne","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Zwiebel und Knoblauch anbraten","content":"Die Butter für die Füllung schmelzen und Zwiebel und Knoblauch anbraten."},{"title":"Rindfleisch anbraten","content":"Das Rindfleisch dazugeben und 3 bis 4 Minuten anbraten; die Champignons hinzufügen und garen, bis sie weich sind.","image_alt":"Rinderstreifen und Champignons bräunen in der Pfanne","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Mehl hinzufügen","content":"Das Mehl darüberstreuen und eine Minute lang verrühren, damit es sich klumpenfrei einbindet."},{"title":"Sauce zubereiten","content":"Die Brühe nach und nach unter Rühren hinzufügen und kochen, bis die Sauce eindickt.","image_alt":"Cremige Champignon-Rindfleisch-Sauce fertig in der Pfanne","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Sahne hinzufügen","content":"Die Sahne unterrühren und einige Minuten bei sanfter Hitze köcheln lassen, ohne stark aufzukochen.","image_alt":"Sahne wird in einem dünnen Strahl über die Rindfleisch-Champignon-Sauce gegossen","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Füllen und servieren","content":"Mit Salz und Pfeffer abschmecken, die Crêpes füllen oder bedecken und mit Petersilie abschließen."}],"new_steps":[{"title":"Trockene Zutaten mischen","content":"Mehl, Zucker und Salz vermischen.","image_url":"/recetas/creep-stroganoff/paso-completo-01-20261103.webp","image_alt":"Trockene Zutaten mischen"},{"title":"Teig zubereiten","content":"Die Eier verquirlen, Milch und geschmolzene Butter hinzufügen und mit den trockenen Zutaten zu einem klumpenfreien Teig verrühren. Den Teig abdecken und vor dem Ausbacken 30 Minuten ruhen lassen; diese Ruhezeit ist in den insgesamt 90 Minuten enthalten.","image_alt":"Flüssiger Crêpe-Teig in einer Glasschüssel verquirlt","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Crêpes backen","content":"Dünne Crêpes 1 bis 2 Minuten pro Seite in einer leicht gefetteten Pfanne backen und beiseitestellen.","image_alt":"Dünner Crêpe bräunt in einer Pfanne","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Zwiebel und Knoblauch anbraten","content":"Die Butter für die Füllung schmelzen und Zwiebel und Knoblauch anbraten.","image_url":"/recetas/creep-stroganoff/paso-completo-04-20261103.webp","image_alt":"Zwiebel und Knoblauch anbraten"},{"title":"Rindfleisch anbraten","content":"Das Rindfleisch dazugeben und 3 bis 4 Minuten anbraten; die Champignons hinzufügen und garen, bis sie weich sind.","image_alt":"Rinderstreifen und Champignons bräunen in der Pfanne","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Mehl hinzufügen","content":"Das Mehl darüberstreuen und eine Minute lang verrühren, damit es sich klumpenfrei einbindet.","image_url":"/recetas/creep-stroganoff/paso-completo-06-20261103.webp","image_alt":"Mehl hinzufügen"},{"title":"Sauce zubereiten","content":"Die Brühe nach und nach unter Rühren hinzufügen und kochen, bis die Sauce eindickt.","image_alt":"Cremige Champignon-Rindfleisch-Sauce fertig in der Pfanne","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Sahne hinzufügen","content":"Die Sahne unterrühren und einige Minuten bei sanfter Hitze köcheln lassen, ohne stark aufzukochen.","image_alt":"Sahne wird in einem dünnen Strahl über die Rindfleisch-Champignon-Sauce gegossen","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Füllen und servieren","content":"Mit Salz und Pfeffer abschmecken, die Crêpes füllen oder bedecken und mit Petersilie abschließen.","image_url":"/recetas/creep-stroganoff/paso-completo-09-20261103.webp","image_alt":"Füllen und servieren"}]},{"id":"9708424f-7580-4e3f-930a-3e16cbfec6ba","expected_steps":[{"title":"Mix the dry ingredients","content":"Mix the flour, sugar and salt."},{"title":"Make the batter","content":"Beat the eggs, add the milk and melted butter, and combine with the dry ingredients until you have a lump-free batter. Cover the batter and let it rest for 30 minutes before cooking the crepes; this rest is included in the 90-minute total.","image_alt":"Crepe batter whisked in a glass bowl","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cook the crepes","content":"Cook thin crepes, 1 to 2 minutes per side, in a lightly greased pan, and set them aside.","image_alt":"Thin crepe browning in a pan","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Saute the onion and garlic","content":"Melt the butter for the filling and saute the onion and garlic."},{"title":"Brown the beef","content":"Add the beef and brown it for 3 to 4 minutes; add the mushrooms and cook until tender.","image_alt":"Beef strips and mushrooms browning in the pan","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Add the flour","content":"Sprinkle in the flour and stir for a minute so it blends in without lumps."},{"title":"Make the sauce","content":"Add the broth little by little, stirring, and cook until the sauce thickens.","image_alt":"Creamy mushroom and beef sauce ready in the pan","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Add the cream","content":"Stir in the cream and cook a few minutes over low heat, without letting it boil hard.","image_alt":"Cream being poured in a thin stream over the beef and mushroom sauce","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Fill and serve","content":"Season with salt and pepper, fill or top the crepes, and finish with parsley."}],"new_steps":[{"title":"Mix the dry ingredients","content":"Mix the flour, sugar and salt.","image_url":"/recetas/creep-stroganoff/paso-completo-01-20261103.webp","image_alt":"Mix the dry ingredients"},{"title":"Make the batter","content":"Beat the eggs, add the milk and melted butter, and combine with the dry ingredients until you have a lump-free batter. Cover the batter and let it rest for 30 minutes before cooking the crepes; this rest is included in the 90-minute total.","image_alt":"Crepe batter whisked in a glass bowl","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cook the crepes","content":"Cook thin crepes, 1 to 2 minutes per side, in a lightly greased pan, and set them aside.","image_alt":"Thin crepe browning in a pan","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Saute the onion and garlic","content":"Melt the butter for the filling and saute the onion and garlic.","image_url":"/recetas/creep-stroganoff/paso-completo-04-20261103.webp","image_alt":"Saute the onion and garlic"},{"title":"Brown the beef","content":"Add the beef and brown it for 3 to 4 minutes; add the mushrooms and cook until tender.","image_alt":"Beef strips and mushrooms browning in the pan","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Add the flour","content":"Sprinkle in the flour and stir for a minute so it blends in without lumps.","image_url":"/recetas/creep-stroganoff/paso-completo-06-20261103.webp","image_alt":"Add the flour"},{"title":"Make the sauce","content":"Add the broth little by little, stirring, and cook until the sauce thickens.","image_alt":"Creamy mushroom and beef sauce ready in the pan","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Add the cream","content":"Stir in the cream and cook a few minutes over low heat, without letting it boil hard.","image_alt":"Cream being poured in a thin stream over the beef and mushroom sauce","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Fill and serve","content":"Season with salt and pepper, fill or top the crepes, and finish with parsley.","image_url":"/recetas/creep-stroganoff/paso-completo-09-20261103.webp","image_alt":"Fill and serve"}]},{"id":"8358b894-382b-4032-a693-2b57df99bb3f","expected_steps":[{"title":"Mezcla los ingredientes secos","content":"Mezcla la harina, el azúcar y la sal."},{"title":"Prepara la masa","content":"Bate los huevos, añade la leche y la mantequilla derretida, e intégralos con los ingredientes secos hasta obtener una masa sin grumos. Tapa la masa y déjala reposar 30 minutos antes de cocinar los crepes; este reposo está incluido en los 90 minutos totales.","image_alt":"Masa líquida para crepes batida en un bol de cristal","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cocina los crepes","content":"Cocina crepes finos, de 1 a 2 minutos por lado, en una sartén ligeramente engrasada y resérvalos.","image_alt":"Crepe fino dorándose en una sartén","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Sofríe cebolla y ajo","content":"Derrite la mantequilla del relleno y sofríe la cebolla y el ajo."},{"title":"Dora la ternera","content":"Añade la ternera y dórala de 3 a 4 minutos; incorpora los champiñones y cocina hasta que estén tiernos.","image_alt":"Tiras de ternera y champiñones dorándose en la sartén","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Añade la harina","content":"Espolvorea la harina y mezcla durante un minuto para que se integre sin grumos."},{"title":"Prepara la salsa","content":"Añade el caldo poco a poco, removiendo, y cocina hasta que la salsa espese.","image_alt":"Salsa cremosa de champiñones y ternera lista en la sartén","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Agrega la nata","content":"Incorpora la nata y cocina unos minutos a fuego suave, sin que hierva con fuerza.","image_alt":"Nata cayendo en hilo sobre la salsa de ternera y champiñones","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Rellena y sirve","content":"Sazona con sal y pimienta, rellena o cubre los crepes y termina con perejil."}],"new_steps":[{"title":"Mezcla los ingredientes secos","content":"Mezcla la harina, el azúcar y la sal.","image_url":"/recetas/creep-stroganoff/paso-completo-01-20261103.webp","image_alt":"Mezcla los ingredientes secos"},{"title":"Prepara la masa","content":"Bate los huevos, añade la leche y la mantequilla derretida, e intégralos con los ingredientes secos hasta obtener una masa sin grumos. Tapa la masa y déjala reposar 30 minutos antes de cocinar los crepes; este reposo está incluido en los 90 minutos totales.","image_alt":"Masa líquida para crepes batida en un bol de cristal","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cocina los crepes","content":"Cocina crepes finos, de 1 a 2 minutos por lado, en una sartén ligeramente engrasada y resérvalos.","image_alt":"Crepe fino dorándose en una sartén","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Sofríe cebolla y ajo","content":"Derrite la mantequilla del relleno y sofríe la cebolla y el ajo.","image_url":"/recetas/creep-stroganoff/paso-completo-04-20261103.webp","image_alt":"Sofríe cebolla y ajo"},{"title":"Dora la ternera","content":"Añade la ternera y dórala de 3 a 4 minutos; incorpora los champiñones y cocina hasta que estén tiernos.","image_alt":"Tiras de ternera y champiñones dorándose en la sartén","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Añade la harina","content":"Espolvorea la harina y mezcla durante un minuto para que se integre sin grumos.","image_url":"/recetas/creep-stroganoff/paso-completo-06-20261103.webp","image_alt":"Añade la harina"},{"title":"Prepara la salsa","content":"Añade el caldo poco a poco, removiendo, y cocina hasta que la salsa espese.","image_alt":"Salsa cremosa de champiñones y ternera lista en la sartén","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Agrega la nata","content":"Incorpora la nata y cocina unos minutos a fuego suave, sin que hierva con fuerza.","image_alt":"Nata cayendo en hilo sobre la salsa de ternera y champiñones","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Rellena y sirve","content":"Sazona con sal y pimienta, rellena o cubre los crepes y termina con perejil.","image_url":"/recetas/creep-stroganoff/paso-completo-09-20261103.webp","image_alt":"Rellena y sirve"}]},{"id":"9dbfe294-f3eb-4c6c-a450-a1a4aee60013","expected_steps":[{"title":"Mélange les ingrédients secs","content":"Mélange la farine, le sucre et le sel."},{"title":"Prépare la pâte","content":"Bats les œufs, ajoute le lait et le beurre fondu, puis incorpore aux ingrédients secs jusqu'à obtenir une pâte sans grumeaux. Couvrez la pâte et laissez-la reposer 30 minutes avant de cuire les crêpes ; ce repos est inclus dans les 90 minutes au total.","image_alt":"Pâte à crêpes liquide fouettée dans un bol en verre","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cuis les crêpes","content":"Cuis des crêpes fines, 1 à 2 minutes de chaque côté, dans une poêle légèrement graissée, et réserve-les.","image_alt":"Crêpe fine qui dore dans une poêle","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Fais revenir l'oignon et l'ail","content":"Fais fondre le beurre de la garniture et fais revenir l'oignon et l'ail."},{"title":"Fais dorer le bœuf","content":"Ajoute le bœuf et fais-le dorer 3 à 4 minutes ; ajoute les champignons et cuis jusqu'à ce qu'ils soient tendres.","image_alt":"Lanières de bœuf et champignons qui dorent dans la poêle","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Ajoute la farine","content":"Saupoudre la farine et mélange pendant une minute pour qu'elle s'incorpore sans grumeaux."},{"title":"Prépare la sauce","content":"Ajoute le bouillon petit à petit en remuant, et cuis jusqu'à ce que la sauce épaississe.","image_alt":"Sauce crémeuse aux champignons et au bœuf prête dans la poêle","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Ajoute la crème","content":"Incorpore la crème et laisse cuire quelques minutes à feu doux, sans laisser bouillir fort.","image_alt":"Crème versée en filet sur la sauce au bœuf et aux champignons","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Garnis et sers","content":"Assaisonne de sel et de poivre, garnis ou recouvre les crêpes et termine avec du persil."}],"new_steps":[{"title":"Mélange les ingrédients secs","content":"Mélange la farine, le sucre et le sel.","image_url":"/recetas/creep-stroganoff/paso-completo-01-20261103.webp","image_alt":"Mélange les ingrédients secs"},{"title":"Prépare la pâte","content":"Bats les œufs, ajoute le lait et le beurre fondu, puis incorpore aux ingrédients secs jusqu'à obtenir une pâte sans grumeaux. Couvrez la pâte et laissez-la reposer 30 minutes avant de cuire les crêpes ; ce repos est inclus dans les 90 minutes au total.","image_alt":"Pâte à crêpes liquide fouettée dans un bol en verre","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cuis les crêpes","content":"Cuis des crêpes fines, 1 à 2 minutes de chaque côté, dans une poêle légèrement graissée, et réserve-les.","image_alt":"Crêpe fine qui dore dans une poêle","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Fais revenir l'oignon et l'ail","content":"Fais fondre le beurre de la garniture et fais revenir l'oignon et l'ail.","image_url":"/recetas/creep-stroganoff/paso-completo-04-20261103.webp","image_alt":"Fais revenir l'oignon et l'ail"},{"title":"Fais dorer le bœuf","content":"Ajoute le bœuf et fais-le dorer 3 à 4 minutes ; ajoute les champignons et cuis jusqu'à ce qu'ils soient tendres.","image_alt":"Lanières de bœuf et champignons qui dorent dans la poêle","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Ajoute la farine","content":"Saupoudre la farine et mélange pendant une minute pour qu'elle s'incorpore sans grumeaux.","image_url":"/recetas/creep-stroganoff/paso-completo-06-20261103.webp","image_alt":"Ajoute la farine"},{"title":"Prépare la sauce","content":"Ajoute le bouillon petit à petit en remuant, et cuis jusqu'à ce que la sauce épaississe.","image_alt":"Sauce crémeuse aux champignons et au bœuf prête dans la poêle","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Ajoute la crème","content":"Incorpore la crème et laisse cuire quelques minutes à feu doux, sans laisser bouillir fort.","image_alt":"Crème versée en filet sur la sauce au bœuf et aux champignons","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Garnis et sers","content":"Assaisonne de sel et de poivre, garnis ou recouvre les crêpes et termine avec du persil.","image_url":"/recetas/creep-stroganoff/paso-completo-09-20261103.webp","image_alt":"Garnis et sers"}]},{"id":"b87caa7d-eb4f-49b8-823a-aa89835e7e99","expected_steps":[{"title":"Mescola gli ingredienti secchi","content":"Mescola la farina, lo zucchero e il sale."},{"title":"Prepara la pastella","content":"Sbatti le uova, aggiungi il latte e il burro fuso e unisci agli ingredienti secchi fino a ottenere una pastella senza grumi. Coprite la pastella e lasciatela riposare 30 minuti prima di cuocere le crêpes; il riposo è incluso nei 90 minuti totali.","image_alt":"Pastella liquida per crêpes sbattuta in una ciotola di vetro","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cuoci le crêpes","content":"Cuoci crêpes sottili, da 1 a 2 minuti per lato, in una padella leggermente unta, e mettile da parte.","image_alt":"Crêpe sottile che dora in padella","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Soffriggi cipolla e aglio","content":"Sciogli il burro del ripieno e soffriggi la cipolla e l'aglio."},{"title":"Rosola il manzo","content":"Aggiungi il manzo e rosolalo per 3-4 minuti; aggiungi i funghi e cuoci finché sono teneri.","image_alt":"Listarelle di manzo e funghi che rosolano in padella","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Aggiungi la farina","content":"Cospargi la farina e mescola per un minuto affinché si amalgami senza grumi."},{"title":"Prepara la salsa","content":"Aggiungi il brodo poco alla volta, mescolando, e cuoci finché la salsa si addensa.","image_alt":"Salsa cremosa di funghi e manzo pronta in padella","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Aggiungi la panna","content":"Incorpora la panna e cuoci qualche minuto a fuoco dolce, senza farla bollire con forza.","image_alt":"Panna versata a filo sulla salsa di manzo e funghi","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Farcisci e servi","content":"Aggiusta di sale e pepe, farcisci o copri le crêpes e termina con il prezzemolo."}],"new_steps":[{"title":"Mescola gli ingredienti secchi","content":"Mescola la farina, lo zucchero e il sale.","image_url":"/recetas/creep-stroganoff/paso-completo-01-20261103.webp","image_alt":"Mescola gli ingredienti secchi"},{"title":"Prepara la pastella","content":"Sbatti le uova, aggiungi il latte e il burro fuso e unisci agli ingredienti secchi fino a ottenere una pastella senza grumi. Coprite la pastella e lasciatela riposare 30 minuti prima di cuocere le crêpes; il riposo è incluso nei 90 minuti totali.","image_alt":"Pastella liquida per crêpes sbattuta in una ciotola di vetro","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cuoci le crêpes","content":"Cuoci crêpes sottili, da 1 a 2 minuti per lato, in una padella leggermente unta, e mettile da parte.","image_alt":"Crêpe sottile che dora in padella","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Soffriggi cipolla e aglio","content":"Sciogli il burro del ripieno e soffriggi la cipolla e l'aglio.","image_url":"/recetas/creep-stroganoff/paso-completo-04-20261103.webp","image_alt":"Soffriggi cipolla e aglio"},{"title":"Rosola il manzo","content":"Aggiungi il manzo e rosolalo per 3-4 minuti; aggiungi i funghi e cuoci finché sono teneri.","image_alt":"Listarelle di manzo e funghi che rosolano in padella","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Aggiungi la farina","content":"Cospargi la farina e mescola per un minuto affinché si amalgami senza grumi.","image_url":"/recetas/creep-stroganoff/paso-completo-06-20261103.webp","image_alt":"Aggiungi la farina"},{"title":"Prepara la salsa","content":"Aggiungi il brodo poco alla volta, mescolando, e cuoci finché la salsa si addensa.","image_alt":"Salsa cremosa di funghi e manzo pronta in padella","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Aggiungi la panna","content":"Incorpora la panna e cuoci qualche minuto a fuoco dolce, senza farla bollire con forza.","image_alt":"Panna versata a filo sulla salsa di manzo e funghi","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Farcisci e servi","content":"Aggiusta di sale e pepe, farcisci o copri le crêpes e termina con il prezzemolo.","image_url":"/recetas/creep-stroganoff/paso-completo-09-20261103.webp","image_alt":"Farcisci e servi"}]},{"id":"00631fec-7127-4bec-9379-872c56a2acfc","expected_steps":[{"title":"粉類を混ぜる","content":"小麦粉、砂糖、塩を混ぜ合わせる。"},{"title":"生地を作る","content":"卵を溶き、牛乳と溶かしバターを加えて、粉類とダマがなくなるまで混ぜ合わせる。 生地にふたをして、焼く前に30分休ませます。この休ませ時間は所要時間90分に含まれます。","image_alt":"ガラスボウルで泡立てたクレープ生地","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"クレープを焼く","content":"薄く油を引いたフライパンで、片面1〜2分ずつ薄いクレープを焼き、取り分けておく。","image_alt":"フライパンで焼き色がつく薄いクレープ","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"玉ねぎとにんにくを炒める","content":"具材用のバターを溶かし、玉ねぎとにんにくを炒める。"},{"title":"牛肉を焼く","content":"牛肉を加えて3〜4分焼き色をつけ、マッシュルームを加えて柔らかくなるまで火を通す。","image_alt":"フライパンで焼き色がつく牛肉の細切りとマッシュルーム","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"小麦粉を加える","content":"小麦粉を振り入れ、ダマにならないよう1分ほど混ぜる。"},{"title":"ソースを作る","content":"ブロスを少しずつ加えながら混ぜ、ソースがとろみがつくまで煮る。","image_alt":"フライパンで仕上がったクリーミーなきのこと牛肉のソース","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"生クリームを加える","content":"生クリームを加え、強く沸騰させないよう弱火で数分煮る。","image_alt":"牛肉ときのこのソースに細く生クリームを注ぐ様子","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"包んで盛り付ける","content":"塩こしょうで味を調え、クレープに包むかのせて、パセリを散らして仕上げる。"}],"new_steps":[{"title":"粉類を混ぜる","content":"小麦粉、砂糖、塩を混ぜ合わせる。","image_url":"/recetas/creep-stroganoff/paso-completo-01-20261103.webp","image_alt":"粉類を混ぜる"},{"title":"生地を作る","content":"卵を溶き、牛乳と溶かしバターを加えて、粉類とダマがなくなるまで混ぜ合わせる。 生地にふたをして、焼く前に30分休ませます。この休ませ時間は所要時間90分に含まれます。","image_alt":"ガラスボウルで泡立てたクレープ生地","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"クレープを焼く","content":"薄く油を引いたフライパンで、片面1〜2分ずつ薄いクレープを焼き、取り分けておく。","image_alt":"フライパンで焼き色がつく薄いクレープ","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"玉ねぎとにんにくを炒める","content":"具材用のバターを溶かし、玉ねぎとにんにくを炒める。","image_url":"/recetas/creep-stroganoff/paso-completo-04-20261103.webp","image_alt":"玉ねぎとにんにくを炒める"},{"title":"牛肉を焼く","content":"牛肉を加えて3〜4分焼き色をつけ、マッシュルームを加えて柔らかくなるまで火を通す。","image_alt":"フライパンで焼き色がつく牛肉の細切りとマッシュルーム","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"小麦粉を加える","content":"小麦粉を振り入れ、ダマにならないよう1分ほど混ぜる。","image_url":"/recetas/creep-stroganoff/paso-completo-06-20261103.webp","image_alt":"小麦粉を加える"},{"title":"ソースを作る","content":"ブロスを少しずつ加えながら混ぜ、ソースがとろみがつくまで煮る。","image_alt":"フライパンで仕上がったクリーミーなきのこと牛肉のソース","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"生クリームを加える","content":"生クリームを加え、強く沸騰させないよう弱火で数分煮る。","image_alt":"牛肉ときのこのソースに細く生クリームを注ぐ様子","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"包んで盛り付ける","content":"塩こしょうで味を調え、クレープに包むかのせて、パセリを散らして仕上げる。","image_url":"/recetas/creep-stroganoff/paso-completo-09-20261103.webp","image_alt":"包んで盛り付ける"}]},{"id":"fd9286e6-bae7-4889-9558-7e34ff073824","expected_steps":[{"title":"Misture os ingredientes secos","content":"Misture a farinha, o açúcar e o sal."},{"title":"Prepare a massa","content":"Bata os ovos, junte o leite e a manteiga derretida, e misture com os ingredientes secos até obter uma massa sem grumos. Cubra a massa e deixe descansar por 30 minutos antes de fazer as panquecas; esse descanso está incluído nos 90 minutos totais.","image_alt":"Massa líquida de panqueca batida numa tigela de vidro","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cozinhe as panquecas","content":"Cozinhe panquecas finas, de 1 a 2 minutos de cada lado, numa frigideira levemente untada, e reserve-as.","image_alt":"Panqueca fina a dourar numa frigideira","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Refogue a cebola e o alho","content":"Derreta a manteiga do recheio e refogue a cebola e o alho."},{"title":"Doure a carne","content":"Junte a carne e doure-a por 3 a 4 minutos; acrescente os cogumelos e cozinhe até ficarem macios.","image_alt":"Tiras de carne e cogumelos a dourar na frigideira","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Adicione a farinha","content":"Polvilhe a farinha e mexa durante um minuto para incorporar sem grumos."},{"title":"Prepare o molho","content":"Adicione o caldo aos poucos, mexendo, e cozinhe até o molho engrossar.","image_alt":"Molho cremoso de cogumelos e carne pronto na frigideira","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Adicione as natas","content":"Junte as natas e cozinhe alguns minutos em fogo brando, sem deixar ferver com força.","image_alt":"Natas a cair em fio sobre o molho de carne e cogumelos","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Recheie e sirva","content":"Tempere com sal e pimenta, recheie ou cubra as panquecas e finalize com salsa."}],"new_steps":[{"title":"Misture os ingredientes secos","content":"Misture a farinha, o açúcar e o sal.","image_url":"/recetas/creep-stroganoff/paso-completo-01-20261103.webp","image_alt":"Misture os ingredientes secos"},{"title":"Prepare a massa","content":"Bata os ovos, junte o leite e a manteiga derretida, e misture com os ingredientes secos até obter uma massa sem grumos. Cubra a massa e deixe descansar por 30 minutos antes de fazer as panquecas; esse descanso está incluído nos 90 minutos totais.","image_alt":"Massa líquida de panqueca batida numa tigela de vidro","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cozinhe as panquecas","content":"Cozinhe panquecas finas, de 1 a 2 minutos de cada lado, numa frigideira levemente untada, e reserve-as.","image_alt":"Panqueca fina a dourar numa frigideira","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Refogue a cebola e o alho","content":"Derreta a manteiga do recheio e refogue a cebola e o alho.","image_url":"/recetas/creep-stroganoff/paso-completo-04-20261103.webp","image_alt":"Refogue a cebola e o alho"},{"title":"Doure a carne","content":"Junte a carne e doure-a por 3 a 4 minutos; acrescente os cogumelos e cozinhe até ficarem macios.","image_alt":"Tiras de carne e cogumelos a dourar na frigideira","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Adicione a farinha","content":"Polvilhe a farinha e mexa durante um minuto para incorporar sem grumos.","image_url":"/recetas/creep-stroganoff/paso-completo-06-20261103.webp","image_alt":"Adicione a farinha"},{"title":"Prepare o molho","content":"Adicione o caldo aos poucos, mexendo, e cozinhe até o molho engrossar.","image_alt":"Molho cremoso de cogumelos e carne pronto na frigideira","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Adicione as natas","content":"Junte as natas e cozinhe alguns minutos em fogo brando, sem deixar ferver com força.","image_alt":"Natas a cair em fio sobre o molho de carne e cogumelos","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Recheie e sirva","content":"Tempere com sal e pimenta, recheie ou cubra as panquecas e finalize com salsa.","image_url":"/recetas/creep-stroganoff/paso-completo-09-20261103.webp","image_alt":"Recheie e sirva"}]},{"id":"2d694a6a-8f54-4f22-baf7-8eb35be724a4","expected_steps":[{"title":"Feigen waschen","content":"Die 600 g Feigen unter fließendem Wasser waschen. Feste Früchte ohne Druckstellen oder Schimmel verwenden; sehr reife, weiche Früchte vermeiden.","image_alt":"Feigen waschen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Feigen einritzen","content":"Am unteren Ende jeder Feige ein etwa 5 mm tiefes Kreuz einritzen, ohne sie zu zerteilen. Nur eine hervorstehende harte Stielspitze kürzen.","image_alt":"Feigen einritzen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Feigen weichkochen","content":"Die Feigen in den 1500 ml Wasser mit den 2 g Natron ab dem sanften Aufkochen 20–30 Minuten garen, bis ein Spieß leicht hineingleitet.","image_alt":"Feigen weichkochen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Feigen abspülen","content":"Die gegarten Feigen mit sauberem Wasser abspülen, um das Natron zu entfernen. Vor dem Sirup sollen sie gut abgetropft sein."},{"title":"Sirup zubereiten","content":"Die 400 g Panela in den 1000 ml Wasser mit Zimtstange und 4 Nelken bei kleiner Hitze etwa 10 Minuten auflösen.","image_alt":"Sirup zubereiten","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Feigen im Sirup garen","content":"Die ganzen Feigen offen bei kleiner Hitze 90–120 Minuten im Sirup garen. Sie sind fertig, wenn sie dunkel glänzen und der Sirup einen Löffel leicht überzieht; den Topf behutsam schwenken, ohne die Früchte zu zerdrücken.","image_alt":"Feigen im Sirup garen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Gewürze entfernen","content":"Nach dem Garen die Zimtstange und alle 4 Nelken herausnehmen.","image_alt":"Gewürze entfernen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Dessert kühlen","content":"Die Feigen im Sirup in einem flachen Gefäß höchstens 1 Stunde abkühlen, dann 4 Stunden bei höchstens 4 °C kühlen. Insgesamt nicht länger als 2 Stunden ungekühlt stehen lassen.","image_alt":"Dessert kühlen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Servieren","content":"Je 2 Feigen mit einem Anteil Sirup, 20 g Dulce de leche und 30 g frischem Käse servieren. Ergibt 6 Portionen.","image_alt":"Servieren","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}],"new_steps":[{"title":"Feigen waschen","content":"Die 600 g Feigen unter fließendem Wasser waschen. Feste Früchte ohne Druckstellen oder Schimmel verwenden; sehr reife, weiche Früchte vermeiden.","image_alt":"Feigen waschen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Feigen einritzen","content":"Am unteren Ende jeder Feige ein etwa 5 mm tiefes Kreuz einritzen, ohne sie zu zerteilen. Nur eine hervorstehende harte Stielspitze kürzen.","image_alt":"Feigen einritzen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Feigen weichkochen","content":"Die Feigen in den 1500 ml Wasser mit den 2 g Natron ab dem sanften Aufkochen 20–30 Minuten garen, bis ein Spieß leicht hineingleitet.","image_alt":"Feigen weichkochen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Feigen abspülen","content":"Die gegarten Feigen mit sauberem Wasser abspülen, um das Natron zu entfernen. Vor dem Sirup sollen sie gut abgetropft sein.","image_url":"/recetas/dulce-de-breva/paso-completo-04-20261103.webp","image_alt":"Feigen abspülen"},{"title":"Sirup zubereiten","content":"Die 400 g Panela in den 1000 ml Wasser mit Zimtstange und 4 Nelken bei kleiner Hitze etwa 10 Minuten auflösen.","image_alt":"Sirup zubereiten","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Feigen im Sirup garen","content":"Die ganzen Feigen offen bei kleiner Hitze 90–120 Minuten im Sirup garen. Sie sind fertig, wenn sie dunkel glänzen und der Sirup einen Löffel leicht überzieht; den Topf behutsam schwenken, ohne die Früchte zu zerdrücken.","image_alt":"Feigen im Sirup garen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Gewürze entfernen","content":"Nach dem Garen die Zimtstange und alle 4 Nelken herausnehmen.","image_alt":"Gewürze entfernen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Dessert kühlen","content":"Die Feigen im Sirup in einem flachen Gefäß höchstens 1 Stunde abkühlen, dann 4 Stunden bei höchstens 4 °C kühlen. Insgesamt nicht länger als 2 Stunden ungekühlt stehen lassen.","image_alt":"Dessert kühlen","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Servieren","content":"Je 2 Feigen mit einem Anteil Sirup, 20 g Dulce de leche und 30 g frischem Käse servieren. Ergibt 6 Portionen.","image_alt":"Servieren","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]},{"id":"d41bb633-21d2-473e-8f3d-578a11343898","expected_steps":[{"title":"Wash the figs","content":"Wash the 600 g figs under running water. Choose firm fruit without bruising or mold; avoid very ripe, soft figs.","image_alt":"Wash the figs","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Score the figs","content":"Make a shallow cross about 5 mm deep in the base of each fig without splitting it apart. Trim only the hard stem tip if it sticks out.","image_alt":"Score the figs","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Soften the figs","content":"Cook the figs in the 1500 ml water with the 2 g baking soda for 20–30 minutes from a gentle boil, until a skewer slides in easily.","image_alt":"Soften the figs","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Rinse the figs","content":"Rinse the cooked figs with clean water to remove the baking soda. They should be well drained before going into the syrup."},{"title":"Make the syrup","content":"Dissolve the 400 g panela in the 1000 ml water with the cinnamon stick and 4 cloves over low heat for about 10 minutes.","image_alt":"Make the syrup","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Simmer in syrup","content":"Cook the whole figs uncovered in the syrup over low heat for 90–120 minutes. They are ready when dark and glossy and the syrup lightly coats a spoon; gently swirl the pan rather than crushing the fruit.","image_alt":"Simmer in syrup","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Remove the spices","content":"Remove the cinnamon stick and all 4 cloves when cooking is complete.","image_alt":"Remove the spices","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Chill the dessert","content":"Cool the figs in their syrup in a shallow container for no more than 1 hour, then refrigerate for 4 hours at 4 °C or below. Total time out of the refrigerator must stay under 2 hours.","image_alt":"Chill the dessert","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Serve","content":"Serve 2 figs per person with a share of the syrup, 20 g dulce de leche and 30 g fresh cheese. Makes 6 servings.","image_alt":"Serve","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}],"new_steps":[{"title":"Wash the figs","content":"Wash the 600 g figs under running water. Choose firm fruit without bruising or mold; avoid very ripe, soft figs.","image_alt":"Wash the figs","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Score the figs","content":"Make a shallow cross about 5 mm deep in the base of each fig without splitting it apart. Trim only the hard stem tip if it sticks out.","image_alt":"Score the figs","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Soften the figs","content":"Cook the figs in the 1500 ml water with the 2 g baking soda for 20–30 minutes from a gentle boil, until a skewer slides in easily.","image_alt":"Soften the figs","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Rinse the figs","content":"Rinse the cooked figs with clean water to remove the baking soda. They should be well drained before going into the syrup.","image_url":"/recetas/dulce-de-breva/paso-completo-04-20261103.webp","image_alt":"Rinse the figs"},{"title":"Make the syrup","content":"Dissolve the 400 g panela in the 1000 ml water with the cinnamon stick and 4 cloves over low heat for about 10 minutes.","image_alt":"Make the syrup","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Simmer in syrup","content":"Cook the whole figs uncovered in the syrup over low heat for 90–120 minutes. They are ready when dark and glossy and the syrup lightly coats a spoon; gently swirl the pan rather than crushing the fruit.","image_alt":"Simmer in syrup","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Remove the spices","content":"Remove the cinnamon stick and all 4 cloves when cooking is complete.","image_alt":"Remove the spices","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Chill the dessert","content":"Cool the figs in their syrup in a shallow container for no more than 1 hour, then refrigerate for 4 hours at 4 °C or below. Total time out of the refrigerator must stay under 2 hours.","image_alt":"Chill the dessert","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Serve","content":"Serve 2 figs per person with a share of the syrup, 20 g dulce de leche and 30 g fresh cheese. Makes 6 servings.","image_alt":"Serve","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]},{"id":"4c3ce8ab-9b2e-4950-857c-1b34381d0eaa","expected_steps":[{"title":"Lava las brevas","content":"Lava los 600 g de brevas bajo agua corriente. Deben estar firmes, sin golpes ni moho; evita las frutas muy maduras y blandas.","image_alt":"Lava las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Marca las brevas","content":"Haz una cruz superficial de unos 5 mm en la base de cada breva, sin partirla ni quitarle la forma entera. Recorta solo la punta dura del tallo si sobresale.","image_alt":"Marca las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Ablanda las brevas","content":"Cuece las brevas en los 1500 ml de agua con los 2 g de bicarbonato durante 20–30 minutos desde el hervor suave, hasta que una brocheta entre con facilidad.","image_alt":"Ablanda las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Enjuaga las brevas","content":"Enjuaga las brevas cocidas con agua limpia para retirar el bicarbonato. Deben quedar bien escurridas antes del almíbar."},{"title":"Prepara el almíbar","content":"Disuelve los 400 g de panela en los 1000 ml de agua con la rama de canela y los 4 clavos, a fuego bajo durante unos 10 minutos.","image_alt":"Prepara el almíbar","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Cala las brevas","content":"Cocina las brevas enteras en el almíbar, destapadas y a fuego bajo, durante 90–120 minutos. Están listas cuando se ven oscuras y brillantes y el almíbar cubre ligeramente una cuchara; mueve la olla suavemente sin aplastarlas.","image_alt":"Cala las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Retira las especias","content":"Retira la canela y los 4 clavos del almíbar al terminar la cocción.","image_alt":"Retira las especias","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Enfría el dulce","content":"Enfría las brevas en su almíbar en un recipiente poco profundo durante un máximo de 1 hora y refrigera 4 horas a 4 °C o menos. No las dejes fuera más de 2 horas en total.","image_alt":"Enfría el dulce","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Sirve","content":"Sirve 2 brevas por persona con su parte del almíbar, 20 g de arequipe y 30 g de queso fresco. Rinde 6 porciones.","image_alt":"Sirve","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}],"new_steps":[{"title":"Lava las brevas","content":"Lava los 600 g de brevas bajo agua corriente. Deben estar firmes, sin golpes ni moho; evita las frutas muy maduras y blandas.","image_alt":"Lava las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Marca las brevas","content":"Haz una cruz superficial de unos 5 mm en la base de cada breva, sin partirla ni quitarle la forma entera. Recorta solo la punta dura del tallo si sobresale.","image_alt":"Marca las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Ablanda las brevas","content":"Cuece las brevas en los 1500 ml de agua con los 2 g de bicarbonato durante 20–30 minutos desde el hervor suave, hasta que una brocheta entre con facilidad.","image_alt":"Ablanda las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Enjuaga las brevas","content":"Enjuaga las brevas cocidas con agua limpia para retirar el bicarbonato. Deben quedar bien escurridas antes del almíbar.","image_url":"/recetas/dulce-de-breva/paso-completo-04-20261103.webp","image_alt":"Enjuaga las brevas"},{"title":"Prepara el almíbar","content":"Disuelve los 400 g de panela en los 1000 ml de agua con la rama de canela y los 4 clavos, a fuego bajo durante unos 10 minutos.","image_alt":"Prepara el almíbar","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Cala las brevas","content":"Cocina las brevas enteras en el almíbar, destapadas y a fuego bajo, durante 90–120 minutos. Están listas cuando se ven oscuras y brillantes y el almíbar cubre ligeramente una cuchara; mueve la olla suavemente sin aplastarlas.","image_alt":"Cala las brevas","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Retira las especias","content":"Retira la canela y los 4 clavos del almíbar al terminar la cocción.","image_alt":"Retira las especias","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Enfría el dulce","content":"Enfría las brevas en su almíbar en un recipiente poco profundo durante un máximo de 1 hora y refrigera 4 horas a 4 °C o menos. No las dejes fuera más de 2 horas en total.","image_alt":"Enfría el dulce","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Sirve","content":"Sirve 2 brevas por persona con su parte del almíbar, 20 g de arequipe y 30 g de queso fresco. Rinde 6 porciones.","image_alt":"Sirve","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]},{"id":"d43e9e8c-29d5-41a3-b183-893164608531","expected_steps":[{"title":"Lavez les figues","content":"Lavez les 600 g de figues sous l’eau courante. Choisissez des fruits fermes, sans chocs ni moisissure ; évitez les figues très mûres et molles.","image_alt":"Lavez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Incisez les figues","content":"Faites une croix superficielle d’environ 5 mm à la base de chaque figue sans la partager. Raccourcissez seulement la pointe dure de la tige si elle dépasse.","image_alt":"Incisez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Attendrissez les figues","content":"Cuisez les figues dans les 1500 ml d’eau avec les 2 g de bicarbonate pendant 20–30 minutes dès le petit bouillon, jusqu’à ce qu’une pique entre facilement.","image_alt":"Attendrissez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Rincez les figues","content":"Rincez les figues cuites à l’eau propre pour enlever le bicarbonate. Elles doivent être bien égouttées avant le sirop."},{"title":"Préparez le sirop","content":"Faites dissoudre les 400 g de panela dans les 1000 ml d’eau avec la cannelle et les 4 clous de girofle à feu doux pendant environ 10 minutes.","image_alt":"Préparez le sirop","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Confisez les figues","content":"Cuisez les figues entières à découvert dans le sirop à feu doux pendant 90–120 minutes. Elles sont prêtes lorsqu’elles deviennent foncées et brillantes et que le sirop nappe légèrement une cuillère ; remuez doucement la casserole sans écraser les fruits.","image_alt":"Confisez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Retirez les épices","content":"Retirez la cannelle et les 4 clous de girofle après la cuisson.","image_alt":"Retirez les épices","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Faites refroidir","content":"Laissez refroidir les figues dans leur sirop dans un récipient peu profond pendant 1 heure maximum, puis réfrigérez 4 heures à 4 °C maximum. Ne dépassez pas 2 heures au total hors du réfrigérateur.","image_alt":"Faites refroidir","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Servez","content":"Servez 2 figues par personne avec une part du sirop, 20 g de dulce de leche et 30 g de fromage frais. Vous obtenez 6 portions.","image_alt":"Servez","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}],"new_steps":[{"title":"Lavez les figues","content":"Lavez les 600 g de figues sous l’eau courante. Choisissez des fruits fermes, sans chocs ni moisissure ; évitez les figues très mûres et molles.","image_alt":"Lavez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Incisez les figues","content":"Faites une croix superficielle d’environ 5 mm à la base de chaque figue sans la partager. Raccourcissez seulement la pointe dure de la tige si elle dépasse.","image_alt":"Incisez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Attendrissez les figues","content":"Cuisez les figues dans les 1500 ml d’eau avec les 2 g de bicarbonate pendant 20–30 minutes dès le petit bouillon, jusqu’à ce qu’une pique entre facilement.","image_alt":"Attendrissez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Rincez les figues","content":"Rincez les figues cuites à l’eau propre pour enlever le bicarbonate. Elles doivent être bien égouttées avant le sirop.","image_url":"/recetas/dulce-de-breva/paso-completo-04-20261103.webp","image_alt":"Rincez les figues"},{"title":"Préparez le sirop","content":"Faites dissoudre les 400 g de panela dans les 1000 ml d’eau avec la cannelle et les 4 clous de girofle à feu doux pendant environ 10 minutes.","image_alt":"Préparez le sirop","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Confisez les figues","content":"Cuisez les figues entières à découvert dans le sirop à feu doux pendant 90–120 minutes. Elles sont prêtes lorsqu’elles deviennent foncées et brillantes et que le sirop nappe légèrement une cuillère ; remuez doucement la casserole sans écraser les fruits.","image_alt":"Confisez les figues","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Retirez les épices","content":"Retirez la cannelle et les 4 clous de girofle après la cuisson.","image_alt":"Retirez les épices","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Faites refroidir","content":"Laissez refroidir les figues dans leur sirop dans un récipient peu profond pendant 1 heure maximum, puis réfrigérez 4 heures à 4 °C maximum. Ne dépassez pas 2 heures au total hors du réfrigérateur.","image_alt":"Faites refroidir","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Servez","content":"Servez 2 figues par personne avec une part du sirop, 20 g de dulce de leche et 30 g de fromage frais. Vous obtenez 6 portions.","image_alt":"Servez","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]},{"id":"fe3180b9-0ef3-4b76-a3cb-6426a0516f1c","expected_steps":[{"title":"Lava i fichi","content":"Lava i 600 g di fichi sotto acqua corrente. Scegli frutti sodi, senza ammaccature o muffa; evita quelli molto maturi e molli.","image_alt":"Lava i fichi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Incidi i fichi","content":"Incidi una croce superficiale di circa 5 mm alla base di ogni fico, senza dividerlo. Accorcia soltanto la punta dura del picciolo se sporge.","image_alt":"Incidi i fichi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Ammorbidisci i fichi","content":"Cuoci i fichi nei 1500 ml d’acqua con i 2 g di bicarbonato per 20–30 minuti dal leggero bollore, finché uno stecchino entra facilmente.","image_alt":"Ammorbidisci i fichi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Sciacqua i fichi","content":"Sciacqua i fichi cotti con acqua pulita per eliminare il bicarbonato. Devono essere ben scolati prima dello sciroppo."},{"title":"Prepara lo sciroppo","content":"Sciogli i 400 g di panela nei 1000 ml d’acqua con la cannella e i 4 chiodi di garofano a fuoco basso per circa 10 minuti.","image_alt":"Prepara lo sciroppo","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Cuoci nello sciroppo","content":"Cuoci i fichi interi scoperti nello sciroppo a fuoco basso per 90–120 minuti. Sono pronti quando diventano scuri e lucidi e lo sciroppo vela leggermente un cucchiaio; muovi delicatamente la pentola senza schiacciare i frutti.","image_alt":"Cuoci nello sciroppo","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Togli le spezie","content":"Togli la cannella e tutti e 4 i chiodi di garofano a cottura ultimata.","image_alt":"Togli le spezie","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Fai raffreddare","content":"Fai raffreddare i fichi nel loro sciroppo in un contenitore basso per non più di 1 ora, poi metti in frigorifero per 4 ore a 4 °C o meno. Non superare 2 ore complessive fuori dal frigorifero.","image_alt":"Fai raffreddare","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Servi","content":"Servi 2 fichi a persona con una parte di sciroppo, 20 g di dulce de leche e 30 g di formaggio fresco. Ottieni 6 porzioni.","image_alt":"Servi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}],"new_steps":[{"title":"Lava i fichi","content":"Lava i 600 g di fichi sotto acqua corrente. Scegli frutti sodi, senza ammaccature o muffa; evita quelli molto maturi e molli.","image_alt":"Lava i fichi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Incidi i fichi","content":"Incidi una croce superficiale di circa 5 mm alla base di ogni fico, senza dividerlo. Accorcia soltanto la punta dura del picciolo se sporge.","image_alt":"Incidi i fichi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Ammorbidisci i fichi","content":"Cuoci i fichi nei 1500 ml d’acqua con i 2 g di bicarbonato per 20–30 minuti dal leggero bollore, finché uno stecchino entra facilmente.","image_alt":"Ammorbidisci i fichi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Sciacqua i fichi","content":"Sciacqua i fichi cotti con acqua pulita per eliminare il bicarbonato. Devono essere ben scolati prima dello sciroppo.","image_url":"/recetas/dulce-de-breva/paso-completo-04-20261103.webp","image_alt":"Sciacqua i fichi"},{"title":"Prepara lo sciroppo","content":"Sciogli i 400 g di panela nei 1000 ml d’acqua con la cannella e i 4 chiodi di garofano a fuoco basso per circa 10 minuti.","image_alt":"Prepara lo sciroppo","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Cuoci nello sciroppo","content":"Cuoci i fichi interi scoperti nello sciroppo a fuoco basso per 90–120 minuti. Sono pronti quando diventano scuri e lucidi e lo sciroppo vela leggermente un cucchiaio; muovi delicatamente la pentola senza schiacciare i frutti.","image_alt":"Cuoci nello sciroppo","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Togli le spezie","content":"Togli la cannella e tutti e 4 i chiodi di garofano a cottura ultimata.","image_alt":"Togli le spezie","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Fai raffreddare","content":"Fai raffreddare i fichi nel loro sciroppo in un contenitore basso per non più di 1 ora, poi metti in frigorifero per 4 ore a 4 °C o meno. Non superare 2 ore complessive fuori dal frigorifero.","image_alt":"Fai raffreddare","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Servi","content":"Servi 2 fichi a persona con una parte di sciroppo, 20 g di dulce de leche e 30 g di formaggio fresco. Ottieni 6 porzioni.","image_alt":"Servi","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]},{"id":"ffdcc006-dcf7-420a-a3a6-8ad347cd61b2","expected_steps":[{"title":"いちじくを洗う","content":"いちじく600 gを流水で洗います。傷やかびのないかための果実を選び、熟しすぎて柔らかいものは避けます。","image_alt":"いちじくを洗う","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"切り込みを入れる","content":"各果実の底に深さ約5 mmの浅い十字を入れ、実を割らず丸ごと保ちます。軸の先が硬く突き出ている場合は先端だけ短くします。","image_alt":"切り込みを入れる","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"いちじくを下ゆでする","content":"水1500 mlと重曹2 gで、静かに沸いてから20〜30分ゆでます。竹串がすっと入る柔らかさが目安です。","image_alt":"いちじくを下ゆでする","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"いちじくをすすぐ","content":"ゆでたいちじくをきれいな水ですすぎ、重曹を落とします。シロップに入れる前に水気をよく切った状態にします。"},{"title":"シロップを作る","content":"パネラ400 gを水1000 ml、シナモン1本、クローブ4個とともに弱火で約10分加熱し、溶かします。","image_alt":"シロップを作る","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"シロップで煮る","content":"丸ごとのいちじくをシロップに入れ、ふたをせず弱火で90〜120分煮ます。色が濃くなってつやが出て、シロップが薄くスプーンを覆えば完成です。果実をつぶさず鍋をそっと揺らします。","image_alt":"シロップで煮る","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"スパイスを取り出す","content":"煮上がったらシナモンとクローブ4個を取り除きます。","image_alt":"スパイスを取り出す","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"冷やす","content":"浅い容器でシロップごと1時間以内を目安に冷まし、4 °C以下の冷蔵庫で4時間冷やします。室温に置く時間は合計2時間を超えないようにします。","image_alt":"冷やす","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"盛り付ける","content":"1人につきいちじく2個とシロップの6分の1量、ドゥルセ・デ・レチェ20 g、チーズ30 gを盛り付けます。6人分です。","image_alt":"盛り付ける","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}],"new_steps":[{"title":"いちじくを洗う","content":"いちじく600 gを流水で洗います。傷やかびのないかための果実を選び、熟しすぎて柔らかいものは避けます。","image_alt":"いちじくを洗う","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"切り込みを入れる","content":"各果実の底に深さ約5 mmの浅い十字を入れ、実を割らず丸ごと保ちます。軸の先が硬く突き出ている場合は先端だけ短くします。","image_alt":"切り込みを入れる","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"いちじくを下ゆでする","content":"水1500 mlと重曹2 gで、静かに沸いてから20〜30分ゆでます。竹串がすっと入る柔らかさが目安です。","image_alt":"いちじくを下ゆでする","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"いちじくをすすぐ","content":"ゆでたいちじくをきれいな水ですすぎ、重曹を落とします。シロップに入れる前に水気をよく切った状態にします。","image_url":"/recetas/dulce-de-breva/paso-completo-04-20261103.webp","image_alt":"いちじくをすすぐ"},{"title":"シロップを作る","content":"パネラ400 gを水1000 ml、シナモン1本、クローブ4個とともに弱火で約10分加熱し、溶かします。","image_alt":"シロップを作る","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"シロップで煮る","content":"丸ごとのいちじくをシロップに入れ、ふたをせず弱火で90〜120分煮ます。色が濃くなってつやが出て、シロップが薄くスプーンを覆えば完成です。果実をつぶさず鍋をそっと揺らします。","image_alt":"シロップで煮る","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"スパイスを取り出す","content":"煮上がったらシナモンとクローブ4個を取り除きます。","image_alt":"スパイスを取り出す","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"冷やす","content":"浅い容器でシロップごと1時間以内を目安に冷まし、4 °C以下の冷蔵庫で4時間冷やします。室温に置く時間は合計2時間を超えないようにします。","image_alt":"冷やす","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"盛り付ける","content":"1人につきいちじく2個とシロップの6分の1量、ドゥルセ・デ・レチェ20 g、チーズ30 gを盛り付けます。6人分です。","image_alt":"盛り付ける","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]},{"id":"c515af5f-faae-46b8-894a-ec30988dc43f","expected_steps":[{"title":"Lave os figos","content":"Lave os 600 g de figos em água corrente. Escolha frutos firmes, sem machucados ou mofo; evite figos muito maduros e moles.","image_alt":"Lave os figos","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Marque os figos","content":"Faça uma cruz superficial de cerca de 5 mm na base de cada figo, sem parti-lo. Apare apenas a ponta dura do cabinho se estiver saliente.","image_alt":"Marque os figos","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Amacie os figos","content":"Cozinhe os figos nos 1500 ml de água com os 2 g de bicarbonato por 20–30 minutos a partir da fervura suave, até um palito entrar facilmente.","image_alt":"Amacie os figos","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Enxágue os figos","content":"Enxágue os figos cozidos com água limpa para retirar o bicarbonato. Eles devem estar bem escorridos antes de ir para a calda."},{"title":"Prepare a calda","content":"Dissolva os 400 g de panela nos 1000 ml de água com a canela em pau e os 4 cravos em fogo baixo por cerca de 10 minutos.","image_alt":"Prepare a calda","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Cozinhe na calda","content":"Cozinhe os figos inteiros destampados na calda em fogo baixo por 90–120 minutos. Estão prontos quando ficam escuros e brilhantes e a calda cobre levemente uma colher; mova a panela com cuidado, sem amassar a fruta.","image_alt":"Cozinhe na calda","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Retire as especiarias","content":"Retire a canela e os 4 cravos ao terminar o cozimento.","image_alt":"Retire as especiarias","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Esfrie o doce","content":"Esfrie os figos na própria calda num recipiente raso por no máximo 1 hora e leve à geladeira por 4 horas a 4 °C ou menos. Não ultrapasse 2 horas no total fora da geladeira.","image_alt":"Esfrie o doce","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Sirva","content":"Sirva 2 figos por pessoa com uma parte da calda, 20 g de doce de leite e 30 g de queijo fresco. Rende 6 porções.","image_alt":"Sirva","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}],"new_steps":[{"title":"Lave os figos","content":"Lave os 600 g de figos em água corrente. Escolha frutos firmes, sem machucados ou mofo; evite figos muito maduros e moles.","image_alt":"Lave os figos","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-01.webp"},{"title":"Marque os figos","content":"Faça uma cruz superficial de cerca de 5 mm na base de cada figo, sem parti-lo. Apare apenas a ponta dura do cabinho se estiver saliente.","image_alt":"Marque os figos","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-02.webp"},{"title":"Amacie os figos","content":"Cozinhe os figos nos 1500 ml de água com os 2 g de bicarbonato por 20–30 minutos a partir da fervura suave, até um palito entrar facilmente.","image_alt":"Amacie os figos","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-03.webp"},{"title":"Enxágue os figos","content":"Enxágue os figos cozidos com água limpa para retirar o bicarbonato. Eles devem estar bem escorridos antes de ir para a calda.","image_url":"/recetas/dulce-de-breva/paso-completo-04-20261103.webp","image_alt":"Enxágue os figos"},{"title":"Prepare a calda","content":"Dissolva os 400 g de panela nos 1000 ml de água com a canela em pau e os 4 cravos em fogo baixo por cerca de 10 minutos.","image_alt":"Prepare a calda","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-05.webp"},{"title":"Cozinhe na calda","content":"Cozinhe os figos inteiros destampados na calda em fogo baixo por 90–120 minutos. Estão prontos quando ficam escuros e brilhantes e a calda cobre levemente uma colher; mova a panela com cuidado, sem amassar a fruta.","image_alt":"Cozinhe na calda","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-06.webp"},{"title":"Retire as especiarias","content":"Retire a canela e os 4 cravos ao terminar o cozimento.","image_alt":"Retire as especiarias","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-07.webp"},{"title":"Esfrie o doce","content":"Esfrie os figos na própria calda num recipiente raso por no máximo 1 hora e leve à geladeira por 4 horas a 4 °C ou menos. Não ultrapasse 2 horas no total fora da geladeira.","image_alt":"Esfrie o doce","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/paso-08.webp"},{"title":"Sirva","content":"Sirva 2 figos por pessoa com uma parte da calda, 20 g de doce de leite e 30 g de queijo fresco. Rende 6 porções.","image_alt":"Sirva","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/dulce-de-breva/portada.webp"}]},{"id":"cb27b779-c848-4fb5-a216-64643837a125","expected_steps":[{"title":"Garnelen anbraten","content":"In einer großen Pfanne das Olivenöl bei mittlerer Hitze erhitzen. Die Garnelen hinzugeben und 2-3 Minuten goldbraun anbraten.","image_alt":"Garnelen bräunen in heißem Olivenöl in einer Pfanne","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Knoblauch hinzufügen","content":"Den gehackten Knoblauch dazugeben und weitere 30 Sekunden anbraten, dabei darauf achten, dass er nicht verbrennt.","image_alt":"Garnelen mit gehacktem Knoblauch in der Pfanne beim Anbraten","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Wein und Paprika hinzufügen","content":"Weißwein und Paprikapulver hinzufügen und mit Salz und Pfeffer nach Geschmack würzen. 2-3 Minuten köcheln lassen, damit der Alkohol verdampft.","image_alt":"Weißwein wird über die Garnelen in der Pfanne gegossen","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Mit Zitrone und Petersilie abschließen","content":"Zitronensaft und gehackte frische Petersilie hinzufügen. Gut umrühren, um alles zu vermengen.","image_alt":"Zitronensaft träufelt über die fertigen Knoblauch-Garnelen mit Petersilie","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Servieren","content":"Die Knoblauch-Garnelen heiß mit weißem Reis oder knusprigem Brot servieren."}],"new_steps":[{"title":"Garnelen anbraten","content":"In einer großen Pfanne das Olivenöl bei mittlerer Hitze erhitzen. Die Garnelen hinzugeben und 2-3 Minuten goldbraun anbraten.","image_alt":"Garnelen bräunen in heißem Olivenöl in einer Pfanne","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Knoblauch hinzufügen","content":"Den gehackten Knoblauch dazugeben und weitere 30 Sekunden anbraten, dabei darauf achten, dass er nicht verbrennt.","image_alt":"Garnelen mit gehacktem Knoblauch in der Pfanne beim Anbraten","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Wein und Paprika hinzufügen","content":"Weißwein und Paprikapulver hinzufügen und mit Salz und Pfeffer nach Geschmack würzen. 2-3 Minuten köcheln lassen, damit der Alkohol verdampft.","image_alt":"Weißwein wird über die Garnelen in der Pfanne gegossen","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Mit Zitrone und Petersilie abschließen","content":"Zitronensaft und gehackte frische Petersilie hinzufügen. Gut umrühren, um alles zu vermengen.","image_alt":"Zitronensaft träufelt über die fertigen Knoblauch-Garnelen mit Petersilie","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Servieren","content":"Die Knoblauch-Garnelen heiß mit weißem Reis oder knusprigem Brot servieren.","image_url":"/recetas/camarones-al-ajillo/portada.webp","image_alt":"Servieren"}]},{"id":"83d21534-1ba6-41ad-8e74-e281bf7070a8","expected_steps":[{"title":"Sauté the shrimp","content":"In a large skillet, heat the olive oil over medium heat. Add the shrimp and sauté for 2-3 minutes until golden.","image_alt":"Shrimp browning in hot olive oil in a skillet","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Add the garlic","content":"Add the minced garlic and sauté for another 30 seconds, making sure it doesn''t burn.","image_alt":"Shrimp with minced garlic sautéing in the skillet","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Add the wine and paprika","content":"Add the white wine and paprika, and season with salt and pepper to taste. Let it simmer for 2-3 minutes so the alcohol evaporates.","image_alt":"White wine being poured over the shrimp in the skillet","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Finish with lemon and parsley","content":"Add the lemon juice and chopped fresh parsley. Stir to combine everything well.","image_alt":"Lemon juice drizzling over the finished garlic shrimp with parsley","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Serve","content":"Serve the garlic shrimp hot with a side of white rice or crusty bread."}],"new_steps":[{"title":"Sauté the shrimp","content":"In a large skillet, heat the olive oil over medium heat. Add the shrimp and sauté for 2-3 minutes until golden.","image_alt":"Shrimp browning in hot olive oil in a skillet","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Add the garlic","content":"Add the minced garlic and sauté for another 30 seconds, making sure it doesn''t burn.","image_alt":"Shrimp with minced garlic sautéing in the skillet","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Add the wine and paprika","content":"Add the white wine and paprika, and season with salt and pepper to taste. Let it simmer for 2-3 minutes so the alcohol evaporates.","image_alt":"White wine being poured over the shrimp in the skillet","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Finish with lemon and parsley","content":"Add the lemon juice and chopped fresh parsley. Stir to combine everything well.","image_alt":"Lemon juice drizzling over the finished garlic shrimp with parsley","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Serve","content":"Serve the garlic shrimp hot with a side of white rice or crusty bread.","image_url":"/recetas/camarones-al-ajillo/portada.webp","image_alt":"Serve"}]},{"id":"5823090c-3ccb-4798-8ad7-9ea02c095aa8","expected_steps":[{"title":"Sofríe los camarones","content":"En una sartén grande, calienta el aceite de oliva a fuego medio. Agrega los camarones y saltea durante unos 2-3 minutos hasta que se doren.","image_alt":"Camarones dorándose en aceite de oliva caliente en una sartén","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Añade el ajo","content":"Agrega el ajo picado y saltea durante otros 30 segundos, asegurándote de que no se queme.","image_alt":"Camarones con ajo picado salteándose en la sartén","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Añade el vino y el pimentón","content":"Añade el vino blanco y el pimentón y sazona con sal y pimienta al gusto. Deja que la mezcla hierva y se cocine por unos 2-3 minutos para que el alcohol del vino se evapore.","image_alt":"Vino blanco siendo vertido sobre los camarones en la sartén","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Termina con limón y perejil","content":"Agrega el jugo de limón y el perejil fresco picado. Revuelve para combinar bien todos los ingredientes.","image_alt":"Jugo de limón cayendo sobre los camarones al ajillo terminados con perejil","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Sirve","content":"Sirve los camarones al ajillo calientes con una guarnición de arroz blanco o pan crujiente."}],"new_steps":[{"title":"Sofríe los camarones","content":"En una sartén grande, calienta el aceite de oliva a fuego medio. Agrega los camarones y saltea durante unos 2-3 minutos hasta que se doren.","image_alt":"Camarones dorándose en aceite de oliva caliente en una sartén","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Añade el ajo","content":"Agrega el ajo picado y saltea durante otros 30 segundos, asegurándote de que no se queme.","image_alt":"Camarones con ajo picado salteándose en la sartén","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Añade el vino y el pimentón","content":"Añade el vino blanco y el pimentón y sazona con sal y pimienta al gusto. Deja que la mezcla hierva y se cocine por unos 2-3 minutos para que el alcohol del vino se evapore.","image_alt":"Vino blanco siendo vertido sobre los camarones en la sartén","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Termina con limón y perejil","content":"Agrega el jugo de limón y el perejil fresco picado. Revuelve para combinar bien todos los ingredientes.","image_alt":"Jugo de limón cayendo sobre los camarones al ajillo terminados con perejil","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Sirve","content":"Sirve los camarones al ajillo calientes con una guarnición de arroz blanco o pan crujiente.","image_url":"/recetas/camarones-al-ajillo/portada.webp","image_alt":"Sirve"}]},{"id":"4a19ee79-89ac-4203-9a92-9bbb003c5ad7","expected_steps":[{"title":"Fais sauter les crevettes","content":"Dans une grande poêle, chauffe l'huile d'olive à feu moyen. Ajoute les crevettes et fais-les sauter 2-3 minutes jusqu'à ce qu'elles dorent.","image_alt":"Crevettes dorant dans l'huile d'olive chaude dans une poêle","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Ajoute l'ail","content":"Ajoute l'ail haché et fais sauter encore 30 secondes, en veillant à ce qu'il ne brûle pas.","image_alt":"Crevettes avec de l'ail haché sautant dans la poêle","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Ajoute le vin et le paprika","content":"Ajoute le vin blanc et le paprika, puis assaisonne de sel et de poivre au goût. Laisse mijoter 2-3 minutes pour que l'alcool s'évapore.","image_alt":"Vin blanc versé sur les crevettes dans la poêle","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Termine avec le citron et le persil","content":"Ajoute le jus de citron et le persil frais haché. Mélange bien pour combiner tous les ingrédients.","image_alt":"Jus de citron versé sur les crevettes à l'ail terminées avec du persil","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Sers","content":"Sers les crevettes à l'ail bien chaudes, accompagnées de riz blanc ou de pain croustillant."}],"new_steps":[{"title":"Fais sauter les crevettes","content":"Dans une grande poêle, chauffe l'huile d'olive à feu moyen. Ajoute les crevettes et fais-les sauter 2-3 minutes jusqu'à ce qu'elles dorent.","image_alt":"Crevettes dorant dans l'huile d'olive chaude dans une poêle","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Ajoute l'ail","content":"Ajoute l'ail haché et fais sauter encore 30 secondes, en veillant à ce qu'il ne brûle pas.","image_alt":"Crevettes avec de l'ail haché sautant dans la poêle","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Ajoute le vin et le paprika","content":"Ajoute le vin blanc et le paprika, puis assaisonne de sel et de poivre au goût. Laisse mijoter 2-3 minutes pour que l'alcool s'évapore.","image_alt":"Vin blanc versé sur les crevettes dans la poêle","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Termine avec le citron et le persil","content":"Ajoute le jus de citron et le persil frais haché. Mélange bien pour combiner tous les ingrédients.","image_alt":"Jus de citron versé sur les crevettes à l'ail terminées avec du persil","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Sers","content":"Sers les crevettes à l'ail bien chaudes, accompagnées de riz blanc ou de pain croustillant.","image_url":"/recetas/camarones-al-ajillo/portada.webp","image_alt":"Sers"}]},{"id":"f7150793-aba3-4d74-9983-4a6f2c88148f","expected_steps":[{"title":"Salta i gamberi","content":"In una padella grande, scalda l'olio d'oliva a fuoco medio. Aggiungi i gamberi e falli saltare 2-3 minuti finché non si dorano.","image_alt":"Gamberi che si dorano nell'olio d'oliva caldo in padella","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Aggiungi l'aglio","content":"Aggiungi l'aglio tritato e fai saltare per altri 30 secondi, assicurandoti che non bruci.","image_alt":"Gamberi con aglio tritato che saltano in padella","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Aggiungi il vino e la paprika","content":"Aggiungi il vino bianco e la paprika, condisci con sale e pepe q.b. Lascia cuocere 2-3 minuti finché l'alcol evapora.","image_alt":"Vino bianco versato sui gamberi in padella","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Termina con limone e prezzemolo","content":"Aggiungi il succo di limone e il prezzemolo fresco tritato. Mescola bene per amalgamare tutto.","image_alt":"Succo di limone versato sui gamberi all'aglio finiti con prezzemolo","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Servi","content":"Servi i gamberi all'aglio caldi con riso bianco o pane croccante."}],"new_steps":[{"title":"Salta i gamberi","content":"In una padella grande, scalda l'olio d'oliva a fuoco medio. Aggiungi i gamberi e falli saltare 2-3 minuti finché non si dorano.","image_alt":"Gamberi che si dorano nell'olio d'oliva caldo in padella","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Aggiungi l'aglio","content":"Aggiungi l'aglio tritato e fai saltare per altri 30 secondi, assicurandoti che non bruci.","image_alt":"Gamberi con aglio tritato che saltano in padella","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Aggiungi il vino e la paprika","content":"Aggiungi il vino bianco e la paprika, condisci con sale e pepe q.b. Lascia cuocere 2-3 minuti finché l'alcol evapora.","image_alt":"Vino bianco versato sui gamberi in padella","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Termina con limone e prezzemolo","content":"Aggiungi il succo di limone e il prezzemolo fresco tritato. Mescola bene per amalgamare tutto.","image_alt":"Succo di limone versato sui gamberi all'aglio finiti con prezzemolo","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Servi","content":"Servi i gamberi all'aglio caldi con riso bianco o pane croccante.","image_url":"/recetas/camarones-al-ajillo/portada.webp","image_alt":"Servi"}]},{"id":"fa0ce64a-809e-46ab-bb4d-cc91229a25c5","expected_steps":[{"title":"エビを炒める","content":"大きめのフライパンにオリーブオイルを入れ、中火で熱します。エビを加えて2〜3分、こんがりするまで炒めます。","image_alt":"熱いオリーブオイルでこんがり炒められているエビ","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"にんにくを加える","content":"みじん切りにんにくを加え、焦げないように注意しながらさらに30秒炒めます。","image_alt":"みじん切りにんにくと一緒にフライパンで炒められているエビ","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"白ワインとパプリカを加える","content":"白ワインとパプリカパウダーを加え、塩こしょうで味を調えます。アルコールが飛ぶように2〜3分煮ます。","image_alt":"フライパンのエビに白ワインを注いでいるところ","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"レモンとパセリで仕上げる","content":"レモン汁と刻んだ生パセリを加え、よく混ぜ合わせます。","image_alt":"パセリを添えた完成したガーリックシュリンプにレモン汁をかけているところ","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"提供する","content":"白いご飯やパリッとしたパンを添えて、熱々のガーリックシュリンプを提供します。"}],"new_steps":[{"title":"エビを炒める","content":"大きめのフライパンにオリーブオイルを入れ、中火で熱します。エビを加えて2〜3分、こんがりするまで炒めます。","image_alt":"熱いオリーブオイルでこんがり炒められているエビ","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"にんにくを加える","content":"みじん切りにんにくを加え、焦げないように注意しながらさらに30秒炒めます。","image_alt":"みじん切りにんにくと一緒にフライパンで炒められているエビ","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"白ワインとパプリカを加える","content":"白ワインとパプリカパウダーを加え、塩こしょうで味を調えます。アルコールが飛ぶように2〜3分煮ます。","image_alt":"フライパンのエビに白ワインを注いでいるところ","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"レモンとパセリで仕上げる","content":"レモン汁と刻んだ生パセリを加え、よく混ぜ合わせます。","image_alt":"パセリを添えた完成したガーリックシュリンプにレモン汁をかけているところ","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"提供する","content":"白いご飯やパリッとしたパンを添えて、熱々のガーリックシュリンプを提供します。","image_url":"/recetas/camarones-al-ajillo/portada.webp","image_alt":"提供する"}]},{"id":"a4f71689-a182-4e35-96c7-a490d15d3700","expected_steps":[{"title":"Refogue os camarões","content":"Em uma frigideira grande, aqueça o azeite em fogo médio. Adicione os camarões e refogue por 2 a 3 minutos até dourarem.","image_alt":"Camarões dourando em azeite quente na frigideira","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Adicione o alho","content":"Adicione o alho picado e refogue por mais 30 segundos, certificando-se de que não queime.","image_alt":"Camarões com alho picado refogando na frigideira","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Adicione o vinho e a páprica","content":"Adicione o vinho branco e a páprica, tempere com sal e pimenta a gosto. Deixe ferver por 2 a 3 minutos para o álcool evaporar.","image_alt":"Vinho branco sendo despejado sobre os camarões na frigideira","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Finalize com limão e salsa","content":"Adicione o suco de limão e a salsa fresca picada. Misture bem para combinar todos os ingredientes.","image_alt":"Suco de limão sendo despejado sobre o camarão ao alho finalizado com salsa","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Sirva","content":"Sirva o camarão ao alho quente, acompanhado de arroz branco ou pão crocante."}],"new_steps":[{"title":"Refogue os camarões","content":"Em uma frigideira grande, aqueça o azeite em fogo médio. Adicione os camarões e refogue por 2 a 3 minutos até dourarem.","image_alt":"Camarões dourando em azeite quente na frigideira","image_url":"/recetas/camarones-al-ajillo/paso-02.webp"},{"title":"Adicione o alho","content":"Adicione o alho picado e refogue por mais 30 segundos, certificando-se de que não queime.","image_alt":"Camarões com alho picado refogando na frigideira","image_url":"/recetas/camarones-al-ajillo/paso-03.webp"},{"title":"Adicione o vinho e a páprica","content":"Adicione o vinho branco e a páprica, tempere com sal e pimenta a gosto. Deixe ferver por 2 a 3 minutos para o álcool evaporar.","image_alt":"Vinho branco sendo despejado sobre os camarões na frigideira","image_url":"/recetas/camarones-al-ajillo/paso-04.webp"},{"title":"Finalize com limão e salsa","content":"Adicione o suco de limão e a salsa fresca picada. Misture bem para combinar todos os ingredientes.","image_alt":"Suco de limão sendo despejado sobre o camarão ao alho finalizado com salsa","image_url":"/recetas/camarones-al-ajillo/paso-05.webp"},{"title":"Sirva","content":"Sirva o camarão ao alho quente, acompanhado de arroz branco ou pão crocante.","image_url":"/recetas/camarones-al-ajillo/portada.webp","image_alt":"Sirva"}]},{"id":"bfb762c1-2d25-5632-9f26-be6ed20066bc","expected_steps":[{"title":"Den Backofen vorheizen","content":"Backofen mit Ober- und Unterhitze auf 220 °C vorheizen. Während der Vorbereitung etwa 15 Minuten aufheizen lassen."},{"title":"Flügel und Blech vorbereiten","content":"1000 g geteilte Flügel mit Haut und Knochen, ohne Spitzen, bereitstellen; falls nötig vorher im Kühlschrank auftauen. Rohes Hähnchen nicht waschen. Mit Einweg-Küchenpapier trocken tupfen, Hände waschen und ein Gitter in ein tiefes Blech zum Auffangen der Säfte setzen.","image_alt":"Flügel und Blech vorbereiten","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Würzen und einzeln verteilen","content":"Flügel mit 10 g Olivenöl, 3 g Salz und 1 g schwarzem Pfeffer vermischen. In einer Lage mit etwas Abstand auf dem Gitter verteilen. Die Sauce noch nicht dazugeben.","image_alt":"Würzen und einzeln verteilen","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Die ersten 20 Minuten backen","content":"Blech auf mittlerer Schiene einschieben und die Flügel 20 Minuten bei 220 °C backen. Währenddessen die Sauce in einem separaten sauberen Topf zubereiten.","image_alt":"Die ersten 20 Minuten backen","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Zutaten für die BBQ-Sauce mischen","content":"160 g Ketchup, 25 g braunen Zucker, 25 g Apfelessig, 10 g Worcestershiresauce, 8 g gehackten Knoblauch, 2 g mildes geräuchertes Paprikapulver und 40 g Wasser in einen Topf geben."},{"title":"Sauce köcheln lassen und teilen","content":"Umrühren und etwa 8 Minuten sanft köcheln lassen, bis die Sauce einen Löffel leicht überzieht. Die Hälfte in einer sauberen Schüssel zum Servieren aufbewahren; den Rest zum Bestreichen verwenden. Den Pinsel nicht in die Serviersauce tauchen.","image_alt":"Sauce köcheln lassen und teilen","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Wenden und weitere 15 Minuten backen","content":"Nach 20 Minuten die Flügel mit einer Zange wenden und weitere 15 Minuten bei 220 °C backen.","image_alt":"Wenden und weitere 15 Minuten backen","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Kerntemperatur prüfen","content":"Mehrere große Flügel an der dicksten Fleischstelle mit einem Küchenthermometer messen, ohne den Knochen zu berühren. Mindestens 74 °C sind nötig. Falls nicht erreicht, weiterbacken und vor dem Glasieren erneut prüfen."},{"title":"Mit Sauce bestreichen und 5 Minuten backen","content":"Sobald 74 °C erreicht sind, die Flügel mit der Glasursauce bestreichen. Weitere 5 Minuten bei 220 °C backen und darauf achten, dass der Zucker nicht verbrennt.","image_alt":"Mit Sauce bestreichen und 5 Minuten backen","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Flügel ruhen lassen","content":"Die dicksten Stücke nochmals prüfen, das Blech vorsichtig herausnehmen und die Flügel 5 Minuten ruhen lassen."},{"title":"Mit der reservierten Sauce servieren","content":"In vier Portionen teilen und mit der sauberen zurückbehaltenen Sauce servieren. Richtwert: 20 Minuten Vorbereitung, 40 Minuten im Ofen und 5 Minuten Ruhezeit; falls nötig länger garen."}],"new_steps":[{"title":"Den Backofen vorheizen","content":"Backofen mit Ober- und Unterhitze auf 220 °C vorheizen. Während der Vorbereitung etwa 15 Minuten aufheizen lassen.","image_url":"/recetas/alitas-bbq/paso-completo-01-20261103.webp","image_alt":"Den Backofen vorheizen"},{"title":"Flügel und Blech vorbereiten","content":"1000 g geteilte Flügel mit Haut und Knochen, ohne Spitzen, bereitstellen; falls nötig vorher im Kühlschrank auftauen. Rohes Hähnchen nicht waschen. Mit Einweg-Küchenpapier trocken tupfen, Hände waschen und ein Gitter in ein tiefes Blech zum Auffangen der Säfte setzen.","image_alt":"Flügel und Blech vorbereiten","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Würzen und einzeln verteilen","content":"Flügel mit 10 g Olivenöl, 3 g Salz und 1 g schwarzem Pfeffer vermischen. In einer Lage mit etwas Abstand auf dem Gitter verteilen. Die Sauce noch nicht dazugeben.","image_alt":"Würzen und einzeln verteilen","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Die ersten 20 Minuten backen","content":"Blech auf mittlerer Schiene einschieben und die Flügel 20 Minuten bei 220 °C backen. Währenddessen die Sauce in einem separaten sauberen Topf zubereiten.","image_alt":"Die ersten 20 Minuten backen","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Zutaten für die BBQ-Sauce mischen","content":"160 g Ketchup, 25 g braunen Zucker, 25 g Apfelessig, 10 g Worcestershiresauce, 8 g gehackten Knoblauch, 2 g mildes geräuchertes Paprikapulver und 40 g Wasser in einen Topf geben.","image_url":"/recetas/alitas-bbq/paso-completo-05-20261103.webp","image_alt":"Zutaten für die BBQ-Sauce mischen"},{"title":"Sauce köcheln lassen und teilen","content":"Umrühren und etwa 8 Minuten sanft köcheln lassen, bis die Sauce einen Löffel leicht überzieht. Die Hälfte in einer sauberen Schüssel zum Servieren aufbewahren; den Rest zum Bestreichen verwenden. Den Pinsel nicht in die Serviersauce tauchen.","image_alt":"Sauce köcheln lassen und teilen","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Wenden und weitere 15 Minuten backen","content":"Nach 20 Minuten die Flügel mit einer Zange wenden und weitere 15 Minuten bei 220 °C backen.","image_alt":"Wenden und weitere 15 Minuten backen","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Kerntemperatur prüfen","content":"Mehrere große Flügel an der dicksten Fleischstelle mit einem Küchenthermometer messen, ohne den Knochen zu berühren. Mindestens 74 °C sind nötig. Falls nicht erreicht, weiterbacken und vor dem Glasieren erneut prüfen.","image_url":"/recetas/alitas-bbq/paso-completo-08-20261103.webp","image_alt":"Kerntemperatur prüfen"},{"title":"Mit Sauce bestreichen und 5 Minuten backen","content":"Sobald 74 °C erreicht sind, die Flügel mit der Glasursauce bestreichen. Weitere 5 Minuten bei 220 °C backen und darauf achten, dass der Zucker nicht verbrennt.","image_alt":"Mit Sauce bestreichen und 5 Minuten backen","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Flügel ruhen lassen","content":"Die dicksten Stücke nochmals prüfen, das Blech vorsichtig herausnehmen und die Flügel 5 Minuten ruhen lassen.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Flügel ruhen lassen"},{"title":"Mit der reservierten Sauce servieren","content":"In vier Portionen teilen und mit der sauberen zurückbehaltenen Sauce servieren. Richtwert: 20 Minuten Vorbereitung, 40 Minuten im Ofen und 5 Minuten Ruhezeit; falls nötig länger garen.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Mit der reservierten Sauce servieren"}]},{"id":"dd546257-ea19-5bcc-b912-68c626c3d892","expected_steps":[{"title":"Preheat the oven","content":"Heat the oven to 220 °C using conventional top and bottom heat. Preheat for about 15 minutes while preparing the wings."},{"title":"Prepare the wings and tray","content":"Have 1000 g of split, skin-on, bone-in wings without tips ready; thaw in the refrigerator first if needed. Do not wash raw chicken. Pat dry with disposable paper towels, wash your hands and place a rack inside a deep baking tray to catch the juices.","image_alt":"Prepare the wings and tray","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Season and arrange in one layer","content":"Coat the wings with 10 g olive oil, 3 g salt and 1 g black pepper. Space them out on the rack in one layer. Do not add the sauce yet.","image_alt":"Season and arrange in one layer","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Bake for the first 20 minutes","content":"Put the tray on the middle oven shelf and bake for 20 minutes at 220 °C. Make the sauce in a separate clean saucepan while the wings cook.","image_alt":"Bake for the first 20 minutes","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Combine the BBQ sauce ingredients","content":"Add 160 g ketchup, 25 g brown sugar, 25 g cider vinegar, 10 g Worcestershire sauce, 8 g chopped garlic, 2 g sweet smoked paprika and 40 g water to the saucepan."},{"title":"Simmer the sauce and reserve half","content":"Stir and simmer gently for about 8 minutes until the sauce lightly coats a spoon. Set half aside in a clean bowl for serving and keep the rest for brushing the wings. Never dip the brush into the serving sauce.","image_alt":"Simmer the sauce and reserve half","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Turn and bake for 15 more minutes","content":"After the first 20 minutes, turn the wings with tongs and bake for a further 15 minutes at 220 °C.","image_alt":"Turn and bake for 15 more minutes","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Check the internal temperature","content":"Test several large wings with a food thermometer in the thickest meat, avoiding the bone. They must reach at least 74 °C. If not, cook for longer and check again before adding sauce."},{"title":"Brush with sauce and bake 5 minutes","content":"Once the wings have reached 74 °C, brush with the portion of sauce kept for glazing. Bake for another 5 minutes at 220 °C, watching that the sugar does not burn.","image_alt":"Brush with sauce and bake 5 minutes","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Rest the wings","content":"Check the thickest pieces again, carefully remove the tray and let the wings rest for 5 minutes."},{"title":"Serve with the reserved sauce","content":"Divide among four servings and serve with the clean sauce reserved earlier. Allow roughly 20 minutes of preparation, 40 minutes in the oven and 5 minutes to rest; add more cooking time if needed."}],"new_steps":[{"title":"Preheat the oven","content":"Heat the oven to 220 °C using conventional top and bottom heat. Preheat for about 15 minutes while preparing the wings.","image_url":"/recetas/alitas-bbq/paso-completo-01-20261103.webp","image_alt":"Preheat the oven"},{"title":"Prepare the wings and tray","content":"Have 1000 g of split, skin-on, bone-in wings without tips ready; thaw in the refrigerator first if needed. Do not wash raw chicken. Pat dry with disposable paper towels, wash your hands and place a rack inside a deep baking tray to catch the juices.","image_alt":"Prepare the wings and tray","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Season and arrange in one layer","content":"Coat the wings with 10 g olive oil, 3 g salt and 1 g black pepper. Space them out on the rack in one layer. Do not add the sauce yet.","image_alt":"Season and arrange in one layer","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Bake for the first 20 minutes","content":"Put the tray on the middle oven shelf and bake for 20 minutes at 220 °C. Make the sauce in a separate clean saucepan while the wings cook.","image_alt":"Bake for the first 20 minutes","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Combine the BBQ sauce ingredients","content":"Add 160 g ketchup, 25 g brown sugar, 25 g cider vinegar, 10 g Worcestershire sauce, 8 g chopped garlic, 2 g sweet smoked paprika and 40 g water to the saucepan.","image_url":"/recetas/alitas-bbq/paso-completo-05-20261103.webp","image_alt":"Combine the BBQ sauce ingredients"},{"title":"Simmer the sauce and reserve half","content":"Stir and simmer gently for about 8 minutes until the sauce lightly coats a spoon. Set half aside in a clean bowl for serving and keep the rest for brushing the wings. Never dip the brush into the serving sauce.","image_alt":"Simmer the sauce and reserve half","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Turn and bake for 15 more minutes","content":"After the first 20 minutes, turn the wings with tongs and bake for a further 15 minutes at 220 °C.","image_alt":"Turn and bake for 15 more minutes","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Check the internal temperature","content":"Test several large wings with a food thermometer in the thickest meat, avoiding the bone. They must reach at least 74 °C. If not, cook for longer and check again before adding sauce.","image_url":"/recetas/alitas-bbq/paso-completo-08-20261103.webp","image_alt":"Check the internal temperature"},{"title":"Brush with sauce and bake 5 minutes","content":"Once the wings have reached 74 °C, brush with the portion of sauce kept for glazing. Bake for another 5 minutes at 220 °C, watching that the sugar does not burn.","image_alt":"Brush with sauce and bake 5 minutes","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Rest the wings","content":"Check the thickest pieces again, carefully remove the tray and let the wings rest for 5 minutes.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Rest the wings"},{"title":"Serve with the reserved sauce","content":"Divide among four servings and serve with the clean sauce reserved earlier. Allow roughly 20 minutes of preparation, 40 minutes in the oven and 5 minutes to rest; add more cooking time if needed.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Serve with the reserved sauce"}]},{"id":"2d31cabb-b350-4c6f-a444-eec6b03c28eb","expected_steps":[{"title":"Precalienta el horno","content":"Enciende el horno a 220 °C con calor arriba y abajo. Déjalo precalentar unos 15 minutos mientras preparas las alitas."},{"title":"Prepara las alitas y la bandeja","content":"Ten listas 1000 g de alitas partidas, con piel y hueso, sin puntas y descongeladas si procede. No laves el pollo. Sécalo con papel desechable, lávate las manos y coloca una rejilla sobre una bandeja profunda para recoger los jugos.","image_alt":"Prepara las alitas y la bandeja","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Sazona y coloca en una sola capa","content":"Mezcla las alitas con 10 g de aceite de oliva, 3 g de sal y 1 g de pimienta negra. Distribúyelas sobre la rejilla sin amontonarlas. Todavía no añadas la salsa.","image_alt":"Sazona y coloca en una sola capa","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Hornea los primeros 20 minutos","content":"Introduce la bandeja a media altura y hornea las alitas durante 20 minutos a 220 °C. Mientras se hornean, prepara la salsa en un cazo limpio.","image_alt":"Hornea los primeros 20 minutos","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Mezcla los ingredientes de la salsa BBQ","content":"Pon en el cazo 160 g de kétchup, 25 g de azúcar moreno, 25 g de vinagre de sidra, 10 g de salsa Worcestershire, 8 g de ajo picado, 2 g de pimentón dulce ahumado y 40 g de agua."},{"title":"Cocina la salsa y reserva una parte","content":"Remueve y cocina la salsa a fuego suave unos 8 minutos, hasta que cubra ligeramente una cuchara. Reserva la mitad en un recipiente limpio para servir y deja la otra mitad para pincelar las alitas. No introduzcas el pincel en la salsa reservada.","image_alt":"Cocina la salsa y reserva una parte","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Dales la vuelta y hornea 15 minutos más","content":"Tras los primeros 20 minutos, gira las alitas con unas pinzas y hornéalas otros 15 minutos a 220 °C.","image_alt":"Dales la vuelta y hornea 15 minutos más","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Comprueba que estén bien cocinadas","content":"Mide varias alitas grandes con un termómetro de cocina en la parte más gruesa, sin tocar el hueso. Deben alcanzar al menos 74 °C. Si todavía no llegan, continúa horneando y vuelve a medir antes de añadir la salsa."},{"title":"Pincela y hornea los últimos 5 minutos","content":"Cuando las alitas hayan alcanzado 74 °C, pincélalas con la salsa destinada al glaseado. Hornea 5 minutos más a 220 °C, vigilando que el azúcar no se queme.","image_alt":"Pincela y hornea los últimos 5 minutos","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Déjalas reposar","content":"Comprueba de nuevo la temperatura en las piezas más gruesas, retira la bandeja con cuidado y deja reposar las alitas durante 5 minutos."},{"title":"Sirve con la salsa reservada","content":"Reparte las alitas en cuatro raciones y acompáñalas con la salsa limpia que apartaste antes. El tiempo orientativo es de 20 minutos de preparación, 40 de horno y 5 de reposo; si las alitas necesitan más cocción, añade ese tiempo."}],"new_steps":[{"title":"Precalienta el horno","content":"Enciende el horno a 220 °C con calor arriba y abajo. Déjalo precalentar unos 15 minutos mientras preparas las alitas.","image_url":"/recetas/alitas-bbq/paso-completo-01-20261103.webp","image_alt":"Precalienta el horno"},{"title":"Prepara las alitas y la bandeja","content":"Ten listas 1000 g de alitas partidas, con piel y hueso, sin puntas y descongeladas si procede. No laves el pollo. Sécalo con papel desechable, lávate las manos y coloca una rejilla sobre una bandeja profunda para recoger los jugos.","image_alt":"Prepara las alitas y la bandeja","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Sazona y coloca en una sola capa","content":"Mezcla las alitas con 10 g de aceite de oliva, 3 g de sal y 1 g de pimienta negra. Distribúyelas sobre la rejilla sin amontonarlas. Todavía no añadas la salsa.","image_alt":"Sazona y coloca en una sola capa","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Hornea los primeros 20 minutos","content":"Introduce la bandeja a media altura y hornea las alitas durante 20 minutos a 220 °C. Mientras se hornean, prepara la salsa en un cazo limpio.","image_alt":"Hornea los primeros 20 minutos","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Mezcla los ingredientes de la salsa BBQ","content":"Pon en el cazo 160 g de kétchup, 25 g de azúcar moreno, 25 g de vinagre de sidra, 10 g de salsa Worcestershire, 8 g de ajo picado, 2 g de pimentón dulce ahumado y 40 g de agua.","image_url":"/recetas/alitas-bbq/paso-completo-05-20261103.webp","image_alt":"Mezcla los ingredientes de la salsa BBQ"},{"title":"Cocina la salsa y reserva una parte","content":"Remueve y cocina la salsa a fuego suave unos 8 minutos, hasta que cubra ligeramente una cuchara. Reserva la mitad en un recipiente limpio para servir y deja la otra mitad para pincelar las alitas. No introduzcas el pincel en la salsa reservada.","image_alt":"Cocina la salsa y reserva una parte","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Dales la vuelta y hornea 15 minutos más","content":"Tras los primeros 20 minutos, gira las alitas con unas pinzas y hornéalas otros 15 minutos a 220 °C.","image_alt":"Dales la vuelta y hornea 15 minutos más","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Comprueba que estén bien cocinadas","content":"Mide varias alitas grandes con un termómetro de cocina en la parte más gruesa, sin tocar el hueso. Deben alcanzar al menos 74 °C. Si todavía no llegan, continúa horneando y vuelve a medir antes de añadir la salsa.","image_url":"/recetas/alitas-bbq/paso-completo-08-20261103.webp","image_alt":"Comprueba que estén bien cocinadas"},{"title":"Pincela y hornea los últimos 5 minutos","content":"Cuando las alitas hayan alcanzado 74 °C, pincélalas con la salsa destinada al glaseado. Hornea 5 minutos más a 220 °C, vigilando que el azúcar no se queme.","image_alt":"Pincela y hornea los últimos 5 minutos","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Déjalas reposar","content":"Comprueba de nuevo la temperatura en las piezas más gruesas, retira la bandeja con cuidado y deja reposar las alitas durante 5 minutos.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Déjalas reposar"},{"title":"Sirve con la salsa reservada","content":"Reparte las alitas en cuatro raciones y acompáñalas con la salsa limpia que apartaste antes. El tiempo orientativo es de 20 minutos de preparación, 40 de horno y 5 de reposo; si las alitas necesitan más cocción, añade ese tiempo.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Sirve con la salsa reservada"}]},{"id":"b931260b-d38f-5546-8faa-e003a0b6cd0a","expected_steps":[{"title":"Préchauffer le four","content":"Préchauffez le four à 220 °C, chaleur traditionnelle haut et bas, pendant environ 15 minutes tout en préparant les ailes."},{"title":"Préparer les ailes et la plaque","content":"Prévoyez 1000 g d'ailes séparées, avec peau et os, sans pointes ; décongelez-les au réfrigérateur si nécessaire. Ne lavez pas le poulet cru. Séchez-le avec du papier jetable, lavez-vous les mains et placez une grille dans une plaque profonde pour recueillir les jus.","image_alt":"Préparer les ailes et la plaque","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Assaisonner et espacer les ailes","content":"Mélangez les ailes avec 10 g d'huile d'olive, 3 g de sel et 1 g de poivre noir. Disposez-les en une seule couche sur la grille sans les entasser. N'ajoutez pas encore la sauce.","image_alt":"Assaisonner et espacer les ailes","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Cuire les 20 premières minutes","content":"Placez la plaque à mi-hauteur et enfournez 20 minutes à 220 °C. Préparez la sauce dans une casserole propre pendant ce temps.","image_alt":"Cuire les 20 premières minutes","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Mélanger les ingrédients de la sauce","content":"Versez dans la casserole 160 g de ketchup, 25 g de sucre brun, 25 g de vinaigre de cidre, 10 g de sauce Worcestershire, 8 g d'ail haché, 2 g de paprika doux fumé et 40 g d'eau."},{"title":"Laisser mijoter et réserver la moitié","content":"Remuez et laissez mijoter doucement environ 8 minutes, jusqu'à ce que la sauce nappe légèrement une cuillère. Réservez la moitié dans un récipient propre pour servir et gardez le reste pour badigeonner. Ne trempez pas le pinceau dans la sauce de service.","image_alt":"Laisser mijoter et réserver la moitié","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Retourner et cuire encore 15 minutes","content":"Après les 20 premières minutes, retournez les ailes avec une pince et enfournez encore 15 minutes à 220 °C.","image_alt":"Retourner et cuire encore 15 minutes","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Vérifier la température à cœur","content":"Mesurez plusieurs grosses ailes dans la chair la plus épaisse avec un thermomètre, sans toucher l'os. Il faut atteindre au moins 74 °C. Sinon, poursuivez la cuisson et contrôlez de nouveau avant de glacer."},{"title":"Badigeonner et cuire 5 minutes","content":"Après avoir atteint 74 °C, badigeonnez les ailes avec la sauce prévue pour le glaçage. Enfournez encore 5 minutes à 220 °C, en surveillant que le sucre ne brûle pas.","image_alt":"Badigeonner et cuire 5 minutes","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Laisser reposer","content":"Vérifiez de nouveau les morceaux les plus épais, retirez la plaque avec précaution et laissez reposer 5 minutes."},{"title":"Servir avec la sauce réservée","content":"Répartissez en quatre portions et servez avec la sauce propre mise de côté. Comptez environ 20 minutes de préparation, 40 minutes de four et 5 minutes de repos ; prolongez la cuisson si nécessaire."}],"new_steps":[{"title":"Préchauffer le four","content":"Préchauffez le four à 220 °C, chaleur traditionnelle haut et bas, pendant environ 15 minutes tout en préparant les ailes.","image_url":"/recetas/alitas-bbq/paso-completo-01-20261103.webp","image_alt":"Préchauffer le four"},{"title":"Préparer les ailes et la plaque","content":"Prévoyez 1000 g d'ailes séparées, avec peau et os, sans pointes ; décongelez-les au réfrigérateur si nécessaire. Ne lavez pas le poulet cru. Séchez-le avec du papier jetable, lavez-vous les mains et placez une grille dans une plaque profonde pour recueillir les jus.","image_alt":"Préparer les ailes et la plaque","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Assaisonner et espacer les ailes","content":"Mélangez les ailes avec 10 g d'huile d'olive, 3 g de sel et 1 g de poivre noir. Disposez-les en une seule couche sur la grille sans les entasser. N'ajoutez pas encore la sauce.","image_alt":"Assaisonner et espacer les ailes","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Cuire les 20 premières minutes","content":"Placez la plaque à mi-hauteur et enfournez 20 minutes à 220 °C. Préparez la sauce dans une casserole propre pendant ce temps.","image_alt":"Cuire les 20 premières minutes","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Mélanger les ingrédients de la sauce","content":"Versez dans la casserole 160 g de ketchup, 25 g de sucre brun, 25 g de vinaigre de cidre, 10 g de sauce Worcestershire, 8 g d'ail haché, 2 g de paprika doux fumé et 40 g d'eau.","image_url":"/recetas/alitas-bbq/paso-completo-05-20261103.webp","image_alt":"Mélanger les ingrédients de la sauce"},{"title":"Laisser mijoter et réserver la moitié","content":"Remuez et laissez mijoter doucement environ 8 minutes, jusqu'à ce que la sauce nappe légèrement une cuillère. Réservez la moitié dans un récipient propre pour servir et gardez le reste pour badigeonner. Ne trempez pas le pinceau dans la sauce de service.","image_alt":"Laisser mijoter et réserver la moitié","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Retourner et cuire encore 15 minutes","content":"Après les 20 premières minutes, retournez les ailes avec une pince et enfournez encore 15 minutes à 220 °C.","image_alt":"Retourner et cuire encore 15 minutes","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Vérifier la température à cœur","content":"Mesurez plusieurs grosses ailes dans la chair la plus épaisse avec un thermomètre, sans toucher l'os. Il faut atteindre au moins 74 °C. Sinon, poursuivez la cuisson et contrôlez de nouveau avant de glacer.","image_url":"/recetas/alitas-bbq/paso-completo-08-20261103.webp","image_alt":"Vérifier la température à cœur"},{"title":"Badigeonner et cuire 5 minutes","content":"Après avoir atteint 74 °C, badigeonnez les ailes avec la sauce prévue pour le glaçage. Enfournez encore 5 minutes à 220 °C, en surveillant que le sucre ne brûle pas.","image_alt":"Badigeonner et cuire 5 minutes","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Laisser reposer","content":"Vérifiez de nouveau les morceaux les plus épais, retirez la plaque avec précaution et laissez reposer 5 minutes.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Laisser reposer"},{"title":"Servir avec la sauce réservée","content":"Répartissez en quatre portions et servez avec la sauce propre mise de côté. Comptez environ 20 minutes de préparation, 40 minutes de four et 5 minutes de repos ; prolongez la cuisson si nécessaire.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Servir avec la sauce réservée"}]},{"id":"f50af27e-ecc8-5e7b-b10a-3bbaa9f8d4e8","expected_steps":[{"title":"Preriscalda il forno","content":"Porta il forno statico a 220 °C, con calore sopra e sotto. Lascialo preriscaldare per circa 15 minuti mentre prepari le ali."},{"title":"Prepara le ali e la teglia","content":"Prepara 1000 g di ali separate con pelle e ossa, senza punte, scongelate in frigorifero se necessario. Non lavare il pollo crudo. Tampona con carta usa e getta, lava le mani e sistema una griglia in una teglia profonda per raccogliere i succhi.","image_alt":"Prepara le ali e la teglia","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Condisci e disponi in un solo strato","content":"Mescola le ali con 10 g di olio d'oliva, 3 g di sale e 1 g di pepe nero. Disponile ben distanziate sulla griglia, senza sovrapporle. Non aggiungere ancora la salsa.","image_alt":"Condisci e disponi in un solo strato","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Cuoci i primi 20 minuti","content":"Metti la teglia al centro del forno e cuoci per 20 minuti a 220 °C. Nel frattempo prepara la salsa in un pentolino pulito.","image_alt":"Cuoci i primi 20 minuti","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Mescola gli ingredienti della salsa BBQ","content":"Versa nel pentolino 160 g di ketchup, 25 g di zucchero di canna, 25 g di aceto di mele, 10 g di salsa Worcestershire, 8 g di aglio tritato, 2 g di paprika dolce affumicata e 40 g di acqua."},{"title":"Fai sobbollire e conserva metà salsa","content":"Mescola e cuoci dolcemente per circa 8 minuti, finché la salsa vela il cucchiaio. Metti metà in una ciotola pulita per servire e tieni il resto per spennellare le ali. Non immergere il pennello nella salsa da portare in tavola.","image_alt":"Fai sobbollire e conserva metà salsa","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Gira e cuoci altri 15 minuti","content":"Dopo i primi 20 minuti gira le ali con le pinze e cuoci per altri 15 minuti a 220 °C.","image_alt":"Gira e cuoci altri 15 minuti","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Controlla la temperatura interna","content":"Misura alcune ali grandi con un termometro nella parte più spessa della carne, senza toccare l'osso. Devono raggiungere almeno 74 °C. Se non sono pronte, prosegui la cottura e controlla ancora prima di glassare."},{"title":"Spennella e cuoci per 5 minuti","content":"Quando le ali hanno raggiunto 74 °C, spennellale con la salsa destinata alla glassa. Rimetti in forno per 5 minuti a 220 °C, facendo attenzione a non bruciare lo zucchero.","image_alt":"Spennella e cuoci per 5 minuti","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Lascia riposare","content":"Controlla di nuovo i pezzi più spessi, estrai la teglia con cautela e lascia riposare le ali per 5 minuti."},{"title":"Servi con la salsa tenuta da parte","content":"Dividi in quattro porzioni e servi con la salsa pulita riservata. Calcola circa 20 minuti di preparazione, 40 di forno e 5 di riposo; allunga la cottura se necessario."}],"new_steps":[{"title":"Preriscalda il forno","content":"Porta il forno statico a 220 °C, con calore sopra e sotto. Lascialo preriscaldare per circa 15 minuti mentre prepari le ali.","image_url":"/recetas/alitas-bbq/paso-completo-01-20261103.webp","image_alt":"Preriscalda il forno"},{"title":"Prepara le ali e la teglia","content":"Prepara 1000 g di ali separate con pelle e ossa, senza punte, scongelate in frigorifero se necessario. Non lavare il pollo crudo. Tampona con carta usa e getta, lava le mani e sistema una griglia in una teglia profonda per raccogliere i succhi.","image_alt":"Prepara le ali e la teglia","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Condisci e disponi in un solo strato","content":"Mescola le ali con 10 g di olio d'oliva, 3 g di sale e 1 g di pepe nero. Disponile ben distanziate sulla griglia, senza sovrapporle. Non aggiungere ancora la salsa.","image_alt":"Condisci e disponi in un solo strato","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Cuoci i primi 20 minuti","content":"Metti la teglia al centro del forno e cuoci per 20 minuti a 220 °C. Nel frattempo prepara la salsa in un pentolino pulito.","image_alt":"Cuoci i primi 20 minuti","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Mescola gli ingredienti della salsa BBQ","content":"Versa nel pentolino 160 g di ketchup, 25 g di zucchero di canna, 25 g di aceto di mele, 10 g di salsa Worcestershire, 8 g di aglio tritato, 2 g di paprika dolce affumicata e 40 g di acqua.","image_url":"/recetas/alitas-bbq/paso-completo-05-20261103.webp","image_alt":"Mescola gli ingredienti della salsa BBQ"},{"title":"Fai sobbollire e conserva metà salsa","content":"Mescola e cuoci dolcemente per circa 8 minuti, finché la salsa vela il cucchiaio. Metti metà in una ciotola pulita per servire e tieni il resto per spennellare le ali. Non immergere il pennello nella salsa da portare in tavola.","image_alt":"Fai sobbollire e conserva metà salsa","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Gira e cuoci altri 15 minuti","content":"Dopo i primi 20 minuti gira le ali con le pinze e cuoci per altri 15 minuti a 220 °C.","image_alt":"Gira e cuoci altri 15 minuti","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Controlla la temperatura interna","content":"Misura alcune ali grandi con un termometro nella parte più spessa della carne, senza toccare l'osso. Devono raggiungere almeno 74 °C. Se non sono pronte, prosegui la cottura e controlla ancora prima di glassare.","image_url":"/recetas/alitas-bbq/paso-completo-08-20261103.webp","image_alt":"Controlla la temperatura interna"},{"title":"Spennella e cuoci per 5 minuti","content":"Quando le ali hanno raggiunto 74 °C, spennellale con la salsa destinata alla glassa. Rimetti in forno per 5 minuti a 220 °C, facendo attenzione a non bruciare lo zucchero.","image_alt":"Spennella e cuoci per 5 minuti","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Lascia riposare","content":"Controlla di nuovo i pezzi più spessi, estrai la teglia con cautela e lascia riposare le ali per 5 minuti.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Lascia riposare"},{"title":"Servi con la salsa tenuta da parte","content":"Dividi in quattro porzioni e servi con la salsa pulita riservata. Calcola circa 20 minuti di preparazione, 40 di forno e 5 di riposo; allunga la cottura se necessario.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Servi con la salsa tenuta da parte"}]},{"id":"b1c351fb-3b6e-5f35-b347-a010db304191","expected_steps":[{"title":"オーブンを予熱する","content":"オーブンを上下加熱の220 °Cに設定し、手羽を準備する間に約15分予熱します。"},{"title":"手羽と天板を準備する","content":"先端を除いた皮・骨付きの手羽1000 gを用意し、必要なら冷蔵庫で解凍します。生の鶏肉は洗わず、使い捨てペーパーで水気を押さえます。手を洗い、深い天板に網を載せて肉汁を受けます。","image_alt":"手羽と天板を準備する","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"下味を付けて並べる","content":"手羽にオリーブ油10 g、塩3 g、黒こしょう1 gをまぶします。網に重ならないよう間隔を空けて並べます。ソースはまだ塗りません。","image_alt":"下味を付けて並べる","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"最初の20分間焼く","content":"天板をオーブンの中段に入れ、220 °Cで20分焼きます。その間に清潔な小鍋でソースを作ります。","image_alt":"最初の20分間焼く","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"BBQソースの材料を合わせる","content":"小鍋にケチャップ160 g、ブラウンシュガー25 g、りんご酢25 g、ウスターシャーソース10 g、刻んだにんにく8 g、甘口スモークパプリカ2 g、水40 gを入れます。"},{"title":"ソースを煮て半量を取り分ける","content":"混ぜながら弱火で約8分煮て、スプーンに薄く絡む濃さにします。半量を清潔な器に取り分けて食卓用にし、残りを手羽に塗るために使います。刷毛を食卓用ソースに入れないでください。","image_alt":"ソースを煮て半量を取り分ける","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"裏返してさらに15分焼く","content":"最初の20分が終わったらトングで裏返し、220 °Cでさらに15分焼きます。","image_alt":"裏返してさらに15分焼く","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"中心温度を確認する","content":"大きな手羽の肉の厚い部分を食品用温度計で測ります。骨には触れず、74 °C以上になったことを確認します。足りなければ追加で焼き、ソースを塗る前にもう一度測ります。"},{"title":"ソースを塗って5分焼く","content":"中心が74 °C以上になったら、塗るために残したソースを薄く塗ります。220 °Cでさらに5分焼き、砂糖が焦げないよう注意します。","image_alt":"ソースを塗って5分焼く","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"5分休ませる","content":"厚い部分の温度を再確認し、天板を安全に取り出して手羽を5分休ませます。"},{"title":"取り分けたソースと盛り付ける","content":"手羽を4人分に分け、清潔に取り分けたソースを添えます。目安は準備20分、オーブン40分、休ませ5分です。焼き足す場合はその分時間を延ばしてください。"}],"new_steps":[{"title":"オーブンを予熱する","content":"オーブンを上下加熱の220 °Cに設定し、手羽を準備する間に約15分予熱します。","image_url":"/recetas/alitas-bbq/paso-completo-01-20261103.webp","image_alt":"オーブンを予熱する"},{"title":"手羽と天板を準備する","content":"先端を除いた皮・骨付きの手羽1000 gを用意し、必要なら冷蔵庫で解凍します。生の鶏肉は洗わず、使い捨てペーパーで水気を押さえます。手を洗い、深い天板に網を載せて肉汁を受けます。","image_alt":"手羽と天板を準備する","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"下味を付けて並べる","content":"手羽にオリーブ油10 g、塩3 g、黒こしょう1 gをまぶします。網に重ならないよう間隔を空けて並べます。ソースはまだ塗りません。","image_alt":"下味を付けて並べる","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"最初の20分間焼く","content":"天板をオーブンの中段に入れ、220 °Cで20分焼きます。その間に清潔な小鍋でソースを作ります。","image_alt":"最初の20分間焼く","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"BBQソースの材料を合わせる","content":"小鍋にケチャップ160 g、ブラウンシュガー25 g、りんご酢25 g、ウスターシャーソース10 g、刻んだにんにく8 g、甘口スモークパプリカ2 g、水40 gを入れます。","image_url":"/recetas/alitas-bbq/paso-completo-05-20261103.webp","image_alt":"BBQソースの材料を合わせる"},{"title":"ソースを煮て半量を取り分ける","content":"混ぜながら弱火で約8分煮て、スプーンに薄く絡む濃さにします。半量を清潔な器に取り分けて食卓用にし、残りを手羽に塗るために使います。刷毛を食卓用ソースに入れないでください。","image_alt":"ソースを煮て半量を取り分ける","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"裏返してさらに15分焼く","content":"最初の20分が終わったらトングで裏返し、220 °Cでさらに15分焼きます。","image_alt":"裏返してさらに15分焼く","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"中心温度を確認する","content":"大きな手羽の肉の厚い部分を食品用温度計で測ります。骨には触れず、74 °C以上になったことを確認します。足りなければ追加で焼き、ソースを塗る前にもう一度測ります。","image_url":"/recetas/alitas-bbq/paso-completo-08-20261103.webp","image_alt":"中心温度を確認する"},{"title":"ソースを塗って5分焼く","content":"中心が74 °C以上になったら、塗るために残したソースを薄く塗ります。220 °Cでさらに5分焼き、砂糖が焦げないよう注意します。","image_alt":"ソースを塗って5分焼く","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"5分休ませる","content":"厚い部分の温度を再確認し、天板を安全に取り出して手羽を5分休ませます。","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"5分休ませる"},{"title":"取り分けたソースと盛り付ける","content":"手羽を4人分に分け、清潔に取り分けたソースを添えます。目安は準備20分、オーブン40分、休ませ5分です。焼き足す場合はその分時間を延ばしてください。","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"取り分けたソースと盛り付ける"}]},{"id":"e7b57ca6-9698-5f80-8683-3128eeb3843c","expected_steps":[{"title":"Preaqueça o forno","content":"Preaqueça o forno a 220 °C, com calor superior e inferior, por cerca de 15 minutos enquanto prepara as asinhas."},{"title":"Prepare as asinhas e a assadeira","content":"Separe 1000 g de asinhas com pele e osso, sem pontas, descongeladas na geladeira se necessário. Não lave o frango cru. Seque com papel descartável, lave as mãos e coloque uma grade em uma assadeira funda para recolher os sucos.","image_alt":"Prepare as asinhas e a assadeira","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Tempere e distribua em uma camada","content":"Misture as asinhas com 10 g de azeite, 3 g de sal e 1 g de pimenta-do-reino. Distribua sobre a grade sem amontoar. Ainda não adicione o molho.","image_alt":"Tempere e distribua em uma camada","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Asse pelos primeiros 20 minutos","content":"Coloque a assadeira no meio do forno e asse por 20 minutos a 220 °C. Enquanto isso, prepare o molho em uma panela limpa.","image_alt":"Asse pelos primeiros 20 minutos","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Misture os ingredientes do molho BBQ","content":"Coloque na panela 160 g de ketchup, 25 g de açúcar mascavo, 25 g de vinagre de maçã, 10 g de molho Worcestershire, 8 g de alho picado, 2 g de páprica doce defumada e 40 g de água."},{"title":"Cozinhe o molho e reserve metade","content":"Mexa e cozinhe em fogo baixo por cerca de 8 minutos, até o molho cobrir levemente uma colher. Reserve metade em um recipiente limpo para servir e use o restante para pincelar. Não mergulhe o pincel no molho reservado.","image_alt":"Cozinhe o molho e reserve metade","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Vire e asse por mais 15 minutos","content":"Depois dos primeiros 20 minutos, vire as asinhas com uma pinça e asse por mais 15 minutos a 220 °C.","image_alt":"Vire e asse por mais 15 minutos","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Confira a temperatura interna","content":"Use um termômetro culinário nas partes mais grossas de algumas asinhas grandes, sem tocar o osso. Devem atingir pelo menos 74 °C. Se necessário, asse por mais tempo e confira antes de colocar o molho."},{"title":"Pincele e asse por mais 5 minutos","content":"Depois de atingir 74 °C, pincele as asinhas com o molho separado para a cobertura. Asse por mais 5 minutos a 220 °C, vigiando para o açúcar não queimar.","image_alt":"Pincele e asse por mais 5 minutos","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Deixe descansar","content":"Confira novamente as peças mais grossas, retire a assadeira com cuidado e deixe as asinhas descansarem por 5 minutos."},{"title":"Sirva com o molho reservado","content":"Divida em quatro porções e acompanhe com o molho limpo reservado. O tempo aproximado é de 20 minutos de preparo, 40 de forno e 5 de descanso; aumente a cocção se necessário."}],"new_steps":[{"title":"Preaqueça o forno","content":"Preaqueça o forno a 220 °C, com calor superior e inferior, por cerca de 15 minutos enquanto prepara as asinhas.","image_url":"/recetas/alitas-bbq/paso-completo-01-20261103.webp","image_alt":"Preaqueça o forno"},{"title":"Prepare as asinhas e a assadeira","content":"Separe 1000 g de asinhas com pele e osso, sem pontas, descongeladas na geladeira se necessário. Não lave o frango cru. Seque com papel descartável, lave as mãos e coloque uma grade em uma assadeira funda para recolher os sucos.","image_alt":"Prepare as asinhas e a assadeira","image_url":"/recetas/alitas-bbq/paso-01.webp"},{"title":"Tempere e distribua em uma camada","content":"Misture as asinhas com 10 g de azeite, 3 g de sal e 1 g de pimenta-do-reino. Distribua sobre a grade sem amontoar. Ainda não adicione o molho.","image_alt":"Tempere e distribua em uma camada","image_url":"/recetas/alitas-bbq/paso-02.webp"},{"title":"Asse pelos primeiros 20 minutos","content":"Coloque a assadeira no meio do forno e asse por 20 minutos a 220 °C. Enquanto isso, prepare o molho em uma panela limpa.","image_alt":"Asse pelos primeiros 20 minutos","image_url":"/recetas/alitas-bbq/paso-03.webp"},{"title":"Misture os ingredientes do molho BBQ","content":"Coloque na panela 160 g de ketchup, 25 g de açúcar mascavo, 25 g de vinagre de maçã, 10 g de molho Worcestershire, 8 g de alho picado, 2 g de páprica doce defumada e 40 g de água.","image_url":"/recetas/alitas-bbq/paso-completo-05-20261103.webp","image_alt":"Misture os ingredientes do molho BBQ"},{"title":"Cozinhe o molho e reserve metade","content":"Mexa e cozinhe em fogo baixo por cerca de 8 minutos, até o molho cobrir levemente uma colher. Reserve metade em um recipiente limpo para servir e use o restante para pincelar. Não mergulhe o pincel no molho reservado.","image_alt":"Cozinhe o molho e reserve metade","image_url":"/recetas/alitas-bbq/paso-04.webp"},{"title":"Vire e asse por mais 15 minutos","content":"Depois dos primeiros 20 minutos, vire as asinhas com uma pinça e asse por mais 15 minutos a 220 °C.","image_alt":"Vire e asse por mais 15 minutos","image_url":"/recetas/alitas-bbq/paso-05.webp"},{"title":"Confira a temperatura interna","content":"Use um termômetro culinário nas partes mais grossas de algumas asinhas grandes, sem tocar o osso. Devem atingir pelo menos 74 °C. Se necessário, asse por mais tempo e confira antes de colocar o molho.","image_url":"/recetas/alitas-bbq/paso-completo-08-20261103.webp","image_alt":"Confira a temperatura interna"},{"title":"Pincele e asse por mais 5 minutos","content":"Depois de atingir 74 °C, pincele as asinhas com o molho separado para a cobertura. Asse por mais 5 minutos a 220 °C, vigiando para o açúcar não queimar.","image_alt":"Pincele e asse por mais 5 minutos","image_url":"/recetas/alitas-bbq/paso-06.webp"},{"title":"Deixe descansar","content":"Confira novamente as peças mais grossas, retire a assadeira com cuidado e deixe as asinhas descansarem por 5 minutos.","image_url":"/recetas/alitas-bbq/paso-06.webp","image_alt":"Deixe descansar"},{"title":"Sirva com o molho reservado","content":"Divida em quatro porções e acompanhe com o molho limpo reservado. O tempo aproximado é de 20 minutos de preparo, 40 de forno e 5 de descanso; aumente a cocção se necessário.","image_url":"/recetas/alitas-bbq/portada.webp","image_alt":"Sirva com o molho reservado"}]},{"id":"aac51938-4685-401c-b9ca-19274ebaadc1","expected_steps":[{"title":"Zutaten abmessen","content":"Alle Mengen abmessen. Eine saubere Flasche mit Deckel und einen Messbecher bereitstellen.","image_alt":"Zutaten abmessen","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Aromaten hacken","content":"Zwiebel, Knoblauch und Ingwer fein hacken.","image_alt":"Aromaten hacken","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Flüssigkeiten mischen","content":"Essig, 100 ml Wasser und Sojasauce in einen 1-Liter-Edelstahltopf gießen.","image_alt":"Flüssigkeiten mischen","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Melasse und Tamarinde einrühren","content":"Melasse und Tamarindenpaste einrühren, bis sie sich verteilt haben.","image_alt":"Melasse und Tamarinde einrühren","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Aromaten und Gewürze zugeben","content":"Zwiebel, Knoblauch, Ingwer, Pfeffer, Nelken und Piment zugeben.","image_alt":"Aromaten und Gewürze zugeben","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Mischung erhitzen","content":"Bei mittlerer Hitze in etwa 5 Minuten sanft aufkochen."},{"title":"Sanft köcheln","content":"Die Hitze reduzieren und offen 20 Minuten mit kleinen Blasen köcheln lassen. Gelegentlich rühren; die Sauce bleibt dünnflüssig.","image_alt":"Sanft köcheln","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Sauce abseihen","content":"Die heiße Sauce durch ein feines Sieb in einen hitzefesten Messbecher gießen. Die festen Reste entsorgen.","image_alt":"Sauce abseihen","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Sauce abkühlen","content":"Etwa 30 Minuten abkühlen lassen. Insgesamt nicht länger als 2 Stunden ungekühlt stehen lassen."},{"title":"Menge prüfen","content":"Die abgeseihte Sauce ergibt ungefähr 300 ml. Bei zu starker Reduktion etwas frisch aufgekochtes Wasser bis 300 ml ergänzen."},{"title":"Kühl lagern","content":"In die saubere Flasche füllen, verschließen und kühlen. Saubere Utensilien verwenden und vor Gebrauch schütteln.","image_alt":"Kühl lagern","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}],"new_steps":[{"title":"Zutaten abmessen","content":"Alle Mengen abmessen. Eine saubere Flasche mit Deckel und einen Messbecher bereitstellen.","image_alt":"Zutaten abmessen","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Aromaten hacken","content":"Zwiebel, Knoblauch und Ingwer fein hacken.","image_alt":"Aromaten hacken","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Flüssigkeiten mischen","content":"Essig, 100 ml Wasser und Sojasauce in einen 1-Liter-Edelstahltopf gießen.","image_alt":"Flüssigkeiten mischen","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Melasse und Tamarinde einrühren","content":"Melasse und Tamarindenpaste einrühren, bis sie sich verteilt haben.","image_alt":"Melasse und Tamarinde einrühren","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Aromaten und Gewürze zugeben","content":"Zwiebel, Knoblauch, Ingwer, Pfeffer, Nelken und Piment zugeben.","image_alt":"Aromaten und Gewürze zugeben","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Mischung erhitzen","content":"Bei mittlerer Hitze in etwa 5 Minuten sanft aufkochen.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Mischung erhitzen"},{"title":"Sanft köcheln","content":"Die Hitze reduzieren und offen 20 Minuten mit kleinen Blasen köcheln lassen. Gelegentlich rühren; die Sauce bleibt dünnflüssig.","image_alt":"Sanft köcheln","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Sauce abseihen","content":"Die heiße Sauce durch ein feines Sieb in einen hitzefesten Messbecher gießen. Die festen Reste entsorgen.","image_alt":"Sauce abseihen","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Sauce abkühlen","content":"Etwa 30 Minuten abkühlen lassen. Insgesamt nicht länger als 2 Stunden ungekühlt stehen lassen.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-09-20261103.webp","image_alt":"Sauce abkühlen"},{"title":"Menge prüfen","content":"Die abgeseihte Sauce ergibt ungefähr 300 ml. Bei zu starker Reduktion etwas frisch aufgekochtes Wasser bis 300 ml ergänzen.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-10-20261103.webp","image_alt":"Menge prüfen"},{"title":"Kühl lagern","content":"In die saubere Flasche füllen, verschließen und kühlen. Saubere Utensilien verwenden und vor Gebrauch schütteln.","image_alt":"Kühl lagern","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}]},{"id":"eb81aef0-0b90-4c1b-ace6-316df3d565cb","expected_steps":[{"title":"Measure the ingredients","content":"Measure the listed quantities. Set out a clean capped bottle and a measuring jug.","image_alt":"Measure the ingredients","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Chop the aromatics","content":"Finely chop the onion, garlic and ginger.","image_alt":"Chop the aromatics","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Combine the liquids","content":"Pour the vinegar, 100 ml water and soy sauce into a 1-litre stainless-steel saucepan.","image_alt":"Combine the liquids","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Dissolve the molasses and tamarind","content":"Stir in the molasses and tamarind paste until dispersed.","image_alt":"Dissolve the molasses and tamarind","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Add aromatics and spices","content":"Add the onion, garlic, ginger, black pepper, cloves and allspice.","image_alt":"Add aromatics and spices","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Heat the mixture","content":"Bring to a gentle boil over medium heat, about 5 minutes."},{"title":"Simmer gently","content":"Reduce the heat and simmer uncovered for 20 minutes with small bubbles. Stir occasionally; the sauce should stay thin.","image_alt":"Simmer gently","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Strain the sauce","content":"Strain the hot sauce through a fine sieve into a heatproof jug. Discard the solids.","image_alt":"Strain the sauce","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Cool the sauce","content":"Let the strong heat dissipate for about 30 minutes. Do not leave unrefrigerated for more than 2 hours."},{"title":"Check the yield","content":"Measure the strained sauce: the approximate yield is 300 ml. If it reduced too far, add a little freshly boiled water to reach 300 ml."},{"title":"Refrigerate","content":"Transfer to the clean bottle, cap and refrigerate. Use clean utensils and shake before serving.","image_alt":"Refrigerate","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}],"new_steps":[{"title":"Measure the ingredients","content":"Measure the listed quantities. Set out a clean capped bottle and a measuring jug.","image_alt":"Measure the ingredients","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Chop the aromatics","content":"Finely chop the onion, garlic and ginger.","image_alt":"Chop the aromatics","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Combine the liquids","content":"Pour the vinegar, 100 ml water and soy sauce into a 1-litre stainless-steel saucepan.","image_alt":"Combine the liquids","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Dissolve the molasses and tamarind","content":"Stir in the molasses and tamarind paste until dispersed.","image_alt":"Dissolve the molasses and tamarind","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Add aromatics and spices","content":"Add the onion, garlic, ginger, black pepper, cloves and allspice.","image_alt":"Add aromatics and spices","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Heat the mixture","content":"Bring to a gentle boil over medium heat, about 5 minutes.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Heat the mixture"},{"title":"Simmer gently","content":"Reduce the heat and simmer uncovered for 20 minutes with small bubbles. Stir occasionally; the sauce should stay thin.","image_alt":"Simmer gently","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Strain the sauce","content":"Strain the hot sauce through a fine sieve into a heatproof jug. Discard the solids.","image_alt":"Strain the sauce","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Cool the sauce","content":"Let the strong heat dissipate for about 30 minutes. Do not leave unrefrigerated for more than 2 hours.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-09-20261103.webp","image_alt":"Cool the sauce"},{"title":"Check the yield","content":"Measure the strained sauce: the approximate yield is 300 ml. If it reduced too far, add a little freshly boiled water to reach 300 ml.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-10-20261103.webp","image_alt":"Check the yield"},{"title":"Refrigerate","content":"Transfer to the clean bottle, cap and refrigerate. Use clean utensils and shake before serving.","image_alt":"Refrigerate","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}]},{"id":"0355e565-2ff2-4b93-9451-b9d39e92426e","expected_steps":[{"title":"Mide los ingredientes","content":"Mide las cantidades indicadas. Reserva una botella limpia con tapa y una jarra graduada.","image_alt":"Mide los ingredientes","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Pica los aromáticos","content":"Pica finamente la cebolla, el ajo y el jengibre.","image_alt":"Pica los aromáticos","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Combina los líquidos","content":"Vierte el vinagre, los 100 ml de agua y la salsa de soja en un cazo de acero inoxidable de 1 litro.","image_alt":"Combina los líquidos","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Disuelve la melaza y el tamarindo","content":"Incorpora la melaza y la pasta de tamarindo; remueve hasta dispersarlas.","image_alt":"Disuelve la melaza y el tamarindo","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Añade los aromáticos y las especias","content":"Añade la cebolla, el ajo, el jengibre, la pimienta negra, los clavos y la pimienta de Jamaica.","image_alt":"Añade los aromáticos y las especias","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Calienta la mezcla","content":"Lleva la mezcla a un hervor suave a fuego medio, unos 5 minutos."},{"title":"Cocina a fuego suave","content":"Baja el fuego y cocina destapado durante 20 minutos, con burbujas pequeñas. Remueve de vez en cuando; debe quedar fluida.","image_alt":"Cocina a fuego suave","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Cuela la salsa","content":"Pasa la salsa caliente por un colador fino a una jarra resistente al calor. Desecha los sólidos.","image_alt":"Cuela la salsa","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Enfría la salsa","content":"Deja perder el calor intenso unos 30 minutos. No la mantengas fuera de la nevera más de 2 horas."},{"title":"Comprueba el rendimiento","content":"Mide la salsa colada: el rendimiento aproximado es de 300 ml. Si se redujo demasiado, añade un poco de agua recién hervida hasta alcanzar 300 ml."},{"title":"Guarda en nevera","content":"Pasa a la botella limpia, tapa y refrigera. Usa utensilios limpios y agita antes de servir.","image_alt":"Guarda en nevera","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}],"new_steps":[{"title":"Mide los ingredientes","content":"Mide las cantidades indicadas. Reserva una botella limpia con tapa y una jarra graduada.","image_alt":"Mide los ingredientes","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Pica los aromáticos","content":"Pica finamente la cebolla, el ajo y el jengibre.","image_alt":"Pica los aromáticos","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Combina los líquidos","content":"Vierte el vinagre, los 100 ml de agua y la salsa de soja en un cazo de acero inoxidable de 1 litro.","image_alt":"Combina los líquidos","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Disuelve la melaza y el tamarindo","content":"Incorpora la melaza y la pasta de tamarindo; remueve hasta dispersarlas.","image_alt":"Disuelve la melaza y el tamarindo","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Añade los aromáticos y las especias","content":"Añade la cebolla, el ajo, el jengibre, la pimienta negra, los clavos y la pimienta de Jamaica.","image_alt":"Añade los aromáticos y las especias","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Calienta la mezcla","content":"Lleva la mezcla a un hervor suave a fuego medio, unos 5 minutos.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Calienta la mezcla"},{"title":"Cocina a fuego suave","content":"Baja el fuego y cocina destapado durante 20 minutos, con burbujas pequeñas. Remueve de vez en cuando; debe quedar fluida.","image_alt":"Cocina a fuego suave","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Cuela la salsa","content":"Pasa la salsa caliente por un colador fino a una jarra resistente al calor. Desecha los sólidos.","image_alt":"Cuela la salsa","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Enfría la salsa","content":"Deja perder el calor intenso unos 30 minutos. No la mantengas fuera de la nevera más de 2 horas.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-09-20261103.webp","image_alt":"Enfría la salsa"},{"title":"Comprueba el rendimiento","content":"Mide la salsa colada: el rendimiento aproximado es de 300 ml. Si se redujo demasiado, añade un poco de agua recién hervida hasta alcanzar 300 ml.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-10-20261103.webp","image_alt":"Comprueba el rendimiento"},{"title":"Guarda en nevera","content":"Pasa a la botella limpia, tapa y refrigera. Usa utensilios limpios y agita antes de servir.","image_alt":"Guarda en nevera","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}]},{"id":"b5ab1e02-be3f-4406-843b-317257fcfedb","expected_steps":[{"title":"Mesurez les ingrédients","content":"Mesurez les quantités indiquées. Préparez une bouteille propre avec bouchon et un verre doseur.","image_alt":"Mesurez les ingrédients","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Hachez les aromates","content":"Hachez finement l’oignon, l’ail et le gingembre.","image_alt":"Hachez les aromates","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Mélangez les liquides","content":"Versez le vinaigre, les 100 ml d’eau et la sauce soja dans une casserole inox de 1 litre.","image_alt":"Mélangez les liquides","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Incorporez mélasse et tamarin","content":"Incorporez la mélasse et la pâte de tamarin en remuant pour les disperser.","image_alt":"Incorporez mélasse et tamarin","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Ajoutez aromates et épices","content":"Ajoutez oignon, ail, gingembre, poivre, girofle et piment de la Jamaïque.","image_alt":"Ajoutez aromates et épices","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Chauffez le mélange","content":"Portez à légère ébullition à feu moyen, environ 5 minutes."},{"title":"Laissez frémir","content":"Baissez le feu et laissez frémir à découvert 20 minutes. Remuez de temps en temps ; la sauce doit rester fluide.","image_alt":"Laissez frémir","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Filtrez la sauce","content":"Filtrez la sauce chaude au tamis fin dans un récipient résistant à la chaleur. Jetez les solides.","image_alt":"Filtrez la sauce","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Refroidissez la sauce","content":"Laissez perdre la forte chaleur environ 30 minutes. Ne laissez pas plus de 2 heures hors du réfrigérateur."},{"title":"Vérifiez le volume","content":"Le volume filtré est d’environ 300 ml. Si la sauce a trop réduit, complétez avec un peu d’eau fraîchement bouillie jusqu’à 300 ml."},{"title":"Conservez au réfrigérateur","content":"Versez dans la bouteille propre, fermez et réfrigérez. Utilisez des ustensiles propres et secouez avant usage.","image_alt":"Conservez au réfrigérateur","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}],"new_steps":[{"title":"Mesurez les ingrédients","content":"Mesurez les quantités indiquées. Préparez une bouteille propre avec bouchon et un verre doseur.","image_alt":"Mesurez les ingrédients","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Hachez les aromates","content":"Hachez finement l’oignon, l’ail et le gingembre.","image_alt":"Hachez les aromates","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Mélangez les liquides","content":"Versez le vinaigre, les 100 ml d’eau et la sauce soja dans une casserole inox de 1 litre.","image_alt":"Mélangez les liquides","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Incorporez mélasse et tamarin","content":"Incorporez la mélasse et la pâte de tamarin en remuant pour les disperser.","image_alt":"Incorporez mélasse et tamarin","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Ajoutez aromates et épices","content":"Ajoutez oignon, ail, gingembre, poivre, girofle et piment de la Jamaïque.","image_alt":"Ajoutez aromates et épices","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Chauffez le mélange","content":"Portez à légère ébullition à feu moyen, environ 5 minutes.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Chauffez le mélange"},{"title":"Laissez frémir","content":"Baissez le feu et laissez frémir à découvert 20 minutes. Remuez de temps en temps ; la sauce doit rester fluide.","image_alt":"Laissez frémir","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Filtrez la sauce","content":"Filtrez la sauce chaude au tamis fin dans un récipient résistant à la chaleur. Jetez les solides.","image_alt":"Filtrez la sauce","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Refroidissez la sauce","content":"Laissez perdre la forte chaleur environ 30 minutes. Ne laissez pas plus de 2 heures hors du réfrigérateur.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-09-20261103.webp","image_alt":"Refroidissez la sauce"},{"title":"Vérifiez le volume","content":"Le volume filtré est d’environ 300 ml. Si la sauce a trop réduit, complétez avec un peu d’eau fraîchement bouillie jusqu’à 300 ml.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-10-20261103.webp","image_alt":"Vérifiez le volume"},{"title":"Conservez au réfrigérateur","content":"Versez dans la bouteille propre, fermez et réfrigérez. Utilisez des ustensiles propres et secouez avant usage.","image_alt":"Conservez au réfrigérateur","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}]},{"id":"825d49a3-e35c-4ecd-9669-0c5dadbf256f","expected_steps":[{"title":"Misura gli ingredienti","content":"Misura le quantità indicate. Prepara una bottiglia pulita con tappo e una caraffa graduata.","image_alt":"Misura gli ingredienti","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Trita gli aromi","content":"Trita finemente cipolla, aglio e zenzero.","image_alt":"Trita gli aromi","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Unisci i liquidi","content":"Versa aceto, 100 ml di acqua e salsa di soia in un pentolino inox da 1 litro.","image_alt":"Unisci i liquidi","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Sciogli melassa e tamarindo","content":"Incorpora melassa e pasta di tamarindo mescolando per distribuirle.","image_alt":"Sciogli melassa e tamarindo","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Aggiungi aromi e spezie","content":"Aggiungi cipolla, aglio, zenzero, pepe, chiodi di garofano e pimento.","image_alt":"Aggiungi aromi e spezie","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Scalda il composto","content":"Porta a leggero bollore a fuoco medio, circa 5 minuti."},{"title":"Fai sobbollire","content":"Abbassa il fuoco e fai sobbollire scoperto per 20 minuti. Mescola ogni tanto; la salsa deve restare fluida.","image_alt":"Fai sobbollire","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Filtra la salsa","content":"Filtra la salsa calda con un colino fine in una caraffa resistente al calore. Elimina i solidi.","image_alt":"Filtra la salsa","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Raffredda la salsa","content":"Lascia perdere il calore intenso per circa 30 minuti. Non lasciare fuori dal frigorifero per oltre 2 ore."},{"title":"Controlla la resa","content":"La resa filtrata è di circa 300 ml. Se è diminuita troppo, aggiungi poca acqua appena bollita fino a 300 ml."},{"title":"Conserva in frigorifero","content":"Trasferisci nella bottiglia pulita, chiudi e metti in frigorifero. Usa utensili puliti e agita prima di servire.","image_alt":"Conserva in frigorifero","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}],"new_steps":[{"title":"Misura gli ingredienti","content":"Misura le quantità indicate. Prepara una bottiglia pulita con tappo e una caraffa graduata.","image_alt":"Misura gli ingredienti","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Trita gli aromi","content":"Trita finemente cipolla, aglio e zenzero.","image_alt":"Trita gli aromi","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Unisci i liquidi","content":"Versa aceto, 100 ml di acqua e salsa di soia in un pentolino inox da 1 litro.","image_alt":"Unisci i liquidi","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Sciogli melassa e tamarindo","content":"Incorpora melassa e pasta di tamarindo mescolando per distribuirle.","image_alt":"Sciogli melassa e tamarindo","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Aggiungi aromi e spezie","content":"Aggiungi cipolla, aglio, zenzero, pepe, chiodi di garofano e pimento.","image_alt":"Aggiungi aromi e spezie","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Scalda il composto","content":"Porta a leggero bollore a fuoco medio, circa 5 minuti.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Scalda il composto"},{"title":"Fai sobbollire","content":"Abbassa il fuoco e fai sobbollire scoperto per 20 minuti. Mescola ogni tanto; la salsa deve restare fluida.","image_alt":"Fai sobbollire","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Filtra la salsa","content":"Filtra la salsa calda con un colino fine in una caraffa resistente al calore. Elimina i solidi.","image_alt":"Filtra la salsa","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Raffredda la salsa","content":"Lascia perdere il calore intenso per circa 30 minuti. Non lasciare fuori dal frigorifero per oltre 2 ore.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-09-20261103.webp","image_alt":"Raffredda la salsa"},{"title":"Controlla la resa","content":"La resa filtrata è di circa 300 ml. Se è diminuita troppo, aggiungi poca acqua appena bollita fino a 300 ml.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-10-20261103.webp","image_alt":"Controlla la resa"},{"title":"Conserva in frigorifero","content":"Trasferisci nella bottiglia pulita, chiudi e metti in frigorifero. Usa utensili puliti e agita prima di servire.","image_alt":"Conserva in frigorifero","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}]},{"id":"8fa038b0-04fc-466a-a1f6-62140be1aabc","expected_steps":[{"title":"材料を量る","content":"分量を量ります。ふた付きの清潔な瓶と計量カップを用意します。","image_alt":"材料を量る","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"香味野菜を刻む","content":"玉ねぎ、にんにく、しょうがを細かく刻みます。","image_alt":"香味野菜を刻む","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"液体を合わせる","content":"容量1リットルのステンレス小鍋に酢、水100 ml、しょうゆを入れます。","image_alt":"液体を合わせる","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"糖蜜とタマリンドを混ぜる","content":"糖蜜とタマリンドペーストを加え、全体に行き渡るまで混ぜます。","image_alt":"糖蜜とタマリンドを混ぜる","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"香味野菜とスパイスを加える","content":"玉ねぎ、にんにく、しょうが、黒こしょう、クローブ、オールスパイスを加えます。","image_alt":"香味野菜とスパイスを加える","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"温める","content":"中火で約5分、穏やかに沸くまで温めます。"},{"title":"弱火で煮る","content":"弱火にしてふたをせず20分煮ます。時々混ぜ、小さな泡が立つ程度を保ちます。さらりと仕上げます。","image_alt":"弱火で煮る","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"ソースをこす","content":"熱いうちに細かいざるで耐熱容器へこします。残った固形物は捨てます。","image_alt":"ソースをこす","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"粗熱を取る","content":"約30分置いて強い熱を取ります。冷蔵庫の外に2時間以上放置しないでください。"},{"title":"出来上がり量を確認する","content":"出来上がりは約300 mlです。煮詰まりすぎた場合は、沸かしたばかりの湯を少量加えて300 mlにします。"},{"title":"冷蔵する","content":"清潔な瓶に移し、ふたをして冷蔵します。清潔な器具を使い、使用前によく振ります。","image_alt":"冷蔵する","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}],"new_steps":[{"title":"材料を量る","content":"分量を量ります。ふた付きの清潔な瓶と計量カップを用意します。","image_alt":"材料を量る","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"香味野菜を刻む","content":"玉ねぎ、にんにく、しょうがを細かく刻みます。","image_alt":"香味野菜を刻む","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"液体を合わせる","content":"容量1リットルのステンレス小鍋に酢、水100 ml、しょうゆを入れます。","image_alt":"液体を合わせる","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"糖蜜とタマリンドを混ぜる","content":"糖蜜とタマリンドペーストを加え、全体に行き渡るまで混ぜます。","image_alt":"糖蜜とタマリンドを混ぜる","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"香味野菜とスパイスを加える","content":"玉ねぎ、にんにく、しょうが、黒こしょう、クローブ、オールスパイスを加えます。","image_alt":"香味野菜とスパイスを加える","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"温める","content":"中火で約5分、穏やかに沸くまで温めます。","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"温める"},{"title":"弱火で煮る","content":"弱火にしてふたをせず20分煮ます。時々混ぜ、小さな泡が立つ程度を保ちます。さらりと仕上げます。","image_alt":"弱火で煮る","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"ソースをこす","content":"熱いうちに細かいざるで耐熱容器へこします。残った固形物は捨てます。","image_alt":"ソースをこす","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"粗熱を取る","content":"約30分置いて強い熱を取ります。冷蔵庫の外に2時間以上放置しないでください。","image_url":"/recetas/salsa-inglesa-casera/paso-completo-09-20261103.webp","image_alt":"粗熱を取る"},{"title":"出来上がり量を確認する","content":"出来上がりは約300 mlです。煮詰まりすぎた場合は、沸かしたばかりの湯を少量加えて300 mlにします。","image_url":"/recetas/salsa-inglesa-casera/paso-completo-10-20261103.webp","image_alt":"出来上がり量を確認する"},{"title":"冷蔵する","content":"清潔な瓶に移し、ふたをして冷蔵します。清潔な器具を使い、使用前によく振ります。","image_alt":"冷蔵する","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}]},{"id":"c3abcaf9-9a9e-4a62-8845-34b16b8378f9","expected_steps":[{"title":"Meça os ingredientes","content":"Meça as quantidades indicadas. Separe uma garrafa limpa com tampa e uma jarra graduada.","image_alt":"Meça os ingredientes","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Pique os aromáticos","content":"Pique bem a cebola, o alho e o gengibre.","image_alt":"Pique os aromáticos","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Misture os líquidos","content":"Coloque vinagre, 100 ml de água e shoyu numa panela inox de 1 litro.","image_alt":"Misture os líquidos","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Dissolva o melaço e o tamarindo","content":"Adicione melaço e pasta de tamarindo, mexendo para dispersar.","image_alt":"Dissolva o melaço e o tamarindo","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Adicione aromáticos e especiarias","content":"Junte cebola, alho, gengibre, pimenta-do-reino, cravo e pimenta-da-jamaica.","image_alt":"Adicione aromáticos e especiarias","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Aqueça a mistura","content":"Leve à fervura suave em fogo médio, cerca de 5 minutos."},{"title":"Cozinhe em fogo baixo","content":"Baixe o fogo e cozinhe destampado por 20 minutos, com bolhas pequenas. Mexa de vez em quando; o molho deve ficar fluido.","image_alt":"Cozinhe em fogo baixo","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Coe o molho","content":"Coe o molho quente em peneira fina para uma jarra resistente ao calor. Descarte os sólidos.","image_alt":"Coe o molho","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Esfrie o molho","content":"Deixe perder o calor intenso por cerca de 30 minutos. Não mantenha fora da geladeira por mais de 2 horas."},{"title":"Confira o rendimento","content":"O rendimento coado é de aproximadamente 300 ml. Se reduzir demais, complete com pouca água recém-fervida até 300 ml."},{"title":"Guarde na geladeira","content":"Transfira para a garrafa limpa, tampe e refrigere. Use utensílios limpos e agite antes de servir.","image_alt":"Guarde na geladeira","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}],"new_steps":[{"title":"Meça os ingredientes","content":"Meça as quantidades indicadas. Separe uma garrafa limpa com tampa e uma jarra graduada.","image_alt":"Meça os ingredientes","image_url":"/recetas/salsa-inglesa-casera/paso-01.webp"},{"title":"Pique os aromáticos","content":"Pique bem a cebola, o alho e o gengibre.","image_alt":"Pique os aromáticos","image_url":"/recetas/salsa-inglesa-casera/paso-02.webp"},{"title":"Misture os líquidos","content":"Coloque vinagre, 100 ml de água e shoyu numa panela inox de 1 litro.","image_alt":"Misture os líquidos","image_url":"/recetas/salsa-inglesa-casera/paso-03.webp"},{"title":"Dissolva o melaço e o tamarindo","content":"Adicione melaço e pasta de tamarindo, mexendo para dispersar.","image_alt":"Dissolva o melaço e o tamarindo","image_url":"/recetas/salsa-inglesa-casera/paso-04.webp"},{"title":"Adicione aromáticos e especiarias","content":"Junte cebola, alho, gengibre, pimenta-do-reino, cravo e pimenta-da-jamaica.","image_alt":"Adicione aromáticos e especiarias","image_url":"/recetas/salsa-inglesa-casera/paso-05.webp"},{"title":"Aqueça a mistura","content":"Leve à fervura suave em fogo médio, cerca de 5 minutos.","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp","image_alt":"Aqueça a mistura"},{"title":"Cozinhe em fogo baixo","content":"Baixe o fogo e cozinhe destampado por 20 minutos, com bolhas pequenas. Mexa de vez em quando; o molho deve ficar fluido.","image_alt":"Cozinhe em fogo baixo","image_url":"/recetas/salsa-inglesa-casera/paso-06.webp"},{"title":"Coe o molho","content":"Coe o molho quente em peneira fina para uma jarra resistente ao calor. Descarte os sólidos.","image_alt":"Coe o molho","image_url":"/recetas/salsa-inglesa-casera/paso-07.webp"},{"title":"Esfrie o molho","content":"Deixe perder o calor intenso por cerca de 30 minutos. Não mantenha fora da geladeira por mais de 2 horas.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-09-20261103.webp","image_alt":"Esfrie o molho"},{"title":"Confira o rendimento","content":"O rendimento coado é de aproximadamente 300 ml. Se reduzir demais, complete com pouca água recém-fervida até 300 ml.","image_url":"/recetas/salsa-inglesa-casera/paso-completo-10-20261103.webp","image_alt":"Confira o rendimento"},{"title":"Guarde na geladeira","content":"Transfira para a garrafa limpa, tampe e refrigere. Use utensílios limpos e agite antes de servir.","image_alt":"Guarde na geladeira","image_url":"/recetas/salsa-inglesa-casera/portada.webp"}]},{"id":"a78305b1-6a52-424a-a894-df2dad874353","expected_steps":[{"title":"Gemüse schneiden","content":"Zwiebel, Paprika, Knoblauch und Tomaten fein schneiden.","image_alt":"Gemüse schneiden","image_url":"/recetas/casuela-de-mariscos/paso-01.webp"},{"title":"Aromaten anschwitzen","content":"Zwiebel, Paprika und Knoblauch im Öl bei mittlerer Hitze 5 Minuten garen.","image_alt":"Aromaten anschwitzen","image_url":"/recetas/casuela-de-mariscos/paso-02.webp"},{"title":"Tomaten zugeben","content":"Die Tomaten in den Topf geben."},{"title":"Tomaten garen","content":"6 Minuten weich garen.","image_alt":"Tomaten garen","image_url":"/recetas/casuela-de-mariscos/paso-03.webp"},{"title":"Flüssigkeit zugeben","content":"Wasser, Kokosmilch und Salz zugeben."},{"title":"Brühe köcheln","content":"5 Minuten sanft köcheln lassen.","image_alt":"Brühe köcheln","image_url":"/recetas/casuela-de-mariscos/paso-04.webp"},{"title":"Tintenfisch zugeben","content":"Den Tintenfisch in die Brühe geben."},{"title":"Tintenfisch garen","content":"15 Minuten sanft köcheln; falls er noch fest ist, länger garen.","image_alt":"Tintenfisch garen","image_url":"/recetas/casuela-de-mariscos/paso-05.webp"},{"title":"Fisch zugeben","content":"Die Fischwürfel zugeben."},{"title":"Fisch garen","content":"5 Minuten sanft garen.","image_alt":"Fisch garen","image_url":"/recetas/casuela-de-mariscos/paso-06.webp"},{"title":"Garnelen zugeben","content":"Die Garnelen in den Topf geben."},{"title":"Garnelen garen","content":"3–4 Minuten garen, bis sie rosa und undurchsichtig sind.","image_alt":"Garnelen garen","image_url":"/recetas/casuela-de-mariscos/paso-07.webp"},{"title":"Garzustand prüfen","content":"Prüfen, ob der Fisch gar und der Tintenfisch zart ist."},{"title":"Eintopf servieren","content":"Den Eintopf heiß mit Koriander, weißem Reis und Patacón nach Wunsch servieren.","image_alt":"Eintopf servieren","image_url":"/recetas/casuela-de-mariscos/paso-08.webp"}],"new_steps":[{"title":"Gemüse schneiden","content":"Zwiebel, Paprika, Knoblauch und Tomaten fein schneiden.","image_alt":"Gemüse schneiden","image_url":"/recetas/casuela-de-mariscos/paso-01.webp"},{"title":"Aromaten anschwitzen","content":"Zwiebel, Paprika und Knoblauch im Öl bei mittlerer Hitze 5 Minuten garen.","image_alt":"Aromaten anschwitzen","image_url":"/recetas/casuela-de-mariscos/paso-02.webp"},{"title":"Tomaten zugeben","content":"Die Tomaten in den Topf geben.","image_url":"/recetas/casuela-de-mariscos/paso-completo-03-20261103.webp","image_alt":"Tomaten zugeben"},{"title":"Tomaten garen","content":"6 Minuten weich garen.","image_alt":"Tomaten garen","image_url":"/recetas/casuela-de-mariscos/paso-03.webp"},{"title":"Flüssigkeit zugeben","content":"Wasser, Kokosmilch und Salz zugeben.","image_url":"/recetas/casuela-de-mariscos/paso-completo-05-20261103.webp","image_alt":"Flüssigkeit zugeben"},{"title":"Brühe köcheln","content":"5 Minuten sanft köcheln lassen.","image_alt":"Brühe köcheln","image_url":"/recetas/casuela-de-mariscos/paso-04.webp"},{"title":"Tintenfisch zugeben","content":"Den Tintenfisch in die Brühe geben.","image_url":"/recetas/casuela-de-mariscos/paso-completo-07-20261103.webp","image_alt":"Tintenfisch zugeben"},{"title":"Tintenfisch garen","content":"15 Minuten sanft köcheln; falls er noch fest ist, länger garen.","image_alt":"Tintenfisch garen","image_url":"/recetas/casuela-de-mariscos/paso-05.webp"},{"title":"Fisch zugeben","content":"Die Fischwürfel zugeben.","image_url":"/recetas/casuela-de-mariscos/paso-completo-09-20261103.webp","image_alt":"Fisch zugeben"},{"title":"Fisch garen","content":"5 Minuten sanft garen.","image_alt":"Fisch garen","image_url":"/recetas/casuela-de-mariscos/paso-06.webp"},{"title":"Garnelen zugeben","content":"Die Garnelen in den Topf geben.","image_url":"/recetas/casuela-de-mariscos/paso-completo-11-20261103.webp","image_alt":"Garnelen zugeben"},{"title":"Garnelen garen","content":"3–4 Minuten garen, bis sie rosa und undurchsichtig sind.","image_alt":"Garnelen garen","image_url":"/recetas/casuela-de-mariscos/paso-07.webp"},{"title":"Garzustand prüfen","content":"Prüfen, ob der Fisch gar und der Tintenfisch zart ist.","image_url":"/recetas/casuela-de-mariscos/paso-completo-13-20261103.webp","image_alt":"Garzustand prüfen"},{"title":"Eintopf servieren","content":"Den Eintopf heiß mit Koriander, weißem Reis und Patacón nach Wunsch servieren.","image_alt":"Eintopf servieren","image_url":"/recetas/casuela-de-mariscos/paso-08.webp"}]},{"id":"1a5964c2-8859-4770-9977-dbfdb5e687fe","expected_steps":[{"title":"Chop the vegetables","content":"Finely chop the onion, pepper, garlic and tomatoes.","image_alt":"Chop the vegetables","image_url":"/recetas/casuela-de-mariscos/paso-01.webp"},{"title":"Sauté the aromatics","content":"Cook the onion, pepper and garlic in oil over medium heat for 5 minutes.","image_alt":"Sauté the aromatics","image_url":"/recetas/casuela-de-mariscos/paso-02.webp"},{"title":"Add the tomato","content":"Add the tomato to the pot."},{"title":"Cook the tomato","content":"Cook for 6 minutes until soft.","image_alt":"Cook the tomato","image_url":"/recetas/casuela-de-mariscos/paso-03.webp"},{"title":"Add the liquids","content":"Add the water, coconut milk and salt."},{"title":"Simmer the broth","content":"Simmer gently for 5 minutes.","image_alt":"Simmer the broth","image_url":"/recetas/casuela-de-mariscos/paso-04.webp"},{"title":"Add the squid","content":"Add the squid to the broth."},{"title":"Cook the squid","content":"Simmer gently for 15 minutes, extending the time if it is still firm.","image_alt":"Cook the squid","image_url":"/recetas/casuela-de-mariscos/paso-05.webp"},{"title":"Add the fish","content":"Add the fish cubes."},{"title":"Cook the fish","content":"Simmer gently for 5 minutes.","image_alt":"Cook the fish","image_url":"/recetas/casuela-de-mariscos/paso-06.webp"},{"title":"Add the shrimp","content":"Add the shrimp to the pot."},{"title":"Cook the shrimp","content":"Cook for 3–4 minutes until pink and opaque.","image_alt":"Cook the shrimp","image_url":"/recetas/casuela-de-mariscos/paso-07.webp"},{"title":"Check doneness","content":"Check that the fish is cooked and the squid tender."},{"title":"Serve the stew","content":"Serve the stew hot with cilantro, white rice and patacón to taste.","image_alt":"Serve the stew","image_url":"/recetas/casuela-de-mariscos/paso-08.webp"}],"new_steps":[{"title":"Chop the vegetables","content":"Finely chop the onion, pepper, garlic and tomatoes.","image_alt":"Chop the vegetables","image_url":"/recetas/casuela-de-mariscos/paso-01.webp"},{"title":"Sauté the aromatics","content":"Cook the onion, pepper and garlic in oil over medium heat for 5 minutes.","image_alt":"Sauté the aromatics","image_url":"/recetas/casuela-de-mariscos/paso-02.webp"},{"title":"Add the tomato","content":"Add the tomato to the pot.","image_url":"/recetas/casuela-de-mariscos/paso-completo-03-20261103.webp","image_alt":"Add the tomato"},{"title":"Cook the tomato","content":"Cook for 6 minutes until soft.","image_alt":"Cook the tomato","image_url":"/recetas/casuela-de-mariscos/paso-03.webp"},{"title":"Add the liquids","content":"Add the water, coconut milk and salt.","image_url":"/recetas/casuela-de-mariscos/paso-completo-05-20261103.webp","image_alt":"Add the liquids"},{"title":"Simmer the broth","content":"Simmer gently for 5 minutes.","image_alt":"Simmer the broth","image_url":"/recetas/casuela-de-mariscos/paso-04.webp"},{"title":"Add the squid","content":"Add the squid to the broth.","image_url":"/recetas/casuela-de-mariscos/paso-completo-07-20261103.webp","image_alt":"Add the squid"},{"title":"Cook the squid","content":"Simmer gently for 15 minutes, extending the time if it is still firm.","image_alt":"Cook the squid","image_url":"/recetas/casuela-de-mariscos/paso-05.webp"},{"title":"Add the fish","content":"Add the fish cubes.","image_url":"/recetas/casuela-de-mariscos/paso-completo-09-20261103.webp","image_alt":"Add the fish"},{"title":"Cook the fish","content":"Simmer gently for 5 minutes.","image_alt":"Cook the fish","image_url":"/recetas/casuela-de-mariscos/paso-06.webp"},{"title":"Add the shrimp","content":"Add the shrimp to the pot.","image_url":"/recetas/casuela-de-mariscos/paso-completo-11-20261103.webp","image_alt":"Add the shrimp"},{"title":"Cook the shrimp","content":"Cook for 3–4 minutes until pink and opaque.","image_alt":"Cook the shrimp","image_url":"/recetas/casuela-de-mariscos/paso-07.webp"},{"title":"Check doneness","content":"Check that the fish is cooked and the squid tender.","image_url":"/recetas/casuela-de-mariscos/paso-completo-13-20261103.webp","image_alt":"Check doneness"},{"title":"Serve the stew","content":"Serve the stew hot with cilantro, white rice and patacón to taste.","image_alt":"Serve the stew","image_url":"/recetas/casuela-de-mariscos/paso-08.webp"}]},{"id":"6c9d337b-6e50-4b4e-a4f6-eb8bacfd6f9a","expected_steps":[{"title":"Pica los vegetales","content":"Pica finamente la cebolla, el pimentón, el ajo y los tomates.","image_alt":"Pica los vegetales","image_url":"/recetas/casuela-de-mariscos/paso-01.webp"},{"title":"Sofríe los aromáticos","content":"Cocina la cebolla, el pimentón y el ajo con el aceite en una olla a fuego medio durante 5 minutos.","image_alt":"Sofríe los aromáticos","image_url":"/recetas/casuela-de-mariscos/paso-02.webp"},{"title":"Añade el tomate","content":"Agrega el tomate a la olla."},{"title":"Cocina el tomate","content":"Cocínalo durante 6 minutos, hasta que esté suave.","image_alt":"Cocina el tomate","image_url":"/recetas/casuela-de-mariscos/paso-03.webp"},{"title":"Añade los líquidos","content":"Añade el agua, la leche de coco y la sal."},{"title":"Cocina el caldo","content":"Cocina a fuego suave durante 5 minutos.","image_alt":"Cocina el caldo","image_url":"/recetas/casuela-de-mariscos/paso-04.webp"},{"title":"Añade el calamar","content":"Incorpora el calamar al caldo."},{"title":"Cocina el calamar","content":"Mantén un hervor suave durante 15 minutos; prolonga la cocción si aún está firme.","image_alt":"Cocina el calamar","image_url":"/recetas/casuela-de-mariscos/paso-05.webp"},{"title":"Añade el pescado","content":"Incorpora el pescado en cubos."},{"title":"Cocina el pescado","content":"Cocina suavemente durante 5 minutos.","image_alt":"Cocina el pescado","image_url":"/recetas/casuela-de-mariscos/paso-06.webp"},{"title":"Añade los camarones","content":"Incorpora los camarones a la olla."},{"title":"Cocina los camarones","content":"Cocina durante 3–4 minutos, hasta que estén rosados y opacos.","image_alt":"Cocina los camarones","image_url":"/recetas/casuela-de-mariscos/paso-07.webp"},{"title":"Comprueba la cocción","content":"Comprueba que el pescado esté cocido y el calamar tierno."},{"title":"Sirve la cazuela","content":"Sirve la cazuela caliente con cilantro, arroz blanco y patacón al gusto.","image_alt":"Sirve la cazuela","image_url":"/recetas/casuela-de-mariscos/paso-08.webp"}],"new_steps":[{"title":"Pica los vegetales","content":"Pica finamente la cebolla, el pimentón, el ajo y los tomates.","image_alt":"Pica los vegetales","image_url":"/recetas/casuela-de-mariscos/paso-01.webp"},{"title":"Sofríe los aromáticos","content":"Cocina la cebolla, el pimentón y el ajo con el aceite en una olla a fuego medio durante 5 minutos.","image_alt":"Sofríe los aromáticos","image_url":"/recetas/casuela-de-mariscos/paso-02.webp"},{"title":"Añade el tomate","content":"Agrega el tomate a la olla.","image_url":"/recetas/casuela-de-mariscos/paso-completo-03-20261103.webp","image_alt":"Añade el tomate"},{"title":"Cocina el tomate","content":"Cocínalo durante 6 minutos, hasta que esté suave.","image_alt":"Cocina el tomate","image_url":"/recetas/casuela-de-mariscos/paso-03.webp"},{"title":"Añade los líquidos","content":"Añade el agua, la leche de coco y la sal.","image_url":"/recetas/casuela-de-mariscos/paso-completo-05-20261103.webp","image_alt":"Añade los líquidos"},{"title":"Cocina el caldo","content":"Cocina a fuego suave durante 5 minutos.","image_alt":"Cocina el caldo","image_url":"/recetas/casuela-de-mariscos/paso-04.webp"},{"title":"Añade el calamar","content":"Incorpora el calamar al caldo.","image_url":"/recetas/casuela-de-mariscos/paso-completo-07-20261103.webp","image_alt":"Añade el calamar"},{"title":"Cocina el calamar","content":"Mantén un hervor suave durante 15 minutos; prolonga la cocción si aún está firme.","image_alt":"Cocina el calamar","image_url":"/recetas/casuela-de-mariscos/paso-05.webp"},{"title":"Añade el pescado","content":"Incorpora el pescado en cubos.","image_url":"/recetas/casuela-de-mariscos/paso-completo-09-20261103.webp","image_alt":"Añade el pescado"},{"title":"Cocina el pescado","content":"Cocina suavemente durante 5 minutos.","image_alt":"Cocina el pescado","image_url":"/recetas/casuela-de-mariscos/paso-06.webp"},{"title":"Añade los camarones","content":"Incorpora los camarones a la olla.","image_url":"/recetas/casuela-de-mariscos/paso-completo-11-20261103.webp","image_alt":"Añade los camarones"},{"title":"Cocina los camarones","content":"Cocina durante 3–4 minutos, hasta que estén rosados y opacos.","image_alt":"Cocina los camarones","image_url":"/recetas/casuela-de-mariscos/paso-07.webp"},{"title":"Comprueba la cocción","content":"Comprueba que el pescado esté cocido y el calamar tierno.","image_url":"/recetas/casuela-de-mariscos/paso-completo-13-20261103.webp","image_alt":"Comprueba la cocción"},{"title":"Sirve la cazuela","content":"Sirve la cazuela caliente con cilantro, arroz blanco y patacón al gusto.","image_alt":"Sirve la cazuela","image_url":"/recetas/casuela-de-mariscos/paso-08.webp"}]},{"id":"2d11cb00-62b7-4b92-ba8e-d53051fbcb21","expected_steps":[{"title":"Hachez les légumes","content":"Hachez finement l’oignon, le poivron, l’ail et les tomates.","image_alt":"Hachez les légumes","image_url":"/recetas/casuela-de-mariscos/paso-01.webp"},{"title":"Faites revenir les aromates","content":"Faites cuire l’oignon, le poivron et l’ail dans l’huile à feu moyen pendant 5 minutes.","image_alt":"Faites revenir les aromates","image_url":"/recetas/casuela-de-mariscos/paso-02.webp"},{"title":"Ajoutez la tomate","content":"Ajoutez la tomate dans la casserole."},{"title":"Cuisez la tomate","content":"Faites-la cuire 6 minutes jusqu’à ce qu’elle soit tendre.","image_alt":"Cuisez la tomate","image_url":"/recetas/casuela-de-mariscos/paso-03.webp"},{"title":"Ajoutez les liquides","content":"Ajoutez l’eau, le lait de coco et le sel."},{"title":"Faites frémir le bouillon","content":"Laissez frémir doucement pendant 5 minutes.","image_alt":"Faites frémir le bouillon","image_url":"/recetas/casuela-de-mariscos/paso-04.webp"},{"title":"Ajoutez le calmar","content":"Ajoutez le c